// 자동 생성 파일 (v2_secretary/export_panel.py) — 논문 카드 세부(주요 내용·근거 문장). panel_data.js가 클 때만 채움.
window.PANEL_PAPERS = {"2611.20292": {"points": [{"subtitle": "인과 관계 분석과 모델 결합", "desc": "PCMCI 알고리즘으로 시간 흐름에 따른 인과 관계를 찾고, 이를 소신호 상태 공간 모델 분석과 결합했어요. 뭔 소리냐면, 데이터에서 고장의 원인을 추론하고 모델을 통해 시스템의 반응을 수학적으로 확인한다는 말이에요.", "evidence": "This paper proposes an analytical method that combines time-series causal discovery using the Peter and Clark Momentary Conditional Independence (PCMCI) algorithm with right/left eigenvector participation-factor analysis of validated small-signal state-space models."}, {"subtitle": "RCCI 지표를 통한 계획 수립", "desc": "연구진은 RCCI라는 새로운 지표를 정의해서 인과 관계가 전력망 기준에 미치는 영향을 가중치로 계산했어요. 이 지표를 활용해 전압 회복이나 진동 감쇠 같은 여러 기준을 만족하는지 반복적으로 검토하는 겁니다.", "evidence": "A planning index referred to as the Resiliency Causal Contribution Index (RCCI) is defined that weights PCMCI-derived causal effects on a TPL benchmark quantity by modal participation."}, {"subtitle": "연쇄 고장 방지를 위한 반복적 검증", "desc": "다양한 고장 상황을 시뮬레이션하면서 자동으로 보호 조치를 추론하고, 연쇄 고장이 발생하지 않을 때까지 과정을 반복해요. 실제 사례 연구를 통해 이 과정이 전력망 확장 계획을 세우는 데 어떻게 쓰이는지 보여줬습니다.", "evidence": "The process infers automatic protective actions and repeats until a cascade is ruled out or confirmed."}], "easy1_evidence": "Conventional existing TPL-001 contingency analysis will assess if a performance benchmark is violated.", "easy2_evidence": "This paper proposes an analytical method that combines time-series causal discovery using the Peter and Clark Momentary Conditional Independence (PCMCI) algorithm with right/left eigenvector participation-factor analysis of validated small-signal state-space models.", "topic_evidence": "This paper proposes an analytical method that combines time-series causal discovery using the Peter and Clark Momentary Conditional Independence (PCMCI) algorithm with right/left eigenvector participation-factor analysis of validated small-signal state-space models.", "limit_evidence": ""}, "2611.19667": {"points": [{"subtitle": "전압 강하와 전력 불균형", "desc": "전압이 떨어지면 정류기에서 들어오는 전력이 줄어들고, 직류 링크의 전압이 낮아지면서 보호 장치가 작동해 시스템이 멈추게 됩니다. 연구진은 이 문제를 직류 링크의 전력 균형 문제로 정의해서 분석했어요.", "evidence": "Once the rectifier reaches its current limit, the power drawn from the grid decreases in proportion to the grid voltage."}, {"subtitle": "세 가지 제어 시나리오", "desc": "UPS 배터리만 사용하는 경우, 컴퓨팅 부하만 줄이는 경우, 그리고 이 둘을 함께 조율하는 경우를 나누어 시뮬레이션을 진행했습니다. 각 자원을 어떻게 활용하느냐에 따라 전압 강하를 견디는 능력이 달라지거든요.", "evidence": "Three control scenarios are studied: UPS battery support alone, computing load curtailment alone, and the coordinated use of both resources."}, {"subtitle": "시뮬레이션 결과 확인", "desc": "TAMU-ERCOT 모델을 사용해 전자기 과도 현상(EMT) 시뮬레이션을 해봤더니, 배터리와 부하 조절을 함께 쓰는 방식이 전압이 거의 0인 상황까지 포함한 모든 테스트에서 성공적으로 버텨냈습니다. 부하만 줄이는 방식은 중간 정도의 전압 강하만 견딜 수 있었다고 연구진은 밝혔어요.", "evidence": "Electromagnetic transient (EMT) simulations using the TAMU-ERCOT AI data center model demonstrate that battery support and the coordinated strategy achieve LVRT for all tested sags, including a near-zero-voltage fault, while load curtailment alone rides through moderate voltage sags."}], "easy1_evidence": "The ability of large AI data centers to ride through grid voltage sags is critical to power system stability and reliability.", "easy2_evidence": "To address this issue, this paper proposes effective control strategies for coordinating uninterruptible power supply (UPS) battery and computing load curtailment to offset the power deficit and enable LVRT at minimum control cost.", "topic_evidence": "This paper frames data center low-voltage ride-through (LVRT) as a DC-link power balance problem.", "limit_evidence": ""}, "2611.19397": {"points": [{"subtitle": "다중 속도 제어 구조", "desc": "각 보조 서비스가 가진 고유한 업데이트 속도를 유지하면서도, 서로 다른 응답 특성을 가진 분산 에너지 자원(DER)들을 하나의 틀 안에서 조율하도록 설계했어요. 뭔 소리냐면, 서비스마다 제어 주기가 달라도 이를 통합적으로 관리할 수 있는 구조를 만들었다는 말이에요.", "evidence": "Furthermore, the input-multirate structure enables coordinated ancillary service provision by DERs with different response dynamics."}, {"subtitle": "시간 가변적 유연성 반영", "desc": "전기차나 온도 조절 부하가 있는 건물처럼 시간이 지나면서 쓸 수 있는 에너지가 변하는 자원들을 위해 전력-에너지 포락선 개념을 도입했어요. 이를 통해 현재의 제어 응답이 미래의 자원 가용성에 미치는 영향까지 고려해서 최적화를 수행한다는 겁니다.", "evidence": "To account for the intertemporal flexibility of electric vehicle aggregations and aggregations of buildings with thermostatically controlled loads (TCLs), we incorporate time-varying power-energy envelopes into our multi-rate MPC formulation."}, {"subtitle": "시뮬레이션 성능 검증", "desc": "수정된 IEEE 33-버스 시스템을 대상으로 비선형 미분-대수 모델을 사용해 폐루프 시뮬레이션을 진행했는데요. 그 결과 세 가지 보조 서비스가 통합적으로 잘 작동하며 조화롭게 제공될 수 있음을 확인했다고 연구진은 밝혔습니다.", "evidence": "We demonstrate the coordinated provision of the three ancillary services through closed-loop simulations on a modified IEEE 33-bus system using a nonlinear differential-algebraic model."}], "easy1_evidence": "The framework allocates distributed energy resource (DER) flexibility among these three ancillary services while retaining their different update rates.", "easy2_evidence": "The controller optimizes the three services together, allowing fast regulation to be coordinated with the developing slow response within the available DER flexibility.", "topic_evidence": "We propose a multi-rate model predictive control (MPC) framework for coordinating primary frequency control (PFC), automatic generation control (AGC), and voltage control (VC) in active distribution networks.", "limit_evidence": ""}, "2611.21072": {"points": [{"subtitle": "과학 데이터 인지 구조", "desc": "분자 그래프나 생물학적 서열을 처리하기 위해 전용 인코더를 사용하고, 스펙트럼 데이터는 측정값의 패치로 변환해서 처리해요. 이렇게 모달리티별로 만든 표현을 공유 백본(핵심 처리부)의 입력 공간으로 매핑해서 텍스트나 이미지와 함께 학습하는 방식이에요.", "evidence": "Sage Sci-Perception uses dedicated encoders for molecular graphs and biological sequences and represents spectra as ordered patches of measurements."}, {"subtitle": "에이전트 능력 검증", "desc": "모델이 도구를 사용하거나 검색, 코딩을 수행할 수 있도록 검증 가능한 환경을 구축했어요. 과제가 제대로 끝났는지는 실제 실행 결과나 환경의 상태 변화, 혹은 제출된 결과물을 통해 확인하는 구조예요.", "evidence": "Task completion is checked against execution results, changes in environment state, or submitted artifacts."}, {"subtitle": "벤치마크 성능 결과", "desc": "7개 영역의 33개 벤치마크에서 평가한 결과, OfficeQA Pro(72.2)와 MLE-bench Lite(90.3 HumanRank) 등에서 1위를 기록했어요. 문서 증거 활용과 머신러닝 작업에서 뛰어난 성능을 보였고, 시각적 피드백이 필요한 데스크톱이나 브라우저 작업에서도 경쟁력 있는 모습을 보여줬다고 연구진은 밝혔어요.", "evidence": "In the primary comparison against five baselines, it ranks first on OfficeQA Pro (72.2), MLE-bench Lite (90.3 HumanRank), Harvey LAB, and SpreadsheetBench~2, and second on OSWorld-Verified (85.2), WebArena-Verified (67.6), and DeepResearch Bench~II (54.2)."}], "easy1_evidence": "We introduce Sage S1.5 Flash, a 320-billion-parameter general-purpose mixture-of-experts model designed to reason over scientific evidence and act in interactive environments.", "easy2_evidence": "To develop the model's agent capabilities, we construct verifiable environments for tool use, search, and coding, as well as specialized workflows involving machine learning experiments and scientific software.", "topic_evidence": "We introduce Sage S1.5 Flash, a 320-billion-parameter general-purpose mixture-of-experts model designed to reason over scientific evidence and act in interactive environments.", "limit_evidence": ""}, "2611.21003": {"points": [{"subtitle": "모델 구조 혁신", "desc": "추론 능력을 높이기 위해 어텐션 값에 MoE를 적용한 MoVA와 이론적으로 더 유연한 softplus attention gating을 도입했습니다. 이 기술들을 활용해 모델의 파라미터 효율성을 크게 개선했다고 연구진은 주장했어요.", "evidence": "On the modeling side, to strengthen reasoning, we introduce Mixture-of-Value Attention (MoVA), applying MoE to attention value projections, and softplus attention gating, a more flexible, theoretically motivated gate."}, {"subtitle": "디코딩 속도 향상", "desc": "Uno라고 불리는 손실 없는 확산 어댑터를 도입하여 디코딩 속도를 최대 2.2배까지 높였습니다. 별도의 초안 모델 없이도 속도를 개선할 수 있다는 점이 특징이에요.", "evidence": "We also introduce Uno, lossless diffusion adapters that speed up decoding by up to 2.2x without a separate draft model."}, {"subtitle": "투명한 오픈 소스 공개", "desc": "LLM360 기준에 따라 학습 데이터, 로그, 코드, 중간 체크포인트 등 개발 과정의 모든 정보를 공개했습니다. 특히 약 10T 규모의 합성 데이터를 활용해 대규모 사전 학습이 가능하다는 점을 보여줬어요.", "evidence": "These pipelines produced roughly 10T synthetic pre-training tokens, showing that synthetic data can be a major ingredient of pre-training at scale."}], "easy1_evidence": "We present K2-Horizon, a fleet of six fully open language models, from a 0.9B dense model to a 375B-A23B MoE, built for general-purpose reasoning and agentic work across math and science, software engineering, deep research, office automation, and beyond.", "easy2_evidence": "Our 36B-A4B model uses both and nearly matches a 32B dense model trained on the same data, with one-seventh the active parameters.", "topic_evidence": "Our release follows the LLM360 definition of open source for transparency and reproducibility: the full development history, including intermediate checkpoints from every training stage, pre-training data, training logs, and all training, evaluation, and infrastructure code, notably our production-scale xLLM framework for dense and MoE training and the RL360 reinforcement-learning stack.", "limit_evidence": ""}, "2611.20534": {"points": [{"subtitle": "가격 기반 조율 알고리즘 개발", "desc": "균형점을 찾기 위해 투영된 애로우-후르비츠-우자와(Arrow-Hurwicz-Uzawa) 방식을 기반으로 한 분산 최적화 알고리즘을 만들었어요. 이 방식은 복잡하게 얽힌 프로슈머들의 결정을 효율적으로 조율하는 역할을 합니다.", "evidence": "To compute the equilibrium, a distributed optimization algorithm is developed based on the projected Arrow-Hurwicz-Uzawa scheme."}, {"subtitle": "수렴 속도 보장", "desc": "연구진은 알고리즘이 안정적으로 작동하도록 명시적인 단계 크기 규칙을 개발했는데요, 이를 통해 에르고딕 수렴 속도가 O(1/√L)과 O(1/L) 수준임을 보장했다고 주장했어요. 계산 과정에서 수렴이 얼마나 빠르게 일어나는지를 수학적으로 증명한 겁니다.", "evidence": "Explicit step-size rules are developed for the algorithm to guarantee $\\mathcal{O}(1/\\sqrt{L})$ and $\\mathcal{O}(1/L)$ ergodic convergence rates."}, {"subtitle": "IEEE 33-bus 시스템 검증", "desc": "프로슈머와 전기차 플릿이 연결된 IEEE 33-bus 배전망에서 시뮬레이션을 수행해 제안한 방법의 정확성과 효율성을 확인했어요. 실제 전력망 환경과 유사한 조건에서 알고리즘이 잘 작동함을 보여준 셈이에요.", "evidence": "Simulations on an IEEE 33-bus feeder that is connected to prosumers and electric vehicle fleets validate the accuracy and efficacy of the proposed methods."}], "easy1_evidence": "Price-based distributed prosumer coordination in distribution networks is fundamentally challenging when the aggregator pursues grid-level goals that couple prosumers' decisions, because the Lagrangian fails to separate and nodal prices are undefined under conventional dual decomposition.", "easy2_evidence": "This paper develops a novel method that embeds mixed competitive-cooperative objectives exactly into prices, which are split into energy, congestion, and grid-objective components, closing the gap between the social welfare optimum and the competitive equilibrium.", "topic_evidence": "Social Welfare and Equilibrium in Distributed Microgrid Prosumer Coordination Under a Mixed Competitive-Cooperative Setting", "limit_evidence": ""}, "2611.20116": {"points": [{"subtitle": "연산과 에너지의 통합 가격 산정", "desc": "연산 비용과 에너지 비용을 하나의 최적화 문제로 묶어 가격을 매겼는데요. 이렇게 하면 전력망의 제약 조건이 가격에 바로 반영되거든요. 뭔 소리냐면, 전력망이나 하드웨어 등 어떤 요소가 비용 상승을 유발하는지 구체적으로 파악할 수 있다는 말이에요.", "evidence": "The resulting compute price reflects the marginal cost of the binding constraints and decomposes into components indicating which grid, power, hardware, or service requirement causes a price surge."}, {"subtitle": "실시간 경제적 신호 제공", "desc": "계산된 가격은 실시간 상황을 반영해서 사용자에게 전달되는데요. 사용자는 이 신호를 보고 자신의 작업 유연성을 어떻게 조절할지 결정할 수 있어요. 전력망이 힘들 때 연산 작업을 조정하도록 유도하는 경제적 지표 역할을 하는 겁니다.", "evidence": "The economic interpretation updates the price with real-time conditions and gives users a signal for potential flexibility provision."}, {"subtitle": "시장 간의 연결과 자원 효율화", "desc": "연구진은 이 방식이 연산 시장과 에너지 시장을 하나로 잇는 가교가 된다고 주장했는데요. 결과적으로 전력망의 부담을 줄이면서 데이터 센터의 연산 자원도 효율적으로 관리할 수 있게 된다는 거예요. 전력망과 컴퓨팅 자원 양쪽 모두에 긍정적인 신호를 준다는 점이 특징입니다.", "evidence": "The co-optimization ultimately connects compute and energy markets while providing a signal for relief of stress on both the grid and the compute resources."}], "easy1_evidence": "Demand from data centers and AI compute is growing rapidly and is increasing stress on the power grid.", "easy2_evidence": "In this work, we propose to quantify and couple the prices of compute and energy in a single optimization problem.", "topic_evidence": "In this work, we propose to quantify and couple the prices of compute and energy in a single optimization problem.", "limit_evidence": ""}, "2611.19046": {"points": [{"subtitle": "최적화 문제 정의", "desc": "전압 강하 상황에서 전력 공급을 유지하는 통과 시간을 최대화하기 위해, 전압 범위에 따른 통과 시간의 적분값을 통과 영역으로 정의하고 이를 최대화하는 최적화 문제를 수립했어요.", "evidence": "We formulate a bound-constrained optimization problem to maximize the ride-through area, defined as the integral of ride-through time over a range of retained grid voltages."}, {"subtitle": "BPZO-Adam 알고리즘 개발", "desc": "제어 설정을 찾기 위해 시뮬레이션 결과만을 활용하는 BPZO-Adam 알고리즘을 개발했는데요. 이 방식은 제조사가 제공하는 블랙박스 형태의 모델에도 바로 적용할 수 있다는 특징이 있어요.", "evidence": "The algorithm evaluates candidate control settings using only simulated ride-through times, making it suitable for vendor-supplied black-box models."}, {"subtitle": "성능 개선 확인", "desc": "TAMU-ERCOT 모델을 통해 실험한 결과, 제어 파라미터를 튜닝했을 때 통과 영역이 10.6% 증가했음을 확인했어요. 또한 커패시턴스를 10배 늘리는 물리적 변경보다 제어 튜닝이 더 효과적이었다고 밝혔습니다.", "evidence": "In a separate study, tuning the controls yields a larger ride-through area than increasing the DC-link capacitance tenfold."}], "easy1_evidence": "Voltage sags can trigger protection trips in uninterruptible power supply (UPS) systems, abruptly reducing the power that AI data centers draw from the grid.", "easy2_evidence": "Simulations using the TAMU-ERCOT electromagnetic transient (EMT) AI data center model show that tuning converter control parameters increases the ride-through area by 10.6%.", "topic_evidence": "This paper improves the low-voltage ride-through (LVRT) capability of AI data centers equipped with double-conversion UPS systems by tuning their existing converter controls.", "limit_evidence": ""}, "2611.18986": {"points": [{"subtitle": "기존 지표의 한계", "desc": "기존의 전력망 성능 평가 지표들은 인버터 기반 자원이 급증하는 현재의 전력망 환경을 충분히 설명하지 못한다는 문제가 있는데요, 특히 전력망의 안정성을 결정짓는 감쇠 특성을 반영하는 데 부족함이 있다는 거예요.", "evidence": "With the growth of inverter based resources, these mostly conventional metrics and indices may not encompass all important elements and variables that hold information about the grid performance, especially the damping properties."}, {"subtitle": "AGI 지표의 도입", "desc": "연구진은 유체역학의 레이놀즈 수 개념을 차용해 전력망의 관성과 감쇠 비율을 연결하는 AGI 지표를 새롭게 고안했어요. 관성이 낮아지는 전력망 환경에서 두 요소를 함께 모니터링하는 것이 필수적이라고 본 겁니다.", "evidence": "With the current trends towards high-power inverter assets and reduced-inertia grids, explicit attention is necessary in monitoring inertia and damping together."}, {"subtitle": "동적 성능 평가의 통찰", "desc": "이 논문은 AGI 지표를 통해 전력망의 동적 성능이 어떻게 나타나는지에 대한 분석 결과를 공유하고 있는데요, 이를 통해 복잡해지는 전력망의 상태를 더 명확하게 파악할 수 있다고 주장했어요.", "evidence": "This paper shares insights the AGI presents about the dynamic performance of power systems."}], "easy1_evidence": "With the growth of inverter based resources, these mostly conventional metrics and indices may not encompass all important elements and variables that hold information about the grid performance, especially the damping properties.", "easy2_evidence": "This paper proposes the Agility Index (AGI), which is a Reynolds number-inspired metric for power system dynamics relating the ratio of inertia to damping.", "topic_evidence": "This paper proposes the Agility Index (AGI), which is a Reynolds number-inspired metric for power system dynamics relating the ratio of inertia to damping.", "limit_evidence": ""}, "2611.19937": {"points": [{"subtitle": "교차 자산 트랜스포머 활용", "desc": "AllocFlow는 시장의 시간적 흐름을 반영한 데이터를 바탕으로 여러 자산 간의 의존성을 파악하는데요, 이를 통해 모든 자산에 대한 연속적인 포지션 가중치를 한꺼번에 생성하는 구조예요. 뭔 소리냐면, 자산 하나하나를 따로 보는 게 아니라 전체 포트폴리오의 균형을 고려해 배분한다는 말이에요.", "evidence": "To capture dependencies among portfolio positions, AllocFlow employs a cross-asset flow Transformer conditioned on temporal market representations to generate continuous, signed position weights across all instruments jointly."}, {"subtitle": "2단계 학습 전략", "desc": "학습의 효율을 높이기 위해 먼저 전략을 모방하는 학습으로 후보 포트폴리오의 틀을 잡고, 그 뒤에 그룹 단위의 강화학습을 통해 실제 금융 수익을 바탕으로 결정을 다듬는 방식을 썼어요. 이렇게 하면 처음부터 무작정 배우는 것보다 훨씬 안정적이고 효율적으로 정책을 만들 수 있다는 거예요.", "evidence": "To address the sample inefficiency and instability of learning continuous allocation policies from scratch, we establish a two-stage training scheme: strategy-supervised imitation shapes a structured distribution of candidate portfolios, followed by group-relative reinforcement learning (RL) that refines joint decisions using portfolio-level financial rewards and a frozen policy reference."}, {"subtitle": "실제 시장 성능 검증", "desc": "시간 단위 암호화폐 선물 데이터로 실험해 보니, 강화학습을 거친 모델이 기존 모방 학습보다 모든 지표에서 더 나은 성과를 냈는데요, 특히 2026년의 새로운 데이터 6개월치에서도 재학습 없이 칼마 지수 4.90을 기록했다고 밝혔어요.", "evidence": "On hourly cryptocurrency perpetual futures, RL refinement raises the annualized net return of the imitation policy from 27.79% to 51.38% and its Calmar ratio from 0.955 to 4.043, surpassing the teacher strategy on every metric, and AllocFlow reaches a Calmar ratio of 4.90 on six further months of unseen 2026 data without retraining."}], "easy1_evidence": "However, traditional pipelines often decouple signal forecasting from portfolio construction, potentially misaligning learning with allocation and execution objectives.", "easy2_evidence": "We present AllocFlow, an end-to-end flow-matching framework that directly generates joint portfolio allocations from raw multi-asset market histories.", "topic_evidence": "We present AllocFlow, an end-to-end flow-matching framework that directly generates joint portfolio allocations from raw multi-asset market histories.", "limit_evidence": ""}, "2611.21218": {"points": [{"subtitle": "인클루전메드 아틀라스 구축", "desc": "연구진은 의료 현장에서 필요한 세 가지 역할과 AI의 세 가지 능력을 조합해 평가 체계를 만들었습니다. 이 체계는 구조적인 감사와 재현 과정을 거쳐 선정된 5개의 벤치마크로 구성되어 있는데요, 의료 AI가 얼마나 넓은 범위의 요구를 충족하는지 측정하는 틀이라고 보시면 됩니다.", "evidence": "The InclusionMed Atlas organizes benchmarks across three healthcare roles and three AI capabilities."}, {"subtitle": "AI 모델 성능 평가 결과", "desc": "최신 거대 언어 모델(LLM)들을 이 체계로 평가했더니 전체 점수는 100점 만점에 17.5점에서 49.1점 사이로 나타났습니다. 모델마다 강점이 있는 역할이나 능력이 달라서, 어떤 기준을 적용하느냐에 따라 순위가 뒤바뀌는 현상이 확인된 거예요.", "evidence": "We evaluated frontier large language models on the Atlas and aggregated their results into the InclusionMed Index, with overall scores ranging from 17.5 to 49.1 out of 100."}, {"subtitle": "임상 결정과 소통 능력의 차이", "desc": "세부 분석을 해보니 상위권 모델들은 임상적인 결정을 내리는 능력보다 환자와 소통하는 능력에서 더 좋은 성적을 거뒀습니다. 또한 비슷한 점수를 받은 모델이라도 실제 추론에 드는 비용은 크게 달랐는데요, 이는 의료 현장의 필요에 따라 모델을 신중하게 골라야 한다는 점을 시사합니다.", "evidence": "A within-benchmark analysis using task-level tags showed that the ten highest-ranked models in the Index all scored higher on patient communication than on clinical decision-making."}], "easy1_evidence": "Advancing medical AI for inclusive healthcare requires evaluation across diverse healthcare roles, tasks, and care settings, but benchmark coverage remains uneven.", "easy2_evidence": "We evaluated frontier large language models on the Atlas and aggregated their results into the InclusionMed Index, with overall scores ranging from 17.5 to 49.1 out of 100.", "topic_evidence": "We introduce InclusionMed, an open medical AI evaluation initiative for inclusive healthcare.", "limit_evidence": ""}, "2611.07222": {"points": [{"subtitle": "데이터 형식 기반의 차단", "desc": "도구의 출력값에서 사용자가 요청하지 않은 대상이 포함되어 있는지 확인하는데요, 읽기 전용 도구에서 나온 형식화된 필드나 정해진 위임 규칙에 맞는 경우에만 호출을 허용하는 방식이에요. 뭔 소리냐면, 데이터의 출처와 형식을 따져서 공격자가 심어둔 가짜 명령을 걸러낸다는 말이에요.", "evidence": "The check admits a call when each target value that appears in tool output but not in the user's task was returned by a read-only tool in a typed field or is covered by a fixed delegation rule."}, {"subtitle": "명령어 정화 및 증거 보존", "desc": "결정론적 정화기(sanitizer)가 모델이 읽기 전에 명령어처럼 보이는 부분을 미리 제거하는데요, 이때 삭제된 부분은 증거로 남겨두고 로컬 판단기가 거부된 호출을 복구할지 결정하게 했어요. 하지만 삭제된 텍스트에 포함된 공격 대상은 절대 복구하지 않도록 설계해서 보안을 강화한 셈이에요.", "evidence": "A deterministic sanitizer removes instruction-like regions its fixed rules match before the model reads them and retains the removed spans as evidence, and a local judge may restore a refused call, never one whose target lies in the removed text."}, {"subtitle": "성능 저하 없는 방어 효율", "desc": "세 가지 백본 모델과 일곱 가지 작업 환경에서 실험해 보니, 표준적인 템플릿 공격을 모두 막아내면서도 가장 높은 유용성 점수를 기록했다고 해요. 특히 방어를 위해 모델을 다시 실행하거나 추가적인 모델 호출이 거의 필요 없다는 점이 큰 장점이에요.", "evidence": "SPILLWAY reaches this floor with no defense-triggered backbone re-run and almost no added model call."}], "easy1_evidence": "Tool-using agents act on email, files, and payments, so an instruction hidden in a web page or a shared document can make an agent send data or money to an attacker.", "easy2_evidence": "SPILLWAY turns this observation into a deterministic floor with no per-task plan.", "topic_evidence": "SPILLWAY: Separating Target Admission from Sanitization to Defend Tool-Using Agents against Prompt Injection", "limit_evidence": ""}, "2611.21513": {"points": [{"subtitle": "안전 보장을 위한 장벽 함수", "desc": "추정 오차가 미리 정해진 임계값 안에 머무르는 한 시스템의 안전을 보장하는 강건한 장벽 함수 조건을 세웠어요. 이 조건을 통해 에이전트가 네트워크에서 연결을 끊어도 안전하다는 사실을 수학적으로 증명했거든요.", "evidence": "We establish a robust barrier function condition that guarantees safety as long as the estimation error remains within a prescribed threshold."}, {"subtitle": "계산 복잡도 개선", "desc": "각 에이전트가 로컬에서 계산 가능한 인증서를 사용해 연결 여부를 결정하도록 만들었어요. 이 방식은 에이전트 수 N에 비례하는 계산량만 필요로 해서, 기존의 지수적 계산 방식보다 훨씬 효율적이라는 거예요.", "evidence": "The certificate construction improves scalability by reducing the complexity of topology-dependent computations from $O(2^N)$ to $O(N)$, where $N$ is the number of agents."}, {"subtitle": "마이크로그리드 성능 평가", "desc": "4개의 상호 연결된 마이크로그리드 환경에서 프로토콜을 직접 실험해 봤는데요, 항상 네트워크를 연결해 두는 방식과 비교했을 때 통신 연결 시간을 줄이면서도 위상과 주파수를 안전하게 유지할 수 있었다고 밝혔어요.", "evidence": "Compared with maintaining network connectivity at all times, the protocol reduces the time agents remain connected while keeping phase and frequency within their safe operating region."}], "easy1_evidence": "This paper develops a decentralized event-triggered topology-switching protocol that allows agents to disconnect from the communication network while preserving state safety and excluding Zeno behavior.", "easy2_evidence": "The certificate construction improves scalability by reducing the complexity of topology-dependent computations from $O(2^N)$ to $O(N)$, where $N$ is the number of agents.", "topic_evidence": "This paper develops a decentralized event-triggered topology-switching protocol that allows agents to disconnect from the communication network while preserving state safety and excluding Zeno behavior.", "limit_evidence": ""}, "2611.21346": {"points": [{"subtitle": "고조파 최적 전력 흐름 기법", "desc": "ESS의 충·방전과 고조파 전류 보상을 하나의 체계 안에서 동시에 스케줄링하는 고조파 최적 전력 흐름(HOPF) 방식을 설계했어요. ESS가 가진 컨버터의 전류 정격 안에서 배터리 상태까지 고려해 효율적으로 움직이게 만든 거예요.", "evidence": "ESS charging, discharging and harmonic-current compensation are jointly scheduled under state-of-charge dynamics and a shared converter-current rating."}, {"subtitle": "의사결정 나무 기반의 모델링", "desc": "전력 흐름 운영 지점을 학습해 전압과 전류의 영역을 나누는 적응형 의사결정 나무를 도입했는데요, 각 영역에서 평면을 찾아내고 이를 수학적으로 검증된 하위 포락선으로 활용했어요. 이 모델을 2차 원뿔 완화 네트워크 모델에 결합해 계산의 복잡도를 줄인 겁니다.", "evidence": "An adaptive decision tree learns voltage-current partitions from OPF operating points."}, {"subtitle": "연간 데이터 기반의 성능 검증", "desc": "1년 치 시간별 데이터를 바탕으로 매일 용량을 최적화하고, 전체 기간에 걸쳐 실제로 가능한지 검증하는 과정을 거쳤어요. 그 결과 고조파 제한으로 손실되었던 용량을 ESS의 컨버터 정격 범위 내에서 완전히 회복할 수 있음을 확인했다고 연구진은 주장했어요.", "evidence": "Coordinated energy dispatch and harmonic compensation thus recover generation capacity within the installed ESS converter ratings."}], "easy1_evidence": "Active distribution networks increasingly rely on coordinated inverter-based resources to accommodate renewable generation, while harmonic limits constrain the capacity that can be connected.", "easy2_evidence": "With each generator capacity bounded by its OPF reference, the proposed method recovers the complete reference allocation.", "topic_evidence": "This paper proposes a harmonic optimal power flow (HOPF) method with active energy-storage-system (ESS) support.", "limit_evidence": ""}, "2611.21313": {"points": [{"subtitle": "강건한 네트워크 축소 모델", "desc": "기존 Opti-KRON 방식에 강건한 불확실성 집합과 바서슈타인 모호성 집합을 결합해서, 전력 주입이 변하더라도 전압 크기 오차를 보장할 수 있게 만들었어요. 뭔 소리냐면, 어떤 상황이 닥쳐도 모델이 원래 망의 특성을 잘 유지하도록 설계했다는 말이에요.", "evidence": "This paper extends Opti-KRON to uncertain nodal injections using robust uncertainty sets and a Wasserstein ambiguity set, with voltage magnitude error guarantees."}, {"subtitle": "계산 효율성 개선", "desc": "모델을 줄일 때 불필요한 제약 조건과 변수를 미리 걸러내는 사전 선별 단계를 도입했는데요, 동시에 적대적 제약 조건 생성 방식을 써서 메모리 요구량을 크게 낮췄어요. 최악의 전력 주입 사례를 반복적으로 추가하면서도 전체 계산 효율을 챙긴 셈이에요.", "evidence": "To improve scalability, we develop a presolve screening step to eliminate redundant constraints and variables while preserving the feasible set."}, {"subtitle": "실제 전력망 적용 결과", "desc": "8,387개 노드로 구성된 실제 배전망에 적용해 본 결과, 0.001 p.u. 임계값에서 전체 노드의 49.9%를 제거하는 성과를 보였어요. 메모리 사용량 또한 18배 이상 줄어드는 효과가 나타났다고 연구진은 주장했습니다.", "evidence": "On a real 8,387-node feeder at a threshold of 0.001~p.u., the reduction removes 49.9% of the nodes."}], "easy1_evidence": "Under unseen nodal injections, however, its accuracy can drop.", "easy2_evidence": "This paper extends Opti-KRON to uncertain nodal injections using robust uncertainty sets and a Wasserstein ambiguity set, with voltage magnitude error guarantees.", "topic_evidence": "This paper extends Opti-KRON to uncertain nodal injections using robust uncertainty sets and a Wasserstein ambiguity set, with voltage magnitude error guarantees.", "limit_evidence": ""}, "2611.21257": {"points": [{"subtitle": "기존 판독 방식의 한계", "desc": "기존에는 센서를 자극하고 다시 멈추는 과정을 반복하는 방식으로 주파수를 측정했는데요, 이 방식은 센서가 멈추는 시간 때문에 측정의 정밀도와 대역폭 범위가 제한된다는 단점이 있었거든요. 뭔 소리냐면, 신호를 계속해서 읽어내지 못하고 띄엄띄엄 확인해야 했다는 말이에요.", "evidence": "Existing systems estimate this frequency from repeated cycles of excitation and ring-down, which limits the precision and bandwidth range."}, {"subtitle": "위상 고정 루프 기반의 연속 판독", "desc": "연구진은 위상 고정 루프를 도입해 센서의 신호를 끊김 없이 연속적으로 읽어내는 방식을 구현했는데요, 이를 통해 센서가 멈추기를 기다릴 필요 없이 실시간으로 위상을 유지하며 주파수를 파악할 수 있게 된 겁니다.", "evidence": "Here, we introduce a continuous, phase-coherent readout based on a phase-locked loop."}, {"subtitle": "실험을 통한 성능 검증", "desc": "실험 환경에서 이 방식을 적용해 봤더니, 30년이 넘는 대역폭 범위 내에서 정밀도와 대역폭 한계의 4% 이내 수준을 유지하는 결과를 보였거든요. 반면 기존 방식은 이 한계치보다 4배 정도 높은 수준에 머물렀다는 점을 고려하면, 이번 방식이 훨씬 정밀하다는 것을 알 수 있습니다.", "evidence": "In a benchtop setup, one record stayed within 4 % of the precision-bandwidth limit over more than three decades of bandwidth, while conventional readouts remained about a factor of 4 above it."}], "easy1_evidence": "Existing systems estimate this frequency from repeated cycles of excitation and ring-down, which limits the precision and bandwidth range.", "easy2_evidence": "Here, we introduce a continuous, phase-coherent readout based on a phase-locked loop.", "topic_evidence": "Here, we introduce a continuous, phase-coherent readout based on a phase-locked loop.", "limit_evidence": ""}, "2611.21144": {"points": [{"subtitle": "하이브리드 오토마타 모델링", "desc": "데이터 센터의 전력 차단과 복구 과정을 전압 기준과 타이머에 의해 제어되는 하이브리드 동적 시스템으로 정의했습니다. 이를 통해 전력망의 교란 상황에서 발생하는 부하의 비연속적인 동작을 수학적으로 표현할 수 있게 된 겁니다.", "evidence": "The Power Electronic Reconnecting and Ceasing (PERC1) load model represents the timed ceasing and reconnection of large power-electronic loads, including data centers."}, {"subtitle": "4단계 매개변수 식별 절차", "desc": "모드 순서 식별부터 논리 매개변수 추정, 그리고 가우스-뉴턴 정교화 과정을 거치는 4단계 절차를 제안했습니다. 특히 하이브리드 궤적 민감도와 점프 행렬을 사용하여 모델의 정확도를 높이는 방식을 취했습니다.", "evidence": "We propose a four-stage identification procedure: mode-sequence identification, estimation of logic parameters from event-time constraints, and joint Gauss-Newton refinement using hybrid trajectory sensitivities and saltation matrices."}, {"subtitle": "매개변수 식별 가능성 분석", "desc": "전압 강하가 한 번만 발생하면 지연 시간과 같은 매개변수를 완전히 구분하기 어렵다는 점을 수학적으로 증명했습니다. 서로 다른 전압 기울기를 가진 두 번의 교란이 있어야만 모든 매개변수를 정확히 식별할 수 있다는 결론을 내렸습니다.", "evidence": "Two structural results are established. The detection and actuation delays are identifiable only through their sum unless a second dip interrupts the reconnection ramp, and a single disturbance leaves one unidentifiable direction in each threshold-delay pair, which two disturbances with different voltage slopes resolve."}], "easy1_evidence": "The Power Electronic Reconnecting and Ceasing (PERC1) load model represents the timed ceasing and reconnection of large power-electronic loads, including data centers.", "easy2_evidence": "We propose a four-stage identification procedure: mode-sequence identification, estimation of logic parameters from event-time constraints, and joint Gauss-Newton refinement using hybrid trajectory sensitivities and saltation matrices.", "topic_evidence": "This paper formulates PERC1 as a hybrid automaton and uses that structure to identify its parameters from synchrophasor records of grid disturbances.", "limit_evidence": "The detection and actuation delays are identifiable only through their sum unless a second dip interrupts the reconnection ramp, and a single disturbance leaves one unidentifiable direction in each threshold-delay pair, which two disturbances with different voltage slopes resolve."}, "2611.21017": {"points": [{"subtitle": "국소적 동차 PID 알고리즘 개발", "desc": "기존 선형 PID 제어기의 이득을 출력값과 그 미분값에 따라 스케일링하는 방식으로 알고리즘을 개선했습니다. 이를 통해 제어기는 시스템 상태에 따라 유연하게 반응할 수 있게 되는데요. 동차 정도를 0으로 설정하면 기존 선형 PID와 동일하게 작동하는 특징이 있습니다.", "evidence": "The homogeneous algorithm is obtained by means of the scaling the gains of the linear controller dependently of the current value of the output and its derivative."}, {"subtitle": "실험을 통한 성능 검증", "desc": "연구진은 보이스 코일 모터와 노이즈가 있는 비접촉식 출력 측정 장치를 갖춘 선형 모션 스테이지 시스템에서 실험을 진행했습니다. 이를 임계 주파수 대역에서 루프 셰이핑(loop-shaping) 기법으로 설계된 표준 PID 제어와 비교했는데요. 실험 결과, 제안한 방식이 더 나은 제어 품질을 보여준다고 밝혔습니다.", "evidence": "The experiments are accomplished on a linear-motion stage system with voice-coil-motor and noisy contactless output measurements."}, {"subtitle": "제어 품질 최적화", "desc": "기존 선형 PID 제어기의 이득을 그대로 활용하면서도 국소적 동차 정도를 추가로 튜닝하여 성능을 높였습니다. 이는 고정된 이득을 사용하는 기존 방식보다 정밀한 제어가 가능하게 만드는데요. 결과적으로 더 안정적이고 정밀한 모션 제어 시스템을 구현할 수 있게 된 셈입니다.", "evidence": "The homogeneous PID shares the gains with linear PID while the tuning of local homogeneity degrees could allow better regulation quality comparing with the linear algorithm."}], "easy1_evidence": "A method for upgrading linear PID controller to a locally homogeneous PID regulator is developed.", "easy2_evidence": "The homogeneous algorithm is obtained by means of the scaling the gains of the linear controller dependently of the current value of the output and its derivative.", "topic_evidence": "A method for upgrading linear PID controller to a locally homogeneous PID regulator is developed.", "limit_evidence": ""}, "2611.20985": {"points": [{"subtitle": "최적화와 시뮬레이션의 결합", "desc": "전력 흐름 근사치와 볼록 최적화(convex optimization)를 통해 유망한 행동을 먼저 선별합니다. 그 후 짧은 기간의 시뮬레이션을 수행해 혼잡도와 재생에너지 낭비, 재급전 비용에 미칠 영향을 예측하는 방식이에요.", "evidence": "Power-flow approximations and convex optimization identify the most promising actions, followed by short-horizon simulations to predict their effect on congestion, renewable curtailment, and redispatching costs."}, {"subtitle": "공격 프로토콜을 활용한 전략", "desc": "챌린지의 특정 공격 프로토콜을 이용해 성능을 높였는데요, 특정 송전선을 미리 끊어두는 방식을 썼습니다. 이렇게 하면 적대적인 고장이 발생하는 것을 사전에 방지할 수 있다는 거예요.", "evidence": "A further policy exploits the benchmark's specific attack protocol: keeping selected lines disconnected prevents some adversarial outages from being initiated."}, {"subtitle": "실시간 제어 성능 검증", "desc": "118개 버스망 환경에서 208개 시나리오 중 189개를 성공적으로 완수하며 64.39점을 기록했습니다. 학습된 규칙 없이도 구조화된 최적화와 시뮬레이션만으로 충분히 빠르고 효과적인 제어가 가능하다는 점을 입증한 셈이에요.", "evidence": "On the benchmark's $118$-bus network, the controller completed $189$ of $208$ final-test scenarios (score $64.39$) and achieved the second-best ratio of score to computation time among the five top-ranked entries, behind one that scored lower."}], "easy1_evidence": "Operating transmission networks under uncertain outages requires coordinating discrete network topology actions with continuous adjustments to generation and storage, while respecting operational constraints and real-time computational limits.", "easy2_evidence": "We present a rollout-based controller that combines discrete and continuous decisions under the uncertain contingency policy of the L2RPN AI4RealNet 2026 challenge.", "topic_evidence": "We present a rollout-based controller that combines discrete and continuous decisions under the uncertain contingency policy of the L2RPN AI4RealNet 2026 challenge.", "limit_evidence": ""}, "2611.20748": {"points": [{"subtitle": "언어 포함 관계를 이용한 안전성 확보", "desc": "연구진은 생성된 논리식과 의도한 논리식이 완전히 똑같아야 한다는 까다로운 조건을 버리고, 대신 언어 포함 관계를 활용했는데요, 이게 무슨 말이냐면 생성된 논리식으로 만든 제어기의 동작이 의도한 요구사항을 만족하기만 하면 충분하다고 본 거예요.", "evidence": "Rather than requiring semantic equivalence between the generated and intended specifications, the proposed approach considers language inclusion, a sufficient condition for ensuring that the traces of a controller synthesized for the generated specification satisfy the intended requirement."}, {"subtitle": "의미적 동치 클래스와 빈도 기반 순위 산정", "desc": "LLM의 모호함을 해결하려고 같은 질문을 여러 번 던져서 나온 결과들을 의미가 같은 것끼리 묶었는데요, 이렇게 묶인 그룹들이 얼마나 자주 나타나는지를 기준으로 순위를 매겨서 가장 신뢰할 수 있는 논리식을 골라내는 방식이에요.", "evidence": "To account for ambiguity, the LLM is queried multiple times, and the resulting LTL specifications are grouped into semantic equivalence classes and ranked by their frequency of occurrence."}, {"subtitle": "차량 내비게이션 사례를 통한 성능 검증", "desc": "제안한 방법이 실제로 잘 작동하는지 확인하려고 차량 내비게이션 환경에서 실험을 진행했는데요, 정해진 위험 수준 안에서 제어기가 안전하게 합성되는지 확인하는 과정을 거쳤습니다.", "evidence": "Experiments on a vehicle navigation case study evaluate the proposed approach."}], "easy1_evidence": "However, the reliability of such translations remains a concern in safety-critical applications, particularly when NL requirements are ambiguous.", "easy2_evidence": "Given a prescribed risk level, CRC selects how many of the top-ranked equivalence classes to combine into a single LTL specification, such that the probability of issuing a controller that violates the intended requirement is bounded by that level.", "topic_evidence": "This paper proposes a framework based on Conformal Risk Control (CRC) to provide a statistical guarantee on the risk of issuing a controller that violates the user's intended requirement.", "limit_evidence": ""}, "2611.20526": {"points": [{"subtitle": "데이터 기반 ODP 평가", "desc": "기기 모델이 없어도 측정된 궤적에서 ODP 행렬과 지표를 직접 추정합니다. 내부 상태 측정값이 있으면 선형 행렬 부등식(LMI)을 구성하고, 없으면 입출력 데이터만으로 확장 상태 표현을 만들어 평가를 수행합니다.", "evidence": "When internal states are available, trajectory-based linear matrix inequalities (LMIs) are constructed from input-state measurements to estimate the local ODP matrices and scalar indices."}, {"subtitle": "계산 효율 및 수치 안정화", "desc": "데이터 기반 LMI의 계산 부담을 줄이기 위해 RIW 기법으로 중복 좌표를 제거했습니다. 또한 IV 전처리를 적용해 노이즈를 억제하고 수치적으로 불안정한 문제를 해결했습니다.", "evidence": "To address the computational and numerical challenges of trajectory-based LMIs, we introduce right-inverse whitening (RIW) to remove redundant behavioral coordinates and improve computational efficiency, and apply instrumental-variable (IV) preprocessing to alleviate numerical ill-conditioning and mitigate noise effects."}, {"subtitle": "구성적 및 분산 평가", "desc": "추정된 ODP 행렬을 네트워크 결합 행렬과 결합하여 전체 전력망의 안정성을 평가합니다. 각 지표를 활용하면 시스템을 나누어 평가하는 분산 방식도 가능하며, 제어기 변경 후에도 모듈식으로 재평가할 수 있습니다.", "evidence": "The estimated ODP matrices are combined with the network coupling matrix for compositional assessment of power system stability, while their scalar indices enable decentralized assessment."}], "easy1_evidence": "This paper proposes a compositional data-driven small-signal stability assessment framework for interconnected power systems based on output differential passivity (ODP).", "easy2_evidence": "To address the computational and numerical challenges of trajectory-based LMIs, we introduce right-inverse whitening (RIW) to remove redundant behavioral coordinates and improve computational efficiency, and apply instrumental-variable (IV) preprocessing to alleviate numerical ill-conditioning and mitigate noise effects.", "topic_evidence": "This paper proposes a compositional data-driven small-signal stability assessment framework for interconnected power systems based on output differential passivity (ODP).", "limit_evidence": ""}, "2611.20355": {"points": [{"subtitle": "행렬 정규 불변 사전 분포 도입", "desc": "칼만 필터(Kalman filter)를 행렬값 연산자로 확장하면서 오프라인에서 학습된 연산자를 중심으로 하는 행렬 정규 불변 사전 분포를 사용했어요. 뭔 소리냐면, 새로운 데이터가 적어도 기존의 학습된 정보를 바탕으로 모델을 안정적으로 업데이트하겠다는 말이에요.", "evidence": "To this end, we formulate a recursive matrix regression in fixed lifted coordinates that extends the Kalman filter with back-to-the-prior forgetting to matrix-valued operators and uses a matrix normal invariant prior, centered at the operator identified offline."}, {"subtitle": "안정성 증명 및 오차 감소", "desc": "어떤 피드백 법칙을 사용하더라도 추정 오차가 입력-상태 안정성을 유지하며 공분산이 사전 공분산의 두 배수 사이에서 머물도록 증명했어요. 이를 통해 모델이 불안정해지는 것을 막고 추정 성능을 확보했다는 겁니다.", "evidence": "For any regressor sequence, and thus under any feedback law, we prove that the covariance remains between two multiples of the prior covariance and that the estimation error is input-to-state stable."}, {"subtitle": "로봇 및 전력망 적용 결과", "desc": "차동 구동 로봇과 전력망 시스템에서 실험해 봤더니, 제안한 방식이 비교 대상인 다른 추정기들보다 추적 오차가 가장 낮게 나타났어요. 특히 여기(excitation)가 거의 없는 상황에서도 공분산이 비정상적으로 커지는 현상을 성공적으로 방지했다고 밝혔습니다.", "evidence": "On an academic example, a differential-drive robot and a power system with plant changes and little excitation, the invariant-prior estimator yields the lowest overall tracking error among the compared estimators and prevents covariance windup."}], "easy1_evidence": "Adaptive Koopman predictive control promises to address this limitation, but typically requires closed-loop persistent excitation (PE).", "easy2_evidence": "To this end, we formulate a recursive matrix regression in fixed lifted coordinates that extends the Kalman filter with back-to-the-prior forgetting to matrix-valued operators and uses a matrix normal invariant prior, centered at the operator identified offline.", "topic_evidence": "In this paper we develop an adaptive generalized Koopman (GeKo) predictive controller that does not require PE.", "limit_evidence": ""}, "2611.20070": {"points": [{"subtitle": "전압 예측 모델 학습", "desc": "지역별로 측정된 전력과 전압 데이터만을 활용해서 전압 변화를 추정하는 선형 대리 모델을 만들었어요. 이 모델은 각 에이전트가 자신의 문제를 풀 때 전압 위반에 대한 페널티로 작용하게 됩니다.", "evidence": "We use sparse-group LASSO regression to learn a linear surrogate of nodal voltages from local power and voltage measurements alone."}, {"subtitle": "합의 기반 분산 최적화", "desc": "학습된 모델을 바탕으로 에이전트들이 서로 통신하며 합의에 도달하는 방식을 사용했어요. 이 과정에서 통신 그래프가 자연스럽게 형성되어 중앙 집중식 제어 없이도 전체적인 최적화를 수행하게 되는 겁니다.", "evidence": "The surrogate serves a dual purpose: it enters each agent's local problem as a voltage penalty and induces the communication graph over which the agents reach consensus."}, {"subtitle": "성능 및 이론적 검증", "desc": "IEEE-33 네트워크에서 실험한 결과, 전압 위반 사례를 30%에서 3% 미만으로 낮추는 성과를 보였어요. 또한 연구진은 대리 모델의 부정확함으로 인해 발생하는 최적해 손실에 대한 이론적 한계치도 함께 제시했습니다.", "evidence": "We provide a theoretical bound on the optimality loss caused by the surrogate voltage estimator inaccuracy."}], "easy1_evidence": "Existing distributed optimization approaches either neglect such physical constraints or assume perfect knowledge of the network model.", "easy2_evidence": "Our numerical results, on an IEEE-33 network, show that the scheme reduces the share of bus-timesteps voltage violations from 30% to below 3%, while staying within 1% of a centralized benchmark computed with full network knowledge.", "topic_evidence": "This paper addresses the Voltage-Constrained Economic Dispatch (VCED) problem in a fully decentralized, consensus-based manner, without any coordinating entity.", "limit_evidence": "We further quantify how the sparsity of the communication graph affects both the optimality gap and the residual violations."}, "2611.20026": {"points": [{"subtitle": "CIM 계층의 설계와 기능", "desc": "연구진이 제안한 CIM 계층은 전력망 내 각 요소의 역할과 연결 상태를 명확하게 정의합니다. 이 계층은 데이터의 출처를 라벨링하여 정보가 데이터 자체에 있는지, 이름에서 유추된 것인지, 아니면 위상 구조에서 파생된 것인지 구분해 줍니다.", "evidence": "It labels the provenance of each fact (stated in the data, suggested only by a name, or inferred from topology), loads operators' CGMES models directly, and builds in ≤1s on the 9,241-bus PEGASE network."}, {"subtitle": "성능 검증 및 효율성", "desc": "실제 구현된 CONDUCTOR 도구는 9,241개의 버스로 구성된 PEGASE 네트워크에서 1초 이내에 모델을 구축할 수 있을 만큼 효율적입니다. 또한 모든 답변을 솔버 결과 및 CIM 계층과 비교하는 결정론적 검사 과정을 거치도록 설계되었습니다.", "evidence": "It labels the provenance of each fact (stated in the data, suggested only by a name, or inferred from topology), loads operators' CGMES models directly, and builds in ≤1s on the 9,241-bus PEGASE network."}, {"subtitle": "정확도 향상 결과", "desc": "CIGRE 중압 네트워크와 IEEE 30-버스 네트워크를 대상으로 실험한 결과, CIM 계층을 사용했을 때 정답률이 97%에 달했습니다. 이는 계층 없이 이름과 형식에 의존했을 때의 55%보다 훨씬 높은 수치로, 연구진은 이 계층이 전력망 보조 도구의 기본 구성 요소가 되어야 한다고 주장했습니다.", "evidence": "On 37 tasks about the CIGRE medium-voltage and IEEE 30-bus networks, the agent gets right 97% of the graded facts with the layer, such as a unit's energy source or a switch's normal state, against 55% without it."}], "easy1_evidence": "Current designs delegate computations to validated solvers, but the agent still infers the type, role and state of each element from its name and tool-specific formats, and errors propagate to every study.", "easy2_evidence": "On 37 tasks about the CIGRE medium-voltage and IEEE 30-bus networks, the agent gets right 97% of the graded facts with the layer, such as a unit's energy source or a switch's normal state, against 55% without it.", "topic_evidence": "We propose a CIM layer for LLM grid assistants and implement it in CONDUCTOR, an open-source assistant.", "limit_evidence": ""}, "2611.19732": {"points": [{"subtitle": "잔차 에너지 분리 원리", "desc": "가중 최소 제곱법(WLS)을 이용한 잔차 계산에서 노이즈와 공격 오차에 동일한 투영기를 적용해 봤는데요. 연구진은 특정 스펙트럼 억제 조건 아래에서 정상 데이터와 공격 데이터의 잔차 에너지가 망 구조와 무관하게 일정한 간격으로 분리된다는 점을 수학적으로 증명했습니다.", "evidence": "The weighted-least-squares (WLS) residual applies the same projector construction to the noise and to the attack error, and under a spectral suppression condition we prove that the expected residual energies of normal and attacked measurements are separated by a topology-independent margin."}, {"subtitle": "공격자의 은폐 전략 분석", "desc": "재구성 기반의 딥러닝 생성기가 어떻게 탐지를 피하는지 분석했습니다. 이 생성기가 데이터를 측정값에 가깝게 맞추면서 일종의 노이즈 제거기처럼 작동하게 되는데, 이로 인해 공격으로 인한 잔차 에너지가 기존 탐지기가 확인하지 않는 하위 구간으로 떨어지게 된다는 겁니다.", "evidence": "A reconstruction-based DL generator pursues stealth by fitting the measurements closely, and because such a generator tends to act as a denoiser, the attacked residual energy can fall into the lower tail that BDD never inspects."}, {"subtitle": "망 구조 변화에 대한 강건성", "desc": "제안한 방식은 한 가지 망 구조에서 학습한 규칙을 다른 구조에 그대로 적용해도 성능이 유지되는 특징이 있습니다. 기존의 원시 측정값을 사용하는 데이터 기반 탐지기가 구조 변경 시 성능이 급격히 떨어지는 것과 대조적으로, 이번 방식은 재학습 없이도 높은 탐지 정확도를 보였다고 주장했습니다.", "evidence": "Empirically, a rule learned on the residual energy at one topology transfers without retraining and keeps mean cross-topology F1 above 0.98 on the IEEE 14-bus, 39-bus, 57-bus, and 118-bus systems, while a raw measurement DD detector collapses."}], "easy1_evidence": "Deep learning (DL) false data injection (FDI) attacks can evade both bad data detection (BDD) and data-driven (DD) detectors in AC power system state estimation (SE), and DD detectors lose effectiveness after a topology change unless they are retrained.", "easy2_evidence": "Empirically, a rule learned on the residual energy at one topology transfers without retraining and keeps mean cross-topology F1 above 0.98 on the IEEE 14-bus, 39-bus, 57-bus, and 118-bus systems, while a raw measurement DD detector collapses.", "topic_evidence": "Topology-Transferable Detection of Deep-Learning False Data Injection Attacks Through Residual-Energy Separation", "limit_evidence": ""}, "2611.19608": {"points": [{"subtitle": "전력망 모델링 및 평가", "desc": "연구진은 IEEE 24-버스 시스템을 수정해서 전력망 모델을 만들고, 24시간 단위의 발전 계획과 에너지 및 예비력 최적화 모델을 적용해 봤는데요. 풍력, 태양광, 배터리 설비를 단계별로 31가지 조합으로 구성해서 전력망의 상태를 평가했습니다.", "evidence": "Thirty-one cumulative portfolio states are evaluated on a modified IEEE 24-bus system for a constructed stressed day using a 24-hour day-ahead unit commitment model with network constraints, co-optimized energy and upward reserve, chronological battery storage, and an approximation of the Electric Reliability Council of Texas operating reserve demand curve."}, {"subtitle": "설비 확충에 따른 예비력 가격 변화", "desc": "풍력만으로는 저녁 시간대 예비력 부족을 막기 어려웠는데, 태양광 1,800MW를 추가했더니 예비력 부족 가격이 평균 1,136.2달러/MWh에서 101.2달러/MWh로 줄어들었습니다. 여기에 배터리 250MW/1,000MWh를 더하자 가격이 4.3달러/MWh까지 떨어지고 풍력 발전의 낭비도 줄어드는 효과가 나타났거든요.", "evidence": "Adding 250 MW/1,000 MWh of battery storage further lowers the average to $4.3/MWh and reduces wind curtailment from 631 MWh to 306 MWh."}, {"subtitle": "지속되는 송전망 혼잡 문제", "desc": "설비를 늘려도 송전망 혼잡은 여전히 남아서, 특정 버스에서는 풍력 발전이 계속 낭비되고 지역마다 전력 가격 차이가 크게 발생했습니다. 같은 배터리 설비라도 설치된 위치에 따라 시장 수익이 201달러와 121달러로 다르게 나타나는 걸 보면, 위치에 따른 혼잡 문제가 여전히 중요하다는 겁니다.", "evidence": "Transmission congestion nevertheless remains: all residual wind curtailment occurs at bus 21, wind capture prices at buses 21 and 23 differ by $31.8/MWh, and identical battery storage plants yield normalized net energy market revenues of $201/(MW·day) and $121/(MW·day) at buses 19 and 21, respectively."}], "easy1_evidence": "This paper asks whether sequential wind, solar, and battery storage additions that eliminate unserved energy also remove modeled reserve scarcity and transmission congestion.", "easy2_evidence": "However, with 1,500 MW of wind, the hourly modeled reserve scarcity price still reaches $5,000/MWh because wind output declines after the system peak.", "topic_evidence": "These results show that unserved energy, modeled reserve scarcity, and locational congestion effects measure distinct operating conditions and should be evaluated separately but interpreted together.", "limit_evidence": ""}, "2611.19602": {"points": [{"subtitle": "DC 방식의 과대평가 확인", "desc": "텍사스 전력망 모델 123개 버스를 분석했더니, 113개 지점에서 DC 방식이 계산한 용량이 AC 방식의 실제 수용 능력보다 컸어요. 전체 중앙값은 143%로, DC 방식이 실제보다 43% 정도 더 크게 잡는 셈이에요.", "evidence": "Across all 123, the ratio of DC-screened to AC-assessed capacity has a median of 143% (a 43% overestimate) and a maximum of 1,070%."}, {"subtitle": "DC 모델이 놓치는 제약 조건", "desc": "DC 모델은 선로의 피상 전력 제한이나 발전기의 무효 전력 제한 같은 중요한 요소들을 고려하지 않아요. 그래서 AC 모델에서는 위반되는 상황이 DC 모델에서는 통과되는 오류가 발생한다는 거예요.", "evidence": "At these 113 buses, the DC-screened capacity violates a branch apparent power limit or a generator reactive power limit in the AC model, two limits the DC model omits."}, {"subtitle": "입지 선정 및 계획의 변화", "desc": "이런 과대평가 때문에 1GW 규모의 프로젝트가 모든 버스에서 통과되지만 실제로는 37개 지점에서 용량을 초과하는 문제가 생겨요. 심지어 DC 방식에서 1위로 꼽힌 지점이 2위 지점보다 실제 수용 능력은 205.5MW나 낮게 나타나기도 했습니다.", "evidence": "The overestimate changes decisions: a 1-GW project passes DC screening at every bus but exceeds the AC-assessed capacity at 37, and the bus ranked first by DC screening has 205.5 MW less AC-assessed capacity than the bus ranked second."}], "easy1_evidence": "On a synthetic Texas system with 123 buses, the DC-screened capacity exceeds the AC-assessed capacity at 113 buses.", "easy2_evidence": "Reporting the AC-assessed capacity beside each DC-screened capacity lets planners reject oversized projects or choose better sites.", "topic_evidence": "This paper assesses that estimate under the alternating current (AC) network model.", "limit_evidence": ""}, "2611.19226": {"points": [{"subtitle": "전문가 모델의 역할 분담", "desc": "먼 거리에서는 수정된 삭망 요소(modified equinoctial elements)를 다루는 전문가가, 도착 직전에는 상대적 위치를 다루는 전문가가 각각 임무를 수행해요. 이 두 전문가의 명령을 학습된 게이트가 상황에 맞춰 자연스럽게 섞어 주는 방식이에요.", "evidence": "A far-range expert acts on modified equinoctial elements, a terminal expert acts on the relative state in the target's local frame, and a learned gate blends their thrust commands."}, {"subtitle": "트랜스포머를 통한 기억력 강화", "desc": "도착 지점용 전문가는 트랜스포머(Transformer)를 사용해 관측 이력을 인코딩함으로써 부분 관측 가능성 문제를 해결했어요. 게이트 또한 별도의 인코더를 사용해 과거 기록에 의존하는 명령을 처리할 수 있게 설계했거든요.", "evidence": "The terminal expert encodes its observation history with a Transformer to address partial observability, and the gate uses a separate encoder to account for the resulting history-dependent command."}, {"subtitle": "강인한 성능과 효율성 입증", "desc": "600번의 시험에서 오차 범위 10m와 1m/s 이내로 모두 성공했고, 항법 오류나 궤도 섭동 같은 변수가 생겨도 재학습 없이 잘 작동했어요. 쉽게 말하면, 기존 방식보다 비행 시간과 연료 효율 면에서 훨씬 뛰어나다는 겁니다.", "evidence": "On 600 test missions, it achieves rendezvous in every case at tolerances of 10 m and 1 m/s, reduces mean flight time and delta-v by 50.6% and 44.5% relative to distance-based hard switching, and remains successful without retraining under navigation errors, unmodeled orbital perturbations, eclipse-induced thrust outages, and thrust loss."}], "easy1_evidence": "Multi-revolution low-thrust rendezvous requires both long-duration orbital transfer and precise terminal control.", "easy2_evidence": "This paper proposes a temporal attention-enhanced mixture-of-experts guidance law trained by deep reinforcement learning.", "topic_evidence": "This paper proposes a temporal attention-enhanced mixture-of-experts guidance law trained by deep reinforcement learning.", "limit_evidence": ""}, "2611.19132": {"points": [{"subtitle": "트립 인증을 통한 선형화", "desc": "계전기가 지연 시간 만료 전에 재설정되면 차단 동작을 취소할 수 있도록 하는 트립 인증 방식을 도입했는데요. 이를 통해 복잡한 비선형 문제를 선형 계획법으로 변환하여 최적의 예비력을 계산할 수 있게 됐다는 거예요.", "evidence": "A trip certificate allows a relay to pick up if it resets before its delay expires, making the sizing a linear program."}, {"subtitle": "예방적 보호와 제어 변수 분석", "desc": "연구진은 오직 예방적 조치로만 보호할 수 있는 계전기들을 식별하는 필수 조건을 정의했는데요. 제어 장치의 예비력은 계전기의 지연 시간이 길어질수록 줄어들고, 제어 장치 자체의 반응 속도가 늦어질수록 더 많은 예비력이 필요하다는 점을 밝혀냈습니다.", "evidence": "A necessary condition identifies the relays that only preventive action can protect, and the reserve of one control decreases with the relay delay and increases with its latency."}, {"subtitle": "시뮬레이션 기반의 효과 검증", "desc": "4개의 시스템을 대상으로 비선형 시뮬레이션을 수행한 결과, 제안한 교정 조치들이 분석 범위 내의 모든 차단 사고를 예방하는 것으로 나타났는데요. 다만 2%의 히스테리시스나 계전기 전압 측정의 작은 오차만으로도 필요한 예비력 규모가 계전기 지연 시간만큼이나 크게 변할 수 있다는 점을 확인했습니다.", "evidence": "A 2% hysteresis or a small error in the relay voltage can change the reserve as much as the relay delay."}], "easy1_evidence": "In an overvoltage cascade, each relay trip removes reactive power absorption and raises the voltage at other plants, often faster than controls can act.", "easy2_evidence": "This paper determines how much fast reactive power to hold, where, and how fast, so that no contingency trips a plant.", "topic_evidence": "This paper determines how much fast reactive power to hold, where, and how fast, so that no contingency trips a plant.", "limit_evidence": "A 2% hysteresis or a small error in the relay voltage can change the reserve as much as the relay delay."}, "2611.19125": {"points": [{"subtitle": "AI 추론 유연성 모델링", "desc": "연구진은 GPU 측정값을 바탕으로 AI 추론 지연 시간과 데이터센터의 전력 소비량을 모델링했는데요, 사용자가 요구하는 서비스 품질(QoS) 범위 안에서 작업 처리를 얼마나 미루거나 옮길 수 있는지 그 유연성을 수치화한 겁니다.", "evidence": "Using GPU measurements, this paper models inference latency and DC power consumption to quantify the flexibility available under users' time-to-first-token (TTFT) and inter-token latency (ITL) requirements."}, {"subtitle": "전력망 최적 조류 계산(OPF) 통합", "desc": "앞서 만든 모델을 전력망 최적 조류 계산(OPF)에 결합해서 AI 작업 경로 설정과 전력 시스템 운영을 하나로 묶었는데요, 데이터센터 운영자와 송전망 운영자, 그리고 사용자가 서로 연결되어 전력망 제약 조건을 고려한 작업 스케줄링이 가능해진 셈이에요.", "evidence": "These models are then incorporated into an AI inference-aware optimal power flow (OPF) that coordinates inference routing and power system operation among DC operators, the transmission system operator, and inference users."}, {"subtitle": "비용 절감 효과 검증", "desc": "PJM 전력망 시스템에서 시뮬레이션을 돌려봤더니, 기존의 컴퓨팅 자원 중심이나 전기 요금 중심의 경로 설정 방식보다 이번에 제안한 방식이 더 낮은 비용으로 전력 수요를 감당할 수 있다고 연구진은 주장했어요.", "evidence": "Simulations on the PJM system show that, compared with computing-based routing and with electricity price-based routing, coordinating inference routing with network operation enables growing DC electricity demand deliverable to be met at lower cost."}], "easy1_evidence": "The rapid growth, temporal variability, and geographic concentration of electricity demand from artificial intelligence (AI) inference can aggravate transmission congestion near data centers (DCs).", "easy2_evidence": "These models are then incorporated into an AI inference-aware optimal power flow (OPF) that coordinates inference routing and power system operation among DC operators, the transmission system operator, and inference users.", "topic_evidence": "By linking user requests, token generation at DCs, and electricity delivery through the transmission network, the formulation schedules inference workloads subject to both users' QoS requirements and transmission constraints.", "limit_evidence": ""}, "2611.19073": {"points": [{"subtitle": "유연한 전력망 연결", "desc": "데이터센터가 전력망 시설을 업그레이드하지 않고도 빠르게 연결될 수 있는 유연한 연결 방식을 다뤘는데요. 대신 전력망에 스트레스가 가해지는 상황에서는 전력 소비 제한을 수용해야 한다는 조건이 붙습니다.", "evidence": "Flexible interconnections allow data centers to connect to the grid sooner without upgrading the grid infrastructure, if they accept limits on their grid power during periods of grid stress."}, {"subtitle": "실시간 전력 배분 방법", "desc": "전력이 제한될 때 데이터센터 내부의 작업들이 어떻게 반응하는지 모델링하고, 작업의 가치에 따라 가용 전력을 실시간으로 나누는 방법을 제안했습니다. 이는 작업의 가치가 에너지 비용보다 훨씬 크다는 점을 고려한 설계예요.", "evidence": "This paper models how jobs respond when their power is reduced, and proposes a real-time method that shares the available power among jobs according to their value."}, {"subtitle": "비용 절감 효과 분석", "desc": "100MW 규모의 데이터센터를 대상으로 1년간 사례 연구를 진행했는데요. 제안한 방법을 사용하면 전력망 제한을 준수하는 비용이 낮아지며, 현장 발전과 에너지 저장 장치를 추가로 활용하면 비용을 더 줄일 수 있다고 연구진은 주장했습니다.", "evidence": "A one-year case study of a 100-MW data center shows that the proposed method lowers the cost of meeting grid limits, and that on-site generation and storage lower it further."}], "easy1_evidence": "When a limit is reached, the data center must slow some of its computing jobs.", "easy2_evidence": "This paper models how jobs respond when their power is reduced, and proposes a real-time method that shares the available power among jobs according to their value.", "topic_evidence": "This paper models how jobs respond when their power is reduced, and proposes a real-time method that shares the available power among jobs according to their value.", "limit_evidence": ""}, "2611.20218": {"points": [{"subtitle": "조직 내 협업 환경 구현", "desc": "각 과제는 26명의 동료가 있는 가상 엔지니어링 조직에서 수행되는데요, 동료들은 각자 맡은 역할과 제한된 지식을 가지고 있어요. 에이전트는 짧은 인수인계를 시작으로 동료와 기록에 흩어진 요구사항을 찾아내야 합니다.", "evidence": "Each assignment places an agent in a simulated engineering organization with 26 colleagues who have distinct responsibilities, bounded knowledge, and controlled collaboration behavior."}, {"subtitle": "요구사항 추적 및 구현의 어려움", "desc": "분석 결과, 에이전트들은 정보를 얻는 과정부터 구현, 검증까지 전 단계에서 실패를 겪고 있어요. 예를 들어 Claude-Opus-5.5는 질문의 93%를 담당자에게 보냈지만, 정작 필요한 요구사항은 64%밖에 얻지 못했거든요.", "evidence": "Requirement-level trajectory analysis reveals failures throughout the delivery process: Claude-Opus-5.5 directs a mean of 93% of first questions about queried cards to their accountable owners across runs but obtains only 64% of colleague-held requirements."}, {"subtitle": "완성도 부족 문제", "desc": "질문을 미루거나 요구사항을 얻은 뒤에도 구현이 불완전한 경우가 많았고, 완료되었다고 보고된 요구사항 중 31%는 테스트를 통과하지 못했어요. 연구진은 이를 통해 요구사항을 끝까지 추적하고 검증하는 것이 자율 소프트웨어 공학의 핵심 과제라고 주장했어요.", "evidence": "Deferred questions go unfollowed, implementations remain incomplete even after requirements are acquired, and 31% of requirements reported as completed fail their tests."}], "easy1_evidence": "A coding agent working within a software organization must establish what to build, collaborate with colleagues, and verify what it delivers.", "easy2_evidence": "The two leading models satisfy approximately 63% of fail-to-pass (F2P) tests but complete fewer than 8% of assignments.", "topic_evidence": "We introduce SWE-CoWork, a benchmark comprising 101 development assignments across 101 real repositories, 11 programming languages, and 12 application domains.", "limit_evidence": "Providing complete requirements upfront improves F2P by approximately 16 percentage points for Seed Evolving and GPT-6 Astra, yet leaves complete task success unchanged."}, "2611.21607": {"points": [{"subtitle": "학습 효율성 개선", "desc": "데이터가 적은 상황에서 얼마나 잘 배우는지 확인해 봤는데요. 10개의 시연만으로도 50개의 시연을 학습한 20억 파라미터 모델보다 더 높은 87.8%의 성능을 보였다는 거예요.", "evidence": "In sample efficiency, just 10 demonstrations outperform a 2B backbone trained with 50 (87.8% vs. 85.6%)."}, {"subtitle": "일반화 성능 강화", "desc": "새로운 환경에 적응하는 능력을 평가하는 LIBERO-PRO 테스트를 진행했는데요. 기존의 작은 모델들이 최대 31.3%의 성공률을 보인 반면, ScaleVLA는 45.1%까지 성공률을 끌어올렸다는 겁니다.", "evidence": "In generalization, LIBERO-PRO success reaches 45.1%, compared with at most 31.3% for smaller backbones."}, {"subtitle": "정밀 조작 능력 향상", "desc": "실제 환경에서 충전기를 꽂는 정밀한 작업을 시켜 봤거든요. 성공 횟수가 10번 중 4번에서 9번으로 크게 늘었는데, 특히 물체와 닿았을 때 위치를 맞추는 능력이 좋아진 덕분이라는 거예요.", "evidence": "In precise manipulation, real-world charger insertion improves from 4/10 to 9/10 successes, with gains concentrated in contact-sensitive alignment."}], "easy1_evidence": "Yet most Vision-Language-Action (VLA) policies still rely on much smaller VLM backbones, leaving this potential largely untapped.", "easy2_evidence": "We introduce ScaleVLA, which connects a 552B DeepSeek-V4.1-Flash backbone to a trainable action DiT, and systematically compare VLMs from 2B to 552B under a shared training setup.", "topic_evidence": "We ask whether frontier-scale representations can provide a stronger foundation for robot learning.", "limit_evidence": ""}, "2611.21599": {"points": [{"subtitle": "병렬 알고리즘 기반의 안정성 증명", "desc": "신경망의 ReLU 활성화가 만드는 초평면 배치를 병렬로 계산하는 알고리즘을 도입했어요. 이를 통해 각 다면체 영역 안에서 리아푸노프(Lyapunov) 조건이 만족하는지를 체계적으로 확인하는 방식이에요.", "evidence": "Hyperlyve's key innovation is a parallel algorithm that enumerates the hyperplane arrangement formed by the ReLU activations of deep networks and certifies that Lyapunov conditions hold within each polyhedral region."}, {"subtitle": "정확한 동역학 시스템의 검증", "desc": "선형 근사치를 사용하는 대신, 실제 시스템의 매끄러운 동역학을 직접 다루는 지역 테스트를 설계했어요. 덕분에 관심 있는 콤팩트 도메인 내에서 시스템의 점근적 안정성을 완전하고 정확하게 검증할 수 있다는 거예요.", "evidence": "We derive sound and complete regional tests to verify the asymptotic stability of the exact smooth dynamics (rather than a piecewise-linear approximation) within a compact domain of interest."}, {"subtitle": "계산 복잡도 규명 및 성능 입증", "desc": "연구진은 이 문제가 co-NP-완전(co-NP-complete)임을 밝혀내며 이론적 공백을 채웠다고 주장했어요. 실제 실험에서도 기존 도구보다 150배 이상 빠른 속도를 보여주며 성능을 입증했거든요.", "evidence": "Furthermore, we formally characterize the computational complexity of the CPA neural Lyapunov verification problem as co-NP-complete, filling a key gap in the literature."}], "easy1_evidence": "Hyperlyve's key innovation is a parallel algorithm that enumerates the hyperplane arrangement formed by the ReLU activations of deep networks and certifies that Lyapunov conditions hold within each polyhedral region.", "easy2_evidence": "Empirical results demonstrate that Hyperlyve enumerates ReLU networks over 150-times faster than competing tools, which contributes to Hyperlyve proving the asymptotic stability of systems that are currently intractable for state-of-the-art verifiers.", "topic_evidence": "We introduce Hyperlyve (Hyperplane Partitioned Lyapunov Verification and Enumeration), a framework for proving the asymptotic stability of nonlinear dynamical systems, including those with neural network controllers.", "limit_evidence": ""}, "2611.21483": {"points": [{"subtitle": "분산형 상태 재구성", "desc": "각 센서 노드가 로컬 정보와 이웃의 상태 추정치만을 활용해 미지의 비선형 시스템을 식별하도록 설계했습니다. 통신 네트워크의 구조와 관측기 동역학, 매개변수 불확실성 사이의 상호작용을 네트워크 수준에서 오차로 표현해 낸 거예요.", "evidence": "Each sensing node reconstructs the source state while adapting local estimates of the unknown linear and nonlinear dynamics using only locally available information and neighboring state estimates."}, {"subtitle": "안정성 보장 조건", "desc": "결합 연산자가 허위츠(Hurwitz) 조건을 만족하도록 노름 기반의 구조적 리아푸노프 함수와 강건한 선형 행렬 부등식(LMI) 조건을 세웠습니다. 이를 통해 적응형 매개변수가 발산하지 않고 추정 오차가 점진적으로 수렴함을 수학적으로 증명했거든요.", "evidence": "Norm-based, structured Lyapunov, and robust LMI conditions are established to guarantee that the resulting coupling operator is Hurwitz."}, {"subtitle": "수치적 성능 검증", "desc": "별 모양, 순환형, 경로형 등 다양한 네트워크 구조에서 이론을 검증해 봤는데요, 센서 노드 수가 늘어남에 따라 계산량이 선형적으로 증가하는 효율성을 보였습니다. 즉, 규모가 커져도 계산 부담이 급격히 늘어나지 않는다는 점을 확인한 셈이에요.", "evidence": "Numerical studies over star, cyclic, and path topologies support the theoretical results and demonstrate approximately linear computational scaling with the number of sensing nodes."}], "easy1_evidence": "This paper studies continuous-time distributed adaptive identification of unknown nonlinear systems over directed communication networks without requiring source or neighboring inputs to be shared.", "easy2_evidence": "Input-to-state stability is further established under bounded predictor mismatch and source disturbances.", "topic_evidence": "This paper studies continuous-time distributed adaptive identification of unknown nonlinear systems over directed communication networks without requiring source or neighboring inputs to be shared.", "limit_evidence": ""}, "2611.21446": {"points": [{"subtitle": "강건한 행동 클러스터 정의", "desc": "외부의 압력에도 아랑곳하지 않고 특정 행동을 고수하는 집단을 강건한 행동 클러스터라고 불렀어요. 이 집단이 유지되려면 구성원들이 서로에게 충분한 영향력을 행사해야 하는데, 이때 필요한 영향력의 크기는 각자가 가진 행동 규칙에 따라 달라진다는 거예요.", "evidence": "We call such a group, paired with that action, a robust action cluster."}, {"subtitle": "행동 전파의 연쇄 반응", "desc": "클러스터 밖에 있는 사람이 언제 클러스터의 행동을 영구적으로 받아들이게 되는지 그 조건을 제시했어요. 이 조건을 반복적으로 적용하면, 결국 네트워크 전체로 행동이 퍼져 나가는 연쇄 반응을 확인할 수 있다는 말이에요.", "evidence": "We further give a sufficient condition under which an agent outside the cluster permanently adopts the cluster's action, and we iterate it to obtain a cascade of agents that are guaranteed to adopt that action."}, {"subtitle": "평균값 적용의 위험성", "desc": "사람마다 다른 행동 기준을 단순히 평균값으로 퉁쳐서 계산하면 어떤 일이 벌어지는지 수치 예시로 보여줬어요. 그랬더니 행동의 전파 양상이나 클러스터의 존재 여부가 완전히 달라질 수 있다는 걸 확인했거든요. 쉽게 말하면, 개별적인 차이를 무시하면 전체 결과를 잘못 해석할 수 있다는 거예요.", "evidence": "Finally, numerical examples show that replacing heterogeneous thresholds by their mean can change both the propagation of an action and the presence of robust action clusters."}], "easy1_evidence": "Agents update their opinions from their neighbors' observed actions and express them through action rules whose thresholds differ across agents.", "easy2_evidence": "We show that a group is a robust action cluster for that action if and only if each member places enough of its influence weight on the group, where the required influence depends on the member's own action rule.", "topic_evidence": "We study the preservation and propagation of public actions in networks whose agents hold continuous private opinions.", "limit_evidence": ""}, "2611.21378": {"points": [{"subtitle": "데이터 통합 전략", "desc": "마찰력이 다른 상황에서 기록된 데이터를 통합하여 예측 모델을 구성했습니다. 마찰력을 명시적으로 추정하는 과정 없이도 다양한 주행 환경에 대응할 수 있도록 설계한 거예요.", "evidence": "Instead, we pool data recorded at different frictions."}, {"subtitle": "예측 오차 비교", "desc": "데이터를 통합했을 때의 다단계 평균 제곱근 오차(RMSE)를 측정해 봤는데요, 마찰력이 일치하는 데이터와 비교해도 오차가 1.5배 이내로 유지되었습니다. 반면 마찰력이 다른 데이터를 그대로 썼을 때는 오차가 2.2배에서 3.4배까지 커졌다는 결과가 나왔어요.", "evidence": "Our results show that pooled data keep the multi-step root-mean-square prediction error within 1.5 times that of matched data, whereas mismatched data increase it by a factor of 2.2 to 3.4."}, {"subtitle": "실제 주행 성능 검증", "desc": "시뮬레이션과 실제 소형 차량 실험을 통해 경로 추적 성능을 확인했습니다. 통합 데이터를 사용한 DPC는 비선형 모델 예측 제어(NMPC)와 유사한 수준의 성능을 보였고, 마찰력이 다른 환경에서도 0.1cm에서 0.2cm 정도의 미세한 차이만 나타냈습니다.", "evidence": "In simulation, DPC with pooled data tracks comparably to nonlinear model predictive control (13.7 cm versus 13.3 cm) and close to DPC with matched data in the CPM Lab, differing by 0.1 cm on the low-friction tires (1.6 cm versus 1.5 cm) and by 0.2 cm on the high-friction tires (0.9 cm versus 1.1 cm)."}], "easy1_evidence": "If the initial trajectory and the recorded data originate from different frictions, prediction accuracy of DPC degrades.", "easy2_evidence": "DPC thus provides partial adaptation to varying friction, without a dedicated adaptation method.", "topic_evidence": "This paper investigates to what extent and under which conditions DPC using data pooled across operating conditions retains the prediction accuracy of DPC using data from the current operating condition.", "limit_evidence": ""}, "2611.21247": {"points": [{"subtitle": "반례 기반의 학습과 검증", "desc": "학습자가 메트릭을 제안하면 검증자가 이를 확인하고, 만약 문제가 있다면 반례를 제공해 다시 학습시키는 구조를 만들었는데요, 이 과정을 통해 시스템이 안정적인지 수학적으로 확실하게 증명할 수 있게 됩니다.", "evidence": "A learner proposes a metric; a sound verifier certifies its matrix inequality or returns diagnostic points for retraining."}, {"subtitle": "수치적 오차와 안정성 범위 계산", "desc": "검증 과정에서 단순히 안정성 여부만 따지는 게 아니라, 모델이 가진 오차 범위와 자코비안(Jacobian) 경계까지 계산해서 안정성을 보장할 수 있는 영역을 정밀하게 측정했는데요, 이를 통해 시스템이 얼마나 안정적인지 구체적인 수치로 확인할 수 있다는 겁니다.", "evidence": "Verified slack improves the contraction rate and quantifies model-error tolerances using certified residual and Jacobian bounds."}, {"subtitle": "물리 모델을 통한 성능 확인", "desc": "실제 스윙 모델(swing-model)을 대상으로 신경망 학습 목표와 에너지 불변 영역을 비교하는 실험을 진행했는데요, 다항식 벤치마크나 스윙 모델의 도메인에서 신경망의 상태 의존성 없이도 안정적인 메트릭을 찾아낼 수 있음을 확인했습니다.", "evidence": "A physical swing-model study compares neural learning objectives with shared verification and invariant energy regions."}], "easy1_evidence": "We study counterexample-guided synthesis of contraction metrics for continuous-time autonomous systems on compact domains.", "easy2_evidence": "The neural extension pairs a learned metric factor with symbolic contraction conditions and rigorous numerical verification; main ablations use polynomial features.", "topic_evidence": "We study counterexample-guided synthesis of contraction metrics for continuous-time autonomous systems on compact domains.", "limit_evidence": "These choices address specific failure mechanisms without guaranteeing optimizer convergence or general empirical superiority."}, "2611.21243": {"points": [{"subtitle": "회전교차로의 성능 우위", "desc": "규칙적인 격자 도로망에서 가장 중심이 되는 교차로 하나만 회전교차로로 바꿔도 지연 시간이 2~3% 줄어드는 것으로 나타났습니다. 교차로를 모두 회전교차로로 바꾸면 기존의 어떤 신호등 방식보다도 뛰어난 성능을 보인다는 게 연구진의 주장이에요.", "evidence": "In our computer simulations of the regular grid, converting the single most central intersection already lowers delays by 2 to 3\\% relative to actuated control; each additional conversion lowers them further, and full conversion outperforms every signalized alternative under all conditions studied."}, {"subtitle": "임계점과 교통 흐름 붕괴", "desc": "불규칙한 도로망에서는 회전교차로가 항상 좋은 건 아니었는데요. 교통량이 기본 부하의 약 3.1배를 넘어서는 임계점에 도달하면 교통 흐름이 급격히 무너지는 현상이 발생했거든요. 이때는 스스로 신호를 조절하는 방식이 지연 시간을 가장 짧게 유지하며 급격한 교통량 증가에도 잘 버티는 것으로 보입니다.", "evidence": "Beyond that point, the self-organizing traffic signals show the lowest delay of any network-wide strategy and is nearly insensitive to surges."}, {"subtitle": "속도 제한과 예측 가능성", "desc": "회전교차로는 낮은 속도 제한에서도 기존 신호등 체계와 비슷한 평균 속도를 유지할 수 있었습니다. 또한 기존 신호등이 있는 도로망보다 통행 시간이 더 일정하게 유지되어 예측하기가 훨씬 쉽다는 장점도 확인했습니다.", "evidence": "Furthermore, travel times in self-organized traffic flows are more predictable than in networks with conventional signals."}], "easy1_evidence": "Urban traffic flow networks are complex adaptive systems, whose variability challenges centralized, top-down control.", "easy2_evidence": "Compared to traffic signal control, this establishes a slower-is-faster effect.", "topic_evidence": "We study decentralized alternatives in which order emerges from local interactions, comparing the network-wide performance of roundabouts in SUMO against fixed-time and actuated control as well as self-organizing signals on a 4$\\times$4 grid and a rewired, irregular variant of it, across demand levels and periodic surge amplitudes.", "limit_evidence": "In the irregular traffic flow network with full conversion of all intersections into roundabouts, this holds only up to a critical load, where traffic flow breaks down sharply, when the time-averaged demand reaches about 3.1 times the base load."}, "2611.21204": {"points": [{"subtitle": "디지털 트윈 결합 구조", "desc": "연구진은 디지털 트윈을 적용하는 방식을 내장형(embedded), 원격형(remote), 네트워크형(networked) 세 가지 구조로 나누어 정리했어요. 장치와 디지털 트윈이 같은 장소에 있지 않아도 효과적으로 연결될 수 있음을 보여준 거예요.", "evidence": "We distinguish three coupling architectures--embedded DT, remote DT, and networked DT--and demonstrate the added value of combining DT and TPC concepts when the DT and PEC are not co-located."}, {"subtitle": "상태 공간 모델링과 칼만 필터", "desc": "제안한 프레임워크는 상태 공간 모델링과 칼만 필터(Kalman filtering)를 함께 사용하는데요, 이를 통해 데이터 전송과 매개변수 추정, 시스템 운영을 한꺼번에 처리할 수 있게 됩니다. 결과적으로 시스템의 강건함과 적응력, 전력 효율이 모두 좋아진다는 게 연구진의 설명이에요.", "evidence": "The proposed framework is based on state-space modeling in conjunction with Kalman filtering and facilitates joint treatment of data transmission, parameter estimation, and system operation, thereby improving robustness, adaptability, and power efficiency."}, {"subtitle": "사이버 물리 에너지 시스템으로의 확장", "desc": "이번 연구는 전력과 통신 기능이 아주 촘촘하게 엮인 미래의 사이버 물리 에너지 시스템(CPES)을 구현하는 데 큰 역할을 할 것으로 보입니다. 디지털 트윈으로 강화된 TPC가 그 핵심 기술이 될 수 있다는 점을 강조했어요.", "evidence": "The presented approach highlights the potential of DT-enhanced TPC as a key enabler for future cyber-physical energy systems with tightly integrated power and communication functionalities."}], "easy1_evidence": "TPC enables simultaneous power transfer and information exchange without dedicated transmitter-side communication hardware, and avoids additional wiring.", "easy2_evidence": "This paper combines, for the first time, the Digital Twin (DT) concept with the TPC paradigm.", "topic_evidence": "The proposed framework is based on state-space modeling in conjunction with Kalman filtering and facilitates joint treatment of data transmission, parameter estimation, and system operation, thereby improving robustness, adaptability, and power efficiency.", "limit_evidence": ""}, "2611.21203": {"points": [{"subtitle": "검증 및 보정 절차 개발", "desc": "예측 모델을 고정해 둔 상태에서 상황 변화에 따른 오차를 검증하는 절차를 만들었는데요. 잔차 그램 행렬을 이용해 모델이 다루지 못하는 영역을 파악하고 최적의 테스트 예산을 결정하는 방식이에요.", "evidence": "A residual Gram matrix yields the minimum augmentation rank and an optimal test budget for uncovered $L_2$ geometry."}, {"subtitle": "성능 개선 및 편향 제거", "desc": "240개의 상황을 대상으로 실험한 결과, 두 가지 스펙트럼 방향을 적용해 최악의 편향을 80.8% 이상 제거할 수 있었습니다. 또한 로지스틱 예측기 실험에서는 비용을 각각 2.590%와 3.239% 줄이는 성과를 보였어요.", "evidence": "For a separate misspecified logistic forecaster, matched sensitivity and generic corrections reduce expected cost by 2.590% and 3.239%, with the generic method winning all 200 refits."}, {"subtitle": "신뢰성 인증 체계", "desc": "새로운 10만 번의 에피소드에서 제안한 보정법을 적용했더니, 설정한 오차 허용 범위인 0.04 이내로 편향이 유지됨을 확인했는데요. 이는 모델의 예측 신뢰성을 수학적으로 인증할 수 있다는 의미예요.", "evidence": "On 100,000 new episodes, both corrections certify absolute evaluation bias below the illustrative tolerance 0.04 throughout a declared shift interval, while the base certifies no shift."}], "easy1_evidence": "Calibration evidence for a predictive controller need not remain valid when operating-context frequencies change.", "easy2_evidence": "In a designed 240-context study, two spectral directions remove at least 80.8% of the feasible worst-case bias.", "topic_evidence": "We develop an audit and certification procedure for a declared family of context-density shifts, with a frozen predictor/controller and unchanged conditional outcome law.", "limit_evidence": "The contribution is reusable evaluation and audit capability with explicit geometric and statistical limits, rather than recalibration superiority."}, "2611.21179": {"points": [{"subtitle": "학습 기반 최적화 프레임워크", "desc": "기존의 분산 최적화 알고리즘에 학습된 보조 장치를 더해서 계산 효율을 높이는 방식을 택했습니다. 추가적인 통신 과정 없이도 과거 데이터를 통해 알고리즘의 수렴 속도를 개선했다는 점이 핵심이에요.", "evidence": "We propose a learning-to-optimize framework for decentralized markets that uses historical data to accelerate clearing algorithms without additional communication."}, {"subtitle": "그래프 신경망을 활용한 유연성", "desc": "시장마다 참여자의 수나 연결 구조가 다를 수 있는데, 이를 해결하기 위해 그래프 신경망을 도입했습니다. 덕분에 다양한 규모와 위상(Topology)을 가진 시장에서도 일관되게 적용할 수 있는 업데이트 방식을 학습할 수 있게 된 거예요.", "evidence": "To enforce convergence by design, we train summable augmentations to a baseline algorithm, using graph neural networks to learn permutation-equivariant updates for markets of varying size and topology."}, {"subtitle": "성능 검증 및 견고성 확인", "desc": "분산 더글라스-래치포드(Douglas-Rachford) 알고리즘을 적용해 실험해 본 결과, 기존보다 더 빠르게 균형점에 도달하는 것을 확인했습니다. 또한 학습하지 않은 새로운 환경에서도 알고리즘이 안정적으로 작동하는 견고함을 보여주었다고 연구진은 주장했어요.", "evidence": "Numerical experiments show improved convergence and illustrate the robustness of our method to out-of-distribution instances."}], "easy1_evidence": "Yet, the computational and communication burden of distributed optimization and GNE-seeking algorithms poses a major challenge to deployment at scale.", "easy2_evidence": "We propose a learning-to-optimize framework for decentralized markets that uses historical data to accelerate clearing algorithms without additional communication.", "topic_evidence": "We propose a learning-to-optimize framework for decentralized markets that uses historical data to accelerate clearing algorithms without additional communication.", "limit_evidence": ""}, "2611.21134": {"points": [{"subtitle": "데이터 기반 모델 세트 구축", "desc": "입력과 출력 데이터를 바탕으로 모델의 불확실성을 정량화하는 모델 세트를 만들었습니다. 각 예측 방향마다 남은 불확실성을 계산해서 제어에 반영하는 방식이에요.", "evidence": "A data-consistent model set quantifies the uncertainty remaining in each prediction direction."}, {"subtitle": "제약 조건 준수와 안전성 확보", "desc": "출력 이력의 불확실성을 전파하여 제약 조건에 대한 마진을 계산하고, 이를 통해 시스템이 안전하게 유지되도록 했습니다. 무한한 시간 동안 제약 조건을 만족하며 목표를 향해 나아갈 수 있음을 수학적으로 증명했거든요.", "evidence": "Under a common contraction condition in a selected history norm, explicit terminal feasibility inequalities certify infinite-horizon continuation under a held reference and yield a closed invariant admissible set."}, {"subtitle": "노이즈 환경으로의 확장", "desc": "측정값에 노이즈가 포함된 상황까지 고려하여 오차 변수 모델 세트를 유도했습니다. 실제 결합 벤치마크 테스트를 해봤더니, 기록이 길어질수록 예측 오차가 줄어들고 실제 모델과의 차이를 잘 메우는 것으로 나타났습니다.", "evidence": "On the coupled benchmark, longer nested records reduce one-step prediction disagreement at the probe regressor, and propagation accounts for most of the gap between the tube and true-model envelopes at the reported constraint row and prediction step."}], "easy1_evidence": "This paper constructs a data-driven reference governor (DDRG) from input--output data and supplied deterministic disturbance bounds.", "easy2_evidence": "A scalar update selects the largest certified step toward the requested reference, with recursive feasibility and constraint satisfaction from certified initialization.", "topic_evidence": "This paper constructs a data-driven reference governor (DDRG) from input--output data and supplied deterministic disturbance bounds.", "limit_evidence": ""}, "2611.21075": {"points": [{"subtitle": "이차 배낭 문제의 구조 활용", "desc": "연구진은 연속적인 이차 배낭 문제(quadratic knapsack problems)가 가진 스칼라 이중 구조를 활용했는데요. 이를 통해 문제의 해가 존재하는지 판단하는 필요충분조건을 찾아내고, 정확한 해를 구하는 절차를 만들었어요.", "evidence": "Exploiting the established scalar dual structure of continuous quadratic knapsack problems, we obtain a necessary and sufficient pointwise feasibility condition and an exact breakpoint-based solution procedure."}, {"subtitle": "계산 효율성과 단계 예측", "desc": "제안한 알고리즘은 n개의 입력에 대해 최대 2n번의 이벤트만 처리하면 되는데요. 만약 원래 입력값이 이미 안전한 범위에 있다면 최대 n번의 과정만으로 최적의 해를 찾아낼 수 있다는 장점이 있어요.", "evidence": "The algorithm requires at most 2n positive breakpoint events for n inputs, reducing to at most n events when the nominal input is admissible."}, {"subtitle": "수치적 검증과 안전성 확보", "desc": "구조화된 해법을 검증된 부동 소수점 제약 평가와 결합해서, 실제로 가능한 명령인지 아니면 불가능한 경우인지 명확히 구분할 수 있게 했는데요. 덕분에 수치적으로 해결되지 않는 경우까지 확실하게 걸러낼 수 있게 된 겁니다.", "evidence": "We further describe how the structured solution can be combined with verified floating-point constraint evaluation to distinguish certified feasible commands, certified infeasibility, and unresolved numerical cases."}], "easy1_evidence": "General-purpose QP solvers typically rely on numerical convergence criteria, which do not directly provide finite bounds on algorithmic steps or distinguish solver failure from mathematical infeasibility.", "easy2_evidence": "The resulting framework provides an exact and computationally predictable solution procedure for a practically relevant class of input-constrained CBF safety filters.", "topic_evidence": "This paper considers CBF-QPs with a single affine safety constraint, componentwise input bounds, and diagonal quadratic weights.", "limit_evidence": ""}, "2611.21036": {"points": [{"subtitle": "비근시안적 안전 필터 설계", "desc": "기존의 CBF 방식에 학습된 최적 비용 함수 근사치를 결합해, 매 순간의 개입이 아닌 전체 경로에서의 개입 노력을 최소화하도록 설계했어요. 이때 원래의 안전 조건은 그대로 유지하면서 벨만 잔차 제약 조건을 완화하는 방식을 썼다는 거예요.", "evidence": "This paper proposes a discrete-time non-myopic safety filter using a learned approximation of the optimal intervention cost-to-go over CBF-admissible policies."}, {"subtitle": "성능 보증 및 이론적 분석", "desc": "연구진은 최적 가치 함수나 근사 오차 범위 없이도 경로별 성능을 보증할 수 있는 방법을 도출했어요. 추가적인 가정하에서는 근사 오차와 허용 오차를 포함한 최적화 부족 범위를 명시적으로 계산할 수 있다고 주장했거든요.", "evidence": "We derive a trajectory-wise performance certificate that requires neither the optimal value function nor an approximation-error bound."}, {"subtitle": "충돌 회피 성능 검증", "desc": "100개의 새로운 초기 조건에서 실험한 결과, 기존 CBF 필터 대비 평균 누적 개입 노력을 약 50% 줄이는 성과를 냈어요. 세 개의 독립적인 네트워크에서도 일관된 개선 효과를 보였고, 온라인 계산 비용도 기존 예측 필터보다 적게 든다는 점을 확인했답니다.", "evidence": "Numerical results for a collision-avoidance problem show an approximately 50% reduction in mean cumulative intervention effort relative to conventional CBF filtering over 100 initial conditions not used during training or parameter selection."}], "easy1_evidence": "Control barrier function (CBF) safety filters minimize instantaneous deviation from a nominal control command, but a sequence of pointwise-minimal interventions need not minimize cumulative intervention effort.", "easy2_evidence": "Numerical results for a collision-avoidance problem show an approximately 50% reduction in mean cumulative intervention effort relative to conventional CBF filtering over 100 initial conditions not used during training or parameter selection.", "topic_evidence": "This paper proposes a discrete-time non-myopic safety filter using a learned approximation of the optimal intervention cost-to-go over CBF-admissible policies.", "limit_evidence": ""}, "2611.20889": {"points": [{"subtitle": "실험 환경과 제약 방식 비교", "desc": "연구진은 BOPTEST의 히트펌프 사례를 활용해 모델 예측 제어(MPC)와 강화 학습(RL) 환경에서 두 제약 방식을 비교했습니다. 소프트 방식은 가중치를 둔 MPC와 SAC, DDPG 학습기를 사용했고, 하드 방식은 정확한 페널티를 적용한 MPC와 라그랑주 기반 학습기를 사용했거든요. 각 방식이 에너지와 쾌적함 사이에서 어떤 성능을 내는지 측정해 본 겁니다.", "evidence": "To this end, we measure the difference in energy use between the two formulations on the BOPTEST bestest_hydronic_heat_pump case, in model predictive control (MPC) and in reinforcement learning (RL)."}, {"subtitle": "에너지 소비와 쾌적함의 상충 관계", "desc": "하드 제약 방식은 쾌적 범위를 더 잘 지키지만 소프트 제약 방식보다 에너지를 더 많이 소비하는 것으로 나타났는데요. 소프트 제약 방식에서 가중치를 높일수록 하드 제약 방식의 행동 양식과 비슷해진다는 점도 확인했습니다. 세 가지 가중치 제어기의 에너지-쾌적함 상충 관계 곡선은 서로 가깝게 위치하며, 가중치에 따라 운영 지점이 결정된다고 봤습니다.", "evidence": "We find that the hard formulations use more energy than the soft formulations at the largest weight, but violate the comfort bounds less."}, {"subtitle": "알고리즘 선택보다 중요한 제약 설정", "desc": "소프트 제약 방식 하에서 세 가지 알고리즘은 가중치에 따라 조금씩 다르긴 하지만 매우 유사한 운영 지점에 도달했는데요. 이는 냉난방 문제에서 알고리즘 자체의 차이보다는 제약 조건을 어떻게 설정하고 가중치를 어떻게 부여하느냐가 에너지 효율에 훨씬 더 큰 영향을 준다는 것을 의미합니다.", "evidence": "Under the soft formulation, the three algorithms reach very similar operating points, although at somewhat different weights."}], "easy1_evidence": "A building controller that keeps a zone within comfort bounds at minimum energy can treat the bounds as a soft constraint, by adding the weighted violation to its cost, or as a hard constraint.", "easy2_evidence": "For this HVAC problem, the formulation and the weight thus affect the energy use more than the choice of algorithm.", "topic_evidence": "We analyze the effect of the hard and the soft formulation of the same problem and isolate the effect of the formulation from the effect of the algorithm.", "limit_evidence": ""}, "2611.20836": {"points": [{"subtitle": "범용 FIM 추정기 도입", "desc": "기존의 수식 기반 방식에서 벗어나 시뮬레이션된 경로를 바탕으로 비트당 정보를 직접 평가하는 추정기를 만들었습니다. 이를 통해 복잡한 시스템에서도 정보 손실을 최소화하는 양자화기 설계가 가능해진 겁니다.", "evidence": "Its core is a universal FIM estimator that evaluates the information per bit from simulated trajectories, and the thresholds are designed by maximizing the estimated criterion under a bit budget."}, {"subtitle": "2단계 파라미터 식별", "desc": "시스템의 파라미터를 미리 알 수 없는 상황을 대비해 2단계 절차를 도입했습니다. 이 과정을 통해 미지의 파라미터 환경에서도 효율적으로 양자화기를 설계할 수 있도록 구성했습니다.", "evidence": "For unknown parameters, the design is implemented through a two-stage procedure."}, {"subtitle": "식별 오차 개선", "desc": "비선형 캐스케이드 탱크 예제에 적용해 본 결과, 단일 중앙값 임계값을 사용했을 때보다 식별 오차를 약 50% 줄이는 성과를 냈습니다. 수치 연구를 통해 참조 최적값에 근접한 성능을 확인했다는 점이 특징이에요.", "evidence": "Numerical studies on a quantized ARX system yield designs close to the reference optimum, while a nonlinear cascaded-tanks example reduces the identification error by about 50% relative to a single median threshold."}], "easy1_evidence": "Existing methods, however, typically rely on closed-form expressions of the FIM.", "easy2_evidence": "This paper proposes a universal quantizer design method for general systems with memory.", "topic_evidence": "This paper proposes a universal quantizer design method for general systems with memory.", "limit_evidence": ""}, "2611.20775": {"points": [{"subtitle": "이벤트 기반 스트레스 테스트", "desc": "시스템 상태를 부분적으로만 볼 수 있는 환경에서도 잘 작동하도록, 문제를 부분 관찰 마르코프 결정 과정(POMDP)으로 재구성했어요. 과거의 관찰 이력을 기억하고 활용하는 순환 근접 정책 최적화 기법을 적용해서, 더 똑똑하게 위험 시나리오를 찾아내도록 만든 거예요.", "evidence": "This method employs Recurrent Proximal Policy Optimization to exploit observation histories when selecting adversarial actions."}, {"subtitle": "다중 적대적 선박 제어", "desc": "선박 운항 중 충돌 회피 시스템을 시험하기 위해 여러 대의 적대적 목표 선박을 배치했는데요, 중간 경유지 샘플링(Intermediate Waypoint Sampling) 기능을 확장해서 각 선박의 경로를 독립적으로 제어할 수 있게 했어요. 덕분에 실제 상황과 비슷한 충돌 유도 시나리오를 더 잘 만들어낼 수 있게 된 겁니다.", "evidence": "An extended Intermediate Waypoint Sampling mechanism enables independent multi-adversary trajectory control and supports the generation of realistic collision-inducing scenarios."}, {"subtitle": "평가 결과 및 확장성", "desc": "실험을 해 봤더니 학습된 스트레스 테스트 정책이 다양한 조우 상황에서도 잘 작동했고, 추가 학습을 통해 성능을 더 높일 수도 있었어요. 심지어 테스트 대상인 충돌 회피 시스템을 다른 버전으로 바꿔도 여전히 효과적이었다고 연구진은 주장했습니다.", "evidence": "The experiment demonstrate that the learned stress-testing policy generalizes across different encounter cases, can be further improved through continued training, and can be made effective when the collision- avoidance system under test is replaced by another version."}], "easy1_evidence": "However, black-box co-simulation may provide only partial access to the system state required by conventional Markov decision process formulations.", "easy2_evidence": "To address this limitation, we proposed Event-Based Adaptive Stress-Testing version 2, a co-simulation-based safety-assessment method formulated as a partially observable Markov decision process.", "topic_evidence": "These results demonstrate the method's potential for scalable black-box safety assessment of complex maritime cyber-physical systems.", "limit_evidence": ""}, "2611.20708": {"points": [{"subtitle": "쿱만 시간 논리(KTL) 도입", "desc": "기존의 신호 시간 논리를 검토한 뒤, 비선형 시스템을 다루기 위한 새로운 논리 체계인 KTL을 제안했어요. 여기에는 논리적 구문과 불리언 의미론, 그리고 양적 의미론이 모두 포함되어 있거든요. 뭔 소리냐면, 비선형 시스템의 복잡한 움직임을 수학적으로 엄밀하게 정의할 수 있는 틀을 마련했다는 말이에요.", "evidence": "We first review signal temporal logic and then introduce KTL, including its syntax, Boolean semantics, and quantitative semantics."}, {"subtitle": "모델 예측 제어(MPC) 공식화", "desc": "KTL로 기술된 제어 사양을 바탕으로 모델 예측 제어(MPC)를 수행하는 새로운 공식을 세웠어요. 제어기가 시스템의 복잡한 동역학을 고려하면서도 목표를 달성할 수 있도록 수학적 설계를 한 거예요. 쉽게 말하면, KTL이라는 언어로 명령을 내리면 MPC가 그에 맞춰 시스템을 움직이게 만든 셈입니다.", "evidence": "Next, we propose a formulation of Model Predictive Control (MPC) from a control specification described by KTL."}, {"subtitle": "AC-DC 전력 변환 적용", "desc": "제안한 MPC 방식이 실제로 잘 작동하는지 확인하기 위해 AC-DC 전력 변환 설계에 적용해 봤어요. 그 결과, 설계의 신뢰성을 확보하면서도 계산 효율성 면에서 효과적이라는 점을 입증했거든요. 복잡한 전력 변환 시스템을 제어하는 데 있어 실용적인 가능성을 보여준 겁니다.", "evidence": "Effectiveness and computational efficiency of the proposed MPC formulation are evaluated by applying it to a reliable design of AC-DC power conversion."}], "easy1_evidence": "This paper proposes a novel temporal logic, which we call Koopman Temporal Logic (KTL), towards a formal method in which Koopman operator theory provides a mathematical way to verify and control systems with nonlinear dynamics.", "easy2_evidence": "Effectiveness and computational efficiency of the proposed MPC formulation are evaluated by applying it to a reliable design of AC-DC power conversion.", "topic_evidence": "This paper proposes a novel temporal logic, which we call Koopman Temporal Logic (KTL), towards a formal method in which Koopman operator theory provides a mathematical way to verify and control systems with nonlinear dynamics.", "limit_evidence": ""}, "2611.20689": {"points": [{"subtitle": "CPP-ECBF 제어 기법", "desc": "등각 예측 프로그래밍(conformal predictive programming)과 확률적 환경 제어 장벽 함수(probabilistic environmental control barrier functions)를 결합한 방식이에요. 이를 통해 환경의 분포를 몰라도 유한한 시간 동안 정해진 확률로 안전을 보장할 수 있는 제어 제약을 만들어 냅니다.", "evidence": "For separable environmental safety functions and i.i.d. uncertainty, CPP-ECBF converts the probabilistic safety condition into a sample-based deterministic control constraint that provides finite-horizon safety with prescribed probability 1-epsilon and calibration confidence 1-beta."}, {"subtitle": "적응형 크루즈 컨트롤 적용", "desc": "실제 주행 상황인 적응형 크루즈 컨트롤(adaptive cruise control)에 이 방식을 적용해 봤는데요, 오프라인에서 구한 불확실성 범위를 바탕으로 차량 가속도의 상한선을 명확한 선형식으로 도출했습니다. 이 상한선은 이차 계획법(quadratic-programming) 기반의 안전 필터를 통해 강제로 적용되도록 설계했어요.", "evidence": "For adaptive cruise control, an offline conformal uncertainty bound yields an explicit linear upper bound on the ego-vehicle acceleration, which is enforced by a quadratic-programming safety filter."}, {"subtitle": "성능 검증 결과", "desc": "10,000번의 몬테카를로 시뮬레이션을 수행한 결과, 99.97%의 시행에서 안전 기준을 만족하는 성과를 보였습니다. 이는 당초 설정한 85%의 신뢰 수준을 크게 뛰어넘는 수치이며, 기존의 보수적인 방식보다 가속도 상한을 평균 5.90 m/s^2만큼 높여 효율성을 개선했다고 연구진은 주장했습니다.", "evidence": "In 10,000 Monte Carlo trials, 99.97% of trials satisfied the finite-horizon safety criterion, exceeding the prescribed confidence of 85%."}], "easy1_evidence": "Safety control under environmental uncertainty is challenging when the uncertainty distribution is unknown and reliable support bounds are unavailable.", "easy2_evidence": "Moreover, CPP-ECBF reduced the conservatism of worst-case robust enforcement, increasing the admissible acceleration upper limit by 5.90 m/s^2 on average.", "topic_evidence": "This paper introduces CPP-ECBF, a distribution-free approach that combines conformal predictive programming with probabilistic environmental control barrier functions.", "limit_evidence": ""}, "2611.20457": {"points": [{"subtitle": "데이터 분석 방법", "desc": "연구진은 오랜 기간 쌓인 CV의 정지 위치 분포를 활용하는 방식을 택했는데요, 이는 신호 주기가 반복될 때마다 차량이 어디에 멈추는지 데이터를 모아 정체 밀도와 포화 교통류를 계산하는 방식입니다.", "evidence": "This paper analyze such methods, in which the jam density and saturation flow are estimated from long-term historical distribution of low penetration rate CV stop positions accumulated over many signal cycles."}, {"subtitle": "실제 데이터 검증", "desc": "도쿄의 교차로 세 곳에서 6개월간 수집한 1~3% 보급률의 데이터를 사용해 검증을 마쳤는데요, 영상으로 직접 확인한 기준값과 비교했을 때 포화 교통류 추정치가 10% 정도의 오차 범위 내에 들어왔다고 밝혔습니다.", "evidence": "The methods are evaluated using actual CV trajectory data collected at three signalized intersections in Tokyo for six months, with a penetration rate on the order of 1--3%."}, {"subtitle": "신뢰도 평가 기준 마련", "desc": "추정된 값이 얼마나 믿을 만한지 스스로 판단할 수 있는 정량적인 기준도 함께 제시했는데요, 이는 데이터가 부족한 상황에서도 추정 결과의 정확성을 가늠할 수 있게 돕는다는 장점이 있습니다.", "evidence": "Furthermore, quantitative criteria for self-evaluation of reliability of the estimates are proposed."}], "easy1_evidence": "However, methods for estimating the jam density itself from low penetration rate CV trajectories have received little attention.", "easy2_evidence": "The estimators mostly agree on a jam spacing close to 8~m at the sites at which the queueing pattern is well developed, and the saturation flow estimates lie within roughly 10% of an independent video-based reference at those sites.", "topic_evidence": "This paper analyze such methods, in which the jam density and saturation flow are estimated from long-term historical distribution of low penetration rate CV stop positions accumulated over many signal cycles.", "limit_evidence": ""}, "2611.20438": {"points": [{"subtitle": "리 대수와 임베딩의 필요조건", "desc": "연구진은 시스템의 드리프트와 제어 벡터 필드로 생성된 리 대수의 유한 차원성이 임베딩 존재의 필수 조건임을 증명했어요. 즉, 이 차원이 무한하면 쿱만 빌리니어 형태로 표현하는 게 불가능하다는 뜻이에요.", "evidence": "First, we show that the finite-dimensionality of the generated Lie algebra is a necessary condition for the existence of a Koopman bilinear embedding."}, {"subtitle": "충분조건 유도", "desc": "리 대수 내부에 0이 아닌 닐포텐트 아이디얼이 존재할 경우, 임베딩이 가능해지는 충분조건을 새롭게 유도했어요. 이를 통해 특정 구조를 가진 시스템에서 임베딩을 구성할 수 있는 수학적 근거를 마련한 셈이에요.", "evidence": "Next, when the generated Lie algebra contains a nonzero nilpotent ideal, we derive a sufficient condition for the existence of such an embedding."}, {"subtitle": "이차 다항식 시스템 예시", "desc": "이차 다항식 시스템을 예로 들어 분석했더니, 유한 차원 리 대수 조건이 벡터 필드에 매우 엄격한 제약을 준다는 점을 확인했어요. 연구진은 이를 근거로 일반적인 시스템에서 정확한 유한 차원 임베딩을 찾는 것이 드문 일이라고 주장했어요.", "evidence": "Finally, through an example of a quadratic polynomial system, we demonstrate that the finite-dimensionality of the generated Lie algebra imposes strong restrictions on the vector fields, suggesting that exact finite-dimensional Koopman bilinear embeddings may be nongeneric."}], "easy1_evidence": "First, we show that the finite-dimensionality of the generated Lie algebra is a necessary condition for the existence of a Koopman bilinear embedding.", "easy2_evidence": "Finally, through an example of a quadratic polynomial system, we demonstrate that the finite-dimensionality of the generated Lie algebra imposes strong restrictions on the vector fields, suggesting that exact finite-dimensional Koopman bilinear embeddings may be nongeneric.", "topic_evidence": "In this paper, we investigate, from a Lie-algebraic perspective, conditions under which a control-affine system admits a finite-dimensional Koopman bilinear embedding.", "limit_evidence": ""}, "2611.20399": {"points": [{"subtitle": "탄력적 의미 통신(ESC)의 구조", "desc": "ESC는 수직적 탄력성과 수평적 탄력성이라는 두 가지 축으로 움직이는데요. 수직적으로는 기존 기능의 강도를 조절하고, 수평적으로는 작업에 참여하는 기능의 범위를 재구성하는 방식이에요. 이 두 축은 추가적인 정보와 계산이 가져다주는 한계 가치를 기준으로 서로 연결되어 작동합니다.", "evidence": "ESC comprises two complementary dimensions: vertical elasticity adjusts the execution intensity of existing capabilities, while horizontal elasticity reconfigures the participating capability set."}, {"subtitle": "암묵적 추론 기반의 장치-에지 메커니즘", "desc": "연구진은 이 통신 방식을 구현하기 위해 장치와 에지 서버가 협력하는 메커니즘을 제안했는데요. 장치에서는 매개변수를 공유하며 추론 깊이를 조절하고, 에지 서버에서는 중간 추론 상태를 무선으로 넘겨받아 작업을 이어가는 방식이에요. 뭔 소리냐면, 장치 혼자 다 처리하지 않고 에지 서버와 상태를 주고받으며 효율을 높인다는 말이에요.", "evidence": "To realize ESC, we propose an implicit-reasoning-enabled device--edge mechanism that supports variable-depth local inference through shared-parameter state updates and edge-side continuation through wireless transfer of intermediate reasoning states."}, {"subtitle": "스도쿠-익스트림 실험 결과", "desc": "스도쿠-익스트림 문제를 통해 검증해 봤더니, 추가적인 추론이 주는 이득은 무선 통신 환경에 따라 달라진다는 점을 확인했는데요. 작업 상황을 인식해 에지를 호출하면 통신 상태가 좋지 않아도 상태 전송 부담을 크게 줄이면서 정확도를 지킬 수 있다는 결과가 나왔습니다.", "evidence": "Experiments on Sudoku-Extreme demonstrate that the benefits of additional inference depend on wireless conditions, while task-aware edge invocation can preserve task accuracy with substantially lower state-transfer overhead."}], "easy1_evidence": "Existing adaptive semantic communication schemes primarily adjust semantic representations and resource configurations within predefined processing scales and capability sets, which may be insufficient for evolving task requirements.", "easy2_evidence": "Experiments on Sudoku-Extreme demonstrate that the benefits of additional inference depend on wireless conditions, while task-aware edge invocation can preserve task accuracy with substantially lower state-transfer overhead.", "topic_evidence": "To address this gap, we introduce elastic semantic communications (ESC), a task-driven framework that extends semantic adaptation to the runtime execution and participation of task-supporting capabilities.", "limit_evidence": ""}, "2611.20392": {"points": [{"subtitle": "전력 소비 확률적 추정", "desc": "실제 건설 현장 데이터를 바탕으로 전기 굴착기의 각 작업 단계별 전력 소비량을 베이지안 선형 회귀로 분석했어요. 작업 중에 생기는 불확실성까지 고려해서 전력 소비 분포를 뽑아낸 겁니다.", "evidence": "We use Bayesian linear regression to obtain the subactivity power distributions, accounting for their operational uncertainty."}, {"subtitle": "통합 스케줄링 최적화", "desc": "전기 중장비의 작업과 충전, 그리고 이동식 충전소의 경로와 충·방전 계획을 한꺼번에 짜는 혼합 정수 계획법을 만들었어요. 전기 요금과 탄소 배출량, 작업 완료 시간까지 모두 고려해서 최적의 값을 찾으려는 시도예요.", "evidence": "Second, we formulate a mixed-integer program that jointly schedules CEV work and charging together with MCS routing, charging, and discharging, optimizing electricity costs, carbon emissions, work completion, and MCS travel."}, {"subtitle": "모델 예측 제어 성능 검증", "desc": "제안한 제어 방식인 시나리오 기반 모델 예측 제어(SB-MPC)를 기존 방식과 비교해 봤는데요. 운영 비용을 기준 대비 60.2% 낮추는 성과를 보였고, 피드백을 활용한 예측 제어가 효과적임을 입증했어요.", "evidence": "Realistic simulations show that SB-MPC performs the best, lowering the operating costs by 60.2% relative to the open-loop baseline, and by 23.3% relative to CE-MPC, demonstrating the efficacy of incorporating predictive control with feedback."}], "easy1_evidence": "The adoption of construction electric vehicles (CEVs) is held back by sparse on-site charging infrastructure, limited mobility, and insufficient knowledge of their power consumption.", "easy2_evidence": "Realistic simulations show that SB-MPC performs the best, lowering the operating costs by 60.2% relative to the open-loop baseline, and by 23.3% relative to CE-MPC, demonstrating the efficacy of incorporating predictive control with feedback.", "topic_evidence": "In this paper, we address these gaps, first, by estimating the power of each subactivity of a representative CEV (a compact electric excavator) based on real-world construction demonstration data.", "limit_evidence": ""}, "2611.20320": {"points": [{"subtitle": "경로 참조 방식의 재설계", "desc": "기존처럼 앞차만 따라가면 도로가 굽어지거나 옆으로 밀릴 때 오차가 무한히 쌓이게 되는데요, 연구진은 리더 차량과 바로 앞 차량의 경로 정보를 함께 참조하는 방식을 도입했습니다. 이렇게 하면 대열이 아무리 길어져도 오차가 일정 범위 안에 머물게 된다는 거예요.", "evidence": "We derive a condition under which combining the trails of the leader and the predecessor keeps the errors bounded for any convoy length, and show that following the predecessor alone lets the errors accumulate without bound, even without amplification, on roads that end turned or shifted sideways."}, {"subtitle": "적응형 피드포워드 제어", "desc": "실제 주행에서는 차량의 짐 무게나 타이어 강성이 변하면서 곡선 주행 시 오차가 발생하는데요, 연구진은 이를 하나의 계수로 정의하고 적응형 법칙을 통해 이 값을 실시간으로 추정하도록 했습니다. 뭔 소리냐면, 차량 상태가 변해도 그에 맞춰 제어 값을 스스로 수정해 오차를 없앤다는 말이에요.", "evidence": "Passenger and cargo loads and tire stiffness vary in practice, and we show that they enter the curvature feedforward through a single coefficient, whose mismatch leaves steady offsets on curves."}, {"subtitle": "11대 차량 대열 시뮬레이션", "desc": "제안한 제어 방식의 성능을 검증하기 위해 11대의 차량으로 구성된 대열 시뮬레이션을 수행했습니다. 그 결과, 분석한 대로 오차가 효과적으로 제어되고 안정성이 유지됨을 확인했습니다.", "evidence": "Simulations of an eleven vehicle convoy confirm the analysis."}], "easy1_evidence": "Since each vehicle's tracking error enters the reference of the next, lateral errors can grow along the convoy.", "easy2_evidence": "We propose an adaptive law that estimates this coefficient on curves and removes the offsets.", "topic_evidence": "This paper presents a course referenced formulation of trail following in arc length, in which each follower takes the direction of its fitted trail as its heading reference.", "limit_evidence": ""}, "2611.20293": {"points": [{"subtitle": "모델 정보가 필요 없는 공격 설계", "desc": "연구진은 차량의 주행 데이터를 수동적으로 기록해 VARX 모델을 학습시켰고, 이를 통해 시스템 정보를 모르는 상태에서도 공격 시퀀스를 구성했어요. 차량의 동역학이나 소음 분포 같은 복잡한 정보가 전혀 필요 없다는 점이 특징이에요.", "evidence": "We develop a model-free FDI attack that uses a Vector Autoregressive model with Exogenous inputs (VARX), identified from passively recorded nominal measurements, to characterize a compromised channel and construct attack sequences within a data-calibrated residual envelope."}, {"subtitle": "차선 유지 시스템 공격 성능 검증", "desc": "차선 유지 주행 환경에서 실험해 본 결과, 차량을 1.25m 옆으로 밀어내어 차선 밖으로 벗어나게 만들었어요. 공격 기간 동안 여러 침입 탐지 시스템(IDS)의 경보율은 2.4% 이하로 유지되어, 기존 방식보다 훨씬 은밀하게 작동했거든요.", "evidence": "In a closed-loop lane-keeping benchmark, the attack induces a 1.25 m lateral displacement, exceeding the specified 0.9 m half-lane width, and keeps the vehicle outside the lane corridor for 9.21 s."}, {"subtitle": "위험 평가 체계의 개선 필요성", "desc": "기존의 위험 평가 방식은 탐지 가능성을 제대로 반영하지 못한다는 문제가 있는데요, 연구진은 이를 보완하기 위해 탐지 조건을 고려한 새로운 위험 평가 공식을 제안했어요. 보안 위험을 평가할 때 공격자가 가진 지식 수준과 실제 탐지 가능성을 반드시 고려해야 한다고 주장하는 겁니다.", "evidence": "We further show that conventional impact-and-feasibility risk scoring can assign identical risk to attacks with substantially different detector responses, and introduce a detection-conditioned risk formulation to distinguish them."}], "easy1_evidence": "Conventional stealthy false-data-injection (FDI) attacks often assume privileged knowledge of system dynamics, estimator parameters, or detector statistics, understating the feasibility of adversaries with limited system information.", "easy2_evidence": "The proposed adversary matches the impact and evasion of a privileged model-based adversary while requiring 13 fewer attack-potential points, raising its assessed feasibility from Low to High under the considered ISO/SAE 21434 Threat Analysis and Risk Assessment (TARA).", "topic_evidence": "This paper investigates a model-free stealthy adversary targeting in-vehicle networks and its implications for automotive cybersecurity risk assessment.", "limit_evidence": ""}, "2611.20266": {"points": [{"subtitle": "2차원 평면 분할", "desc": "복잡한 3차원 유도 문제를 두 개의 2차원 교전 평면으로 나누어 접근했어요. 이렇게 하면 각 평면에서 필요한 제어 전략을 독립적으로 설계할 수 있다는 장점이 있거든요.", "evidence": "The guidance problem is decomposed into two two-dimensional (2D) engagement planes."}, {"subtitle": "2단계 비례 항법 적용", "desc": "첫 번째 단계에서는 가상 목표물을 이용해 미사일의 속도 방향을 맞추고, 두 번째 단계에서는 시간 변화에 따라 편향된 비례 항법을 적용해 궤적을 정밀하게 다듬었어요. 이를 통해 시야각 제한을 어기지 않고도 목표 각도에 도달할 수 있게 만든 겁니다.", "evidence": "In the second plane, a two-stage time-varying biased PNG (TVBPN) strategy is utilized to accurately shape the trajectory and achieve the desired terminal impact angle while maintaining compliance with FOV limitations."}, {"subtitle": "가속도 연속성 확보", "desc": "가상 목표물의 위치를 적절히 설정해서 첫 번째 단계와 두 번째 단계가 전환될 때 가속도가 끊기지 않고 매끄럽게 이어지도록 했어요. 연구진은 수치 시뮬레이션을 통해 이 유도 법칙이 실제로 유효하고 실행 가능하다는 점을 증명했거든요.", "evidence": "The position of the virtual target point ensures a smooth and continuous lateral acceleration at the transition between the first and second stages."}], "easy1_evidence": "This paper presents a novel impact angle control guidance law to address the challenge of achieving any desired impact angle while satisfying the seeker's Field Of View (FOV) limit and maintaining acceleration continuity.", "easy2_evidence": "In the second plane, a two-stage time-varying biased PNG (TVBPN) strategy is utilized to accurately shape the trajectory and achieve the desired terminal impact angle while maintaining compliance with FOV limitations.", "topic_evidence": "This paper presents a novel impact angle control guidance law to address the challenge of achieving any desired impact angle while satisfying the seeker's Field Of View (FOV) limit and maintaining acceleration continuity.", "limit_evidence": ""}, "2611.20256": {"points": [{"subtitle": "핀슬러 거리를 이용한 수축 분석", "desc": "두 경로 사이의 거리를 측정하기 위해 핀슬러 거리를 도입했어요. 이 방식은 리만 거리와 노름 기반 거리를 모두 포함하는 일반적인 틀이라서, 다양한 확률 시스템의 수축 성질을 분석하는 데 유용하다는 거예요.", "evidence": "We consider two trajectories driven by a common noise process and measure their separation using Finsler distances, which encompass Riemannian and norm-induced distances."}, {"subtitle": "수축 조건의 수학적 규명", "desc": "L^p-수축과 거의 확실한 수축이라는 두 가지 개념을 정의하고, 이들이 성립하기 위한 필요충분조건을 미분 형태로 제시했어요. 가벼운 가정만으로도 수축 여부를 판별할 수 있는 수학적 근거를 마련한 겁니다.", "evidence": "Each notion is characterized by a differential condition that is necessary and sufficient for contraction under mild hypotheses."}, {"subtitle": "노이즈 유도 동기화와 강건성 확인", "desc": "연구진은 이 이론을 활용해 노이즈로 인해 시스템들이 동기화되는 현상을 분석했어요. 파라미터가 조금씩 변하더라도 시스템이 얼마나 잘 버티는지 그 강건성을 정량적으로 평가할 수 있음을 보여줬거든요.", "evidence": "As an illustration, we apply the established theory to analyze noise-induced synchronization and quantify its robustness with respect to parameter perturbations."}], "easy1_evidence": "This paper studies contraction properties of stochastic dynamical systems governed by It\\^o stochastic differential equations.", "easy2_evidence": "Two notions of contraction are then investigated: $L^p$-contraction, defined by exponential decay of the $L^p$-norm (or the $p$-th moment) of the distance, and almost sure contraction, defined by exponential decay of the distance along almost every sample path.", "topic_evidence": "This paper studies contraction properties of stochastic dynamical systems governed by It\\^o stochastic differential equations.", "limit_evidence": ""}, "2611.20157": {"points": [{"subtitle": "확장 상태 공간에서의 학습", "desc": "데이터를 단순히 변환하는 대신 상태 변수와 이미 알고 있는 비선형성을 합친 확장 상태에서 동역학을 학습하는 방식을 택했어요. 이렇게 하면 변환 관계를 그대로 활용해 비선형성까지 정확하게 얻어낼 수 있거든요.", "evidence": "Instead, we learn the dynamics in the extended state, i.e., the state together with the known nonlinearities, and obtain the dynamics of the nonlinearities via the exact lifting relations."}, {"subtitle": "KINDy 알고리즘의 차수 선택", "desc": "연구진이 제안한 KINDy는 커널 능선 회귀를 통해 각 성분의 차수를 먼저 결정해요. 데이터에 노이즈가 적고 정규화가 적절하다면, 이 방식이 실제 차수보다 낮게 추정하지 않는다는 점을 수학적으로 증명했거든요.", "evidence": "We prove that, for sufficiently small noise and regularization, provided the data satisfy a rank condition, the selected degree never underestimates the true degree."}, {"subtitle": "카트-폴 시스템 성능 검증", "desc": "카트-폴(cart-pole) 시스템에 적용해 봤더니, 기존의 전체 라이브러리 기반 희소 회귀보다 최대 8.5배 빠르게 모델을 찾아냈어요. 모델의 간결함은 유지하면서도 테스트 오차는 더 낮거나 비슷한 수준을 보였다고 연구진은 주장했습니다.", "evidence": "On the cart-pole system, KINDy recovers the true degrees at low noise levels and achieves speedups of up to 8.5 over sparse regression on the full library, while in almost all cases yielding models that are at least as sparse and have lower or equal test errors."}], "easy1_evidence": "We show that fitting lifted polynomial models directly to lifted data is problematic, since the exact lifting constraints render the lifted derivatives linearly dependent.", "easy2_evidence": "To avoid the combinatorially large libraries that sparse regression requires when the polynomial degrees are unknown, we propose KINDy, which selects the degree of each component by kernel ridge regression before applying sparse regression to the correspondingly reduced library.", "topic_evidence": "Kernel-Guided Learning of Lifted Sparse Polynomial Models of Nonlinear Dynamical Systems", "limit_evidence": ""}, "2611.20098": {"points": [{"subtitle": "깊이 정보 없는 기하학적 관측", "desc": "추적 중인 각 점의 방향과 회전 보정된 미분 값을 활용해서 로봇 본체 프레임의 속도에 대한 제약 조건을 만들었어요. 이 방식은 깊이를 직접 추정하거나 움직이는 방향을 재구성할 필요가 없다는 특징이 있거든요.", "evidence": "For each tracked point, the bearing and its rotationally compensated derivative give a depth-free homogeneous constraint on the body-frame velocity."}, {"subtitle": "중력 보조를 통한 오차 독립성 확보", "desc": "보조 중력 상태를 도입해서 6차원 속도-중력 오차 역학을 자세 보정으로부터 독립시켰어요. 이렇게 하면 시스템의 관측 가능성이 관성 방향과 그 미분 값으로 형성된 행렬의 지속적인 자극에 따라 결정된다는 점을 증명했거든요.", "evidence": "The auxiliary gravity state makes the six-dimensional body-frame velocity-gravity error dynamics independent of the attitude correction, and their uniform observability is shown to be equivalent to persistent excitation of a matrix formed from the inertial bearings and their derivatives."}, {"subtitle": "시뮬레이션을 통한 성능 검증", "desc": "연구진은 시뮬레이션을 통해 제안한 방식이 초기 오차를 어떻게 회복하는지, 그리고 측정값이 흔들릴 때 얼마나 민감하게 반응하는지를 확인했어요. 이를 통해 제안한 관측기가 실제 환경에서 안정적으로 작동할 수 있음을 보여준 겁니다.", "evidence": "Simulations illustrate the excitation condition, recovery from initial errors, and sensitivity to perturbed measurements."}], "easy1_evidence": "This paper presents a geometric observer for monocular visual-inertial odometry driven by individual optical-flow constraints.", "easy2_evidence": "Under this condition, the body-frame velocity and gravity errors converge globally and uniformly exponentially, and a gravity-based attitude correction renders the combined velocity, gravity, and reduced-attitude error almost globally asymptotically stable and locally uniformly exponentially stable.", "topic_evidence": "This paper presents a geometric observer for monocular visual-inertial odometry driven by individual optical-flow constraints.", "limit_evidence": "Under this condition, the body-frame velocity and gravity errors converge globally and uniformly exponentially, and a gravity-based attitude correction renders the combined velocity, gravity, and reduced-attitude error almost globally asymptotically stable and locally uniformly exponentially stable."}, "2611.19970": {"points": [{"subtitle": "물리 기반의 통합 모델링", "desc": "건물의 열 반응을 분수 차수의 커널로 표현하여 온도와 부하 사이의 지연 현상을 수학적으로 증명했습니다. 이를 통해 구조적 변화와 예측 오차의 긴 기억 현상을 동시에 고려할 수 있게 된 겁니다.", "evidence": "We prove that averaging building responses over Cole-Cole distributed time constants yields a fractional temperature kernel with nonnegative weights exactly when its order is at most one."}, {"subtitle": "구조적 변화와 기억 현상의 동시 추정", "desc": "기존의 베이지안 정보 기준은 긴 기억 현상을 무시해서 잘못된 변화 지점을 찾아내는 문제가 있었는데요. 연구진은 이를 해결하기 위해 변화 지점 탐지기와 기억 현상을 함께 추정하는 방식을 도입했고, 덕분에 오경보율을 원하는 수준 이하로 유지할 수 있게 됐습니다.", "evidence": "A Bayesian information criterion that ignores long memory selects spurious breaks with probability tending to one, so breaks and memory are estimated jointly, and an online break detector keeps its false-alarm rate below any prescribed level."}, {"subtitle": "예비력 산정 및 성능 검증", "desc": "긴 기억 현상으로 인해 필요한 저장 에너지가 시간 지평의 제곱근보다 빠르게 증가한다는 점을 파악하여, 이차 원뿔 계획법을 통해 예비력을 산정했습니다. 실제 데이터로 검증한 결과, 기존 방식보다 에너지 한계 초과 빈도를 크게 낮추는 효과를 보였습니다.", "evidence": "Its reserves breach the storage energy limit on 4.1% and 8.5% of days, against 36.7% and 57.5% with error correlations ignored."}], "easy1_evidence": "Both depend on three effects that are usually modeled separately, namely the thermal inertia of buildings, which makes load lag temperature, structural breaks, which shift demand, and the long memory of forecast errors, which keeps them from cancelling out.", "easy2_evidence": "On New England and Mid-Atlantic data including the 2020 pandemic, the proposed framework improves on the best of ten benchmarks by 15.7% and 10.3% in mean absolute percentage error.", "topic_evidence": "Physics-Informed Fractional Load Forecasting With Memory-Aware Break Detection for Reserve Scheduling", "limit_evidence": ""}, "2611.19852": {"points": [{"subtitle": "희소 피드백 제어 설계", "desc": "연구진은 최대 s개의 0이 아닌 행을 가진 피드백 행렬들을 구성해서 시스템을 제어하는 방식을 택했습니다. 스위칭 시스템 이론을 활용해 시스템이 안정화 가능하다면 어떤 s값에 대해서도 안정성을 보장하는 입력 신호가 존재함을 확인했거든요.", "evidence": "Using switched systems theory, we show that there exists an s-sparse input for any sparsity level s >= 1 that ensures stability when the continuous-time LDS is stabilizable."}, {"subtitle": "제어 에너지 최적화", "desc": "피드백 행렬의 프로베니우스 노름(Frobenius norm)을 최소화해서 제어에 들어가는 에너지를 줄였습니다. 계산 결과 s가 커질수록 필요한 제어 에너지가 s의 제곱에 반비례해서 줄어든다는 사실을 밝혀냈다는 거예요.", "evidence": "We show that an upper bound on the control energy required for stabilization using an s-sparse input is inversely proportional to s^2, while maintaining the same exponential stability rate."}, {"subtitle": "이벤트 기반 통신 효율화", "desc": "희소 입력 설계에 이벤트 트리거 규칙을 더해서 통신 자원 사용량을 한 번 더 줄였습니다. 이 전략을 쓰면 상태 피드백과 출력 피드백 환경 모두에서 시스템을 안정화할 수 있다는 점을 질량-용수철 시스템 예시로 보여줬습니다.", "evidence": "Our sparse and event-triggered control strategy ensures that any stabilizable continuous-time LDS can be stabilized using s-sparse inputs under both state feedback and output feedback, for any s>=1."}], "easy1_evidence": "Efficient use of communication resources is crucial for stabilizing a networked control system.", "easy2_evidence": "We show that an upper bound on the control energy required for stabilization using an s-sparse input is inversely proportional to s^2, while maintaining the same exponential stability rate.", "topic_evidence": "This work considers the problem of stabilizing a continuous-time linear dynamical system (LDS) using s-sparse inputs.", "limit_evidence": ""}, "2611.19482": {"points": [{"subtitle": "MISO-FIR 모델 구축", "desc": "먼저 쉽게 얻을 수 있는 센서 신호를 활용해서 직접 측정하기 어려운 힘 신호를 추정하는 MISO-FIR 모델을 만들었어요. 이 모델을 통해 복잡한 장비 없이도 필요한 데이터를 확보하는 셈이에요.", "evidence": "A MISO-FIR model is first constructed using easily accessible sensor signals to estimate the unmeasurable force signal."}, {"subtitle": "불확실성 기반 환경 분류", "desc": "추정된 매개변수의 불확실성을 신뢰 타원체로 나타내고, 가설 검정을 통해 통계적으로 비슷한 주행 환경을 자동으로 묶었어요. 사람이 일일이 라벨을 붙이지 않아도 환경을 구분할 수 있다는 게 핵심이에요.", "evidence": "The uncertainty of estimated parameters is quantified through confidence ellipsoids, and pairwise hypothesis testing is developed to identify statistically similar working conditions."}, {"subtitle": "희소 매개변수 추정 및 성능 검증", "desc": "각 그룹 안에서 필요한 매개변수만 추정하는 방식을 썼는데, 실제 차량 데이터로 실험해 보니 기존의 거리 기반 방식보다 성능이 좋았어요. 모델 개수를 줄이면서도 특정 조건에 맞춘 모델만큼 정확한 결과를 냈다고 연구진은 밝혔습니다.", "evidence": "Experiments using real-world vehicle data demonstrate that the UACS framework achieves estimation accuracy comparable to condition-specific models while substantially reducing the number of required models and outperforming conventional distance-based clustering approaches."}], "easy1_evidence": "Accurate wheel center force (WCF) estimation is important for vehicle durability analysis and condition monitoring, whereas direct measurement requires dedicated transducers and increases instrumentation cost and complexity.", "easy2_evidence": "The UACS framework simultaneously reduces the number of required models and active parameters while maintaining estimation accuracy.", "topic_evidence": "This paper proposes an uncertainty-aware clustering and sparse parameter estimation framework (UACS) for WCF signal estimation under diverse and unlabeled working conditions.", "limit_evidence": ""}, "2611.19469": {"points": [{"subtitle": "궤적 모나드와 제어기 합성", "desc": "제어기를 모나드의 사상으로 정의하고, 제어기의 순차적 실행을 궤적 연결로 해석하는 구조를 설계했어요. 제어 장벽 함수(CBF)를 통한 안전성 보장 역시 이 범주 내의 하위 모나드로 대응시킬 수 있다는 점을 밝혀냈거든요.", "evidence": "Its Kleisli category treats controllers as morphisms and sequential execution as trajectory concatenation."}, {"subtitle": "안전성 보장을 위한 대수적 조건", "desc": "모든 제어기가 모나드 곱에 대해 닫혀 있는 공통 하위 모나드에 포함되어야 한다는 단 하나의 대수적 조건을 제시했어요. 이 조건은 왜 여러 장벽의 매끄러운 교집합은 안전한 합성을 지원하는지, 반대로 단계별로 장벽을 강제하는 방식은 왜 실패하는지를 수학적으로 설명해 줍니다.", "evidence": "All controllers must land in a common sub-monad, which is closed under the monad multiplication."}, {"subtitle": "실증 및 성능 검증", "desc": "단계별 제어 방식의 실패율을 베르누이 모델로 유도하고, 3,000개의 무작위 사례를 통해 검증했어요. 기존의 모든 장벽을 이차 계획법(QP)으로 동시에 강제하는 방식은 장벽 개수가 늘어날수록 성능이 떨어진다는 점을 확인했거든요.", "evidence": "The same sweep shows that the standard baseline degrades under constraint conflict as the barrier count grows."}], "easy1_evidence": "Sequential composition of safety-certified controllers for hybrid and non-smooth robotic systems is well studied piecewise.", "easy2_evidence": "Joint safety of composed controllers then follows from one algebraic condition.", "topic_evidence": "We construct a \\emph{trajectory monad} for Filippov-regular differential inclusions.", "limit_evidence": ""}, "2611.19428": {"points": [{"subtitle": "수소 실증 사업의 중요성", "desc": "수소 생산과 통합을 위한 실증 사업은 탄소 중립 에너지 시스템으로 나아가는 데 핵심적인 역할을 하고 있는데요. 전 세계적으로 정부의 강력한 지원을 받으며 수소 에너지 발전을 이끄는 중요한 동력이 되고 있다는 겁니다.", "evidence": "The implementation of hydrogen production and integration demonstration projects has received significant attention around the world and strong support from governments, highlighting the crucial role of such initiatives in the advancement of hydrogen energy."}, {"subtitle": "실제 산업 현장 분석의 필요성", "desc": "그동안 수소 기술에 대한 연구는 많았지만, 실제 현장에서 산업적으로 어떻게 적용되는지를 종합적이고 체계적으로 검토한 연구는 여전히 부족한 실정이었거든요. 연구진은 이런 공백을 메우는 것이 중요하다고 봤습니다.", "evidence": "However, research in this area remains limited, particularly in terms of comprehensive and systematic reviews of industrial practices under real-world conditions."}, {"subtitle": "13개 프로젝트 사례 연구", "desc": "연구진은 전 세계 13개의 모범적인 수소 실증 프로젝트를 선정해서 생산, 저장, 산업적 활용이라는 세 가지 측면에서 핵심 특징을 정리했습니다. 이를 통해 수소 에너지를 대규모로 보급하기 위한 실질적인 가이드라인을 제공하려는 거예요.", "evidence": "To bridge this gap, this article provides an in-depth review of hydrogen production, storage, and industrial applications, summarizing key features of thirteen exemplary hydrogen demonstration projects from around the world."}], "easy1_evidence": "Hydrogen technology has the potential to address various challenges related to integrating low- and zero-carbon energy sources, as well as achieving carbon neutrality.", "easy2_evidence": "To bridge this gap, this article provides an in-depth review of hydrogen production, storage, and industrial applications, summarizing key features of thirteen exemplary hydrogen demonstration projects from around the world.", "topic_evidence": "The goal is to offer insights and guidance for the large-scale deployment of hydrogen energy while identifying potential technological pathways for the future.", "limit_evidence": "However, research in this area remains limited, particularly in terms of comprehensive and systematic reviews of industrial practices under real-world conditions."}, "2611.19426": {"points": [{"subtitle": "고장 진단 알고리즘 최적화", "desc": "참새 탐색 알고리즘을 활용해 랜덤 포레스트 모델을 최적화함으로써 고장 진단의 정확도를 높였는데요. 덕분에 복잡한 시스템에서도 센서 3개라는 적은 자원만으로 다중 스위치 고장을 찾아낼 수 있게 됐습니다.", "evidence": "By optimizing a random forest algorithm with a sparrow search algorithm, high-precision multi-switch fault diagnosis is achieved using only three current sensors."}, {"subtitle": "고장 허용 운전 전략", "desc": "시스템에 고장이 발생하면 보조 스위치를 작동시켜서 운전을 멈추지 않고 이어가는 방식을 도입했는데요. 이를 통해 전해조에 안정적으로 전력을 공급할 수 있게 되었다는 겁니다.", "evidence": "Fault-tolerant operation of the system is achieved through an auxiliary switch after a failure."}, {"subtitle": "포트 간 전력 공유", "desc": "고장 상황에서도 출력 포트들 사이에서 전력을 자유롭게 나눌 수 있도록 설계했는데요. 결과적으로 수소 생산 시스템 전체의 효율과 안정성을 동시에 확보했다고 연구진은 주장했습니다.", "evidence": "Additionally, power sharing between output ports can be realized."}], "easy1_evidence": "Currently, there are no effective fault diagnosis or fault tolerance solutions for these systems.", "easy2_evidence": "This paper proposes a fault diagnosis method for open-circuit faults in a triple-port hydrogen converter and a corresponding fault-tolerant operating strategy.", "topic_evidence": "This paper proposes a fault diagnosis method for open-circuit faults in a triple-port hydrogen converter and a corresponding fault-tolerant operating strategy.", "limit_evidence": ""}, "2611.19272": {"points": [{"subtitle": "공간 모멘트 기반 형태 제어", "desc": "이미지를 샘플링해서 중심점과 분산으로 기본 형태를 잡고, 나머지 세부 모양은 정규화된 좌표계의 고차 모멘트로 인코딩했어요. 개별 로봇의 위치를 지정하지 않고 무리 전체의 통계적 특성을 제어하는 방식이에요.", "evidence": "The image is sampled into a reference configuration whose centroid and covariance set the position and principal spreads of the formation, while its higher-order moments, expressed in covariance-normalized (whitened) coordinates, encode the remaining shape."}, {"subtitle": "계층적 제어기와 직교화 기법", "desc": "음의 기울기 속도를 다항식의 보완 공간에 투영하는 직교화 기법을 사용해서, 고차 모멘트를 수정해도 저차 모멘트가 유지되도록 설계했어요. 이 덕분에 제어 차수를 높여도 기존에 맞춘 형태가 흐트러지지 않는다는 장점이 있어요.", "evidence": "The key mechanism is orthogonalization in the swarm's own empirical inner product: projecting negative-gradient velocities onto the complement of low-degree polynomials sampled at the agents makes every higher-order correction preserve all lower-order moments exactly."}, {"subtitle": "분산 제어 실험 및 검증", "desc": "350대의 로봇을 활용한 시뮬레이션에서 10차 모멘트까지 제어해 비행기 모양을 형성하는 데 성공했어요. 이 제어기는 이웃 로봇과의 통신만으로도 작동하는 분산 구현이 가능하며, 추정 속도가 충분히 빠를 때 국소적 지수 수렴을 보인다고 연구진은 주장했어요.", "evidence": "In a distributed simulation on a sparse graph, 350 agents form an airplane from an unstructured swarm through moments up to order ten; the hierarchy reaches the full specification, while the joint law approaches it with smaller velocities."}], "easy1_evidence": "In contrast with geometric formation control, which prescribes distances, bearings, or relative positions between specific agents, this specification concerns the swarm as a whole and assigns no agent to a particular place.", "easy2_evidence": "The resulting hierarchical controller has lower triangular error dynamics and converges locally exponentially for any positive gains, so orders can be added without undoing those already achieved.", "topic_evidence": "This paper shapes a swarm into a target pattern, such as a figure taken from an image, by controlling its spatial moments.", "limit_evidence": "Both controllers admit a distributed implementation that uses only relative positions and neighbor communication and retains local exponential convergence when estimation is sufficiently fast."}, "2611.19252": {"points": [{"subtitle": "탐색과 피드백의 구조적 관계", "desc": "연구진은 MPPI 제어에서 탐색 범위를 결정하는 공분산이 피드백 이득까지 결정한다는 점을 수학적으로 증명했는데요, 탐색을 줄이면 이전 해답을 거의 그대로 반복하게 되어 불안정한 시스템을 제어할 수 없게 된다는 겁니다.", "evidence": "We show that, for linear quadratic (LQ) problems with infinitely many samples, the exploration covariance also determines the feedback gain, i.e., how strongly MPPI updates the previous solution in response to the current state."}, {"subtitle": "SS-MPPI 제안", "desc": "이러한 갈등을 풀기 위해 안정화에 필요한 제어 입력을 미리 계산해 분리하는 SS-MPPI를 도입했는데요, 이를 통해 탐색 범위를 작게 가져가면서도 샘플 효율성을 높이는 결과를 얻었습니다.", "evidence": "For LQ problems, SS-MPPI remains stable with small exploration and is thus sample-efficient."}, {"subtitle": "시뮬레이션 검증", "desc": "거꾸로 선 진자와 사족 보행 로봇을 대상으로 실험해 봤더니, 기존 방식은 탐색이 적을 때 제어에 실패했지만 SS-MPPI는 적은 샘플로도 안정적으로 작동함을 확인했습니다.", "evidence": "Simulations of an inverted pendulum and a quadruped robot confirm the analysis, showing that MPPI fails under small exploration, whereas SS-MPPI remains stable even with few samples."}], "easy1_evidence": "Because a single covariance governs both exploration and feedback, stability and sample efficiency are in structural conflict: stabilization requires large exploration, which leaves few samples that contribute to the solution.", "easy2_evidence": "To resolve this conflict, we propose Stabilizing Subspace MPPI (SS-MPPI), which computes the control inputs required for stabilization and samples only the rest.", "topic_evidence": "This paper investigates how exploration affects closed-loop stability in model predictive path integral (MPPI) control.", "limit_evidence": ""}, "2611.19245": {"points": [{"subtitle": "통합 설계 방식 적용", "desc": "위성 구성과 구조적 인터페이스, 부품 배치, 배선 경로를 조립과 시험 과정에 맞춰 함께 설계했는데요. 서비스 인터페이스를 위성 한쪽 면으로 모아서 지상 지원 장비가 접근하고 배선을 연결하기 쉽게 만들었어요.", "evidence": "The integrated approach incorporates co-designing the satellite configuration, structural interfaces, subsystem placement, harness routing, and ground support equipment to facilitate efficient AIT."}, {"subtitle": "유지보수를 위한 구조 개선", "desc": "위성 덮개를 열어도 내부 부품과 배선이 고정되도록 뼈대 인터페이스를 개발했는데요. 기계적 기준점을 정해두어서 센서나 부품을 떼어내고 다시 설치할 때도 정밀하게 제어할 수 있게 했습니다.", "evidence": "Skeletal support interfaces are developed to retain mounted components and service interfaces when removable enclosures are opened to expose internal harness-routing paths for inspection, troubleshooting, and rework."}, {"subtitle": "가동형 지상 지원 기구", "desc": "위성 상판을 하판 대비 180도까지 열 수 있는 탈착식 이중 경첩을 도입했는데요. 배선이 꼬이지 않게 하면서도 위성 자체에는 복잡한 경첩 무게를 더하지 않는 방식을 택한 겁니다.", "evidence": "A removable double hinge ground-support mechanism allows the top deck to open up to 180 degrees relative to the bottom deck while accommodating interconnecting-harness articulation, without introducing permanent hinge mass and complexity to the satellite."}], "easy1_evidence": "The rapid growth of small-satellite constellations has increased the need for higher manufacturing throughput, lower production costs, and shorter turnaround times.", "easy2_evidence": "Building on our prior work, this paper presents an integrated design-for-AIT approach for the 65 kg Lumelite-5 satellite.", "topic_evidence": "Through this work, we demonstrate how co-designing satellite architecture and AIT processes from the early development stages can support more scalable, repeatable, and efficient constellation production.", "limit_evidence": ""}, "2611.19212": {"points": [{"subtitle": "지능형 설정 루프", "desc": "설정 에이전트가 현장 정보와 이전 평가 기록을 조합해 안테나 설정안을 생성하는 방식이에요. 여기에 광선 추적(RT) 기반 평가자가 성능을 요약해 주면, 반성 에이전트가 이를 해석해 구체적인 조정안을 내놓는 구조로 되어 있거든요.", "evidence": "Specifically, a Configuration Agent combines scene information, evaluation history, and reflection feedback to generate antenna configuration proposals."}, {"subtitle": "반성 기반 경험 축적", "desc": "반성 에이전트가 현장별로 성능이 부족한 부분을 진단하고, 이를 바탕으로 조건부 경험을 차곡차곡 쌓아 나가는 것이 핵심이에요. 뭔 소리냐면, 시행착오를 통해 얻은 데이터를 다음 설정에 반영하여 점점 더 똑똑한 결정을 내리게 된다는 말이에요.", "evidence": "Next, a Reflection Agent interprets these results to diagnose site-specific performance deficiencies, recommend feasible configuration adjustments, and accumulate conditional experience."}, {"subtitle": "성능 개선 효과", "desc": "실제 도시 환경에서 시뮬레이션을 해 봤더니, 제안한 프레임워크가 기존의 벤치마크 방식들보다 통신 끊김 확률이 낮게 나타났거든요. 연구진은 이를 통해 에이전트의 추론과 반성 기능이 적응형 안테나 설정 결정에 효과적이라고 주장했어요.", "evidence": "Simulations in real-world urban scenarios demonstrate that the proposed framework achieves lower outage probabilities than the considered benchmark methods, highlighting the effectiveness of agentic reasoning and reflection in translating site-specific performance feedback and accumulated experience into adaptive antenna configuration decisions."}], "easy1_evidence": "In contrast to conventional approaches that reply on costly performance evaluations, the proposed framework achieves intelligent and efficient antenna configuration through a perception-reasoning-reflection loop.", "easy2_evidence": "Through this iterative process, the framework accumulates site-specific experience and progressively refines antenna configurations without human-in-the-loop intervention.", "topic_evidence": "An agentic framework is proposed for cell shaping in future sixth-generation (6G) wireless network planning.", "limit_evidence": ""}, "2611.19194": {"points": [{"subtitle": "일반화 성능 검증 체계", "desc": "전력망의 어드미턴스 행렬 변화, 부하 수준, 그리고 학습하지 않은 새로운 전력망이라는 세 가지 축을 기준으로 모델의 한계를 시험했습니다. 기존 연구들이 각자 만든 기준을 썼던 것과 달리, 체계적인 틀을 제시했다는 점이 특징이에요.", "evidence": "We propose a three-axis framework to test their generalization limits: changed admittance matrices of training grids, load levels, and unseen grids."}, {"subtitle": "모델별 성능 저하 분석", "desc": "GENCO, LUMINA, GridSFM 세 모델을 DC 방식과 비교했는데요, 선로가 추가되거나 부하가 학습 범위를 넘어서면 성능이 크게 떨어지는 현상을 발견했습니다. 특히 LUMINA와 미세 조정된 GENCO는 선로가 길어질수록 DC 방식보다 못한 결과를 보이기도 했거든요.", "evidence": "Experiments reveal that adding a line degrades all FMs more than removing one, and longer lines eventually make LUMINA and fine-tuned GENCO worse than DC."}, {"subtitle": "메타 모델로서의 한계", "desc": "학습 범위를 벗어난 새로운 전력망에서 LUMINA는 성능이 급격히 낮아졌고, GridSFM은 학습 데이터와 가장 거리가 먼 전력망에서 실패했습니다. 연구진은 이 모델들이 학습 조건 밖에서는 추가적인 데이터와 계산이 필요한 메타 모델에 가깝다고 결론 내렸습니다.", "evidence": "On unseen grids, LUMINA degrades sharply even inside its training range, and GridSFM fails on the grid farthest from it."}], "easy1_evidence": "We propose a three-axis framework to test their generalization limits: changed admittance matrices of training grids, load levels, and unseen grids.", "easy2_evidence": "Thus, beyond training conditions, FMs behave more like meta-models requiring test-time fine-tuning data and compute.", "topic_evidence": "We propose a three-axis framework to test their generalization limits: changed admittance matrices of training grids, load levels, and unseen grids.", "limit_evidence": "Thus, beyond training conditions, FMs behave more like meta-models requiring test-time fine-tuning data and compute."}, "2611.19187": {"points": [{"subtitle": "통합된 제어의 뼈대", "desc": "기존의 운영 공간 제어부터 강화 학습, 확산 정책까지 다양한 방법론들이 결국 제약 조건이 있는 순차적 의사결정 문제로 귀결된다는 점을 확인했습니다. 즉, 분야마다 다르게 보이던 기술들이 하나의 공통된 뼈대로 모이고 있다는 거예요.", "evidence": "No single framework is accepted, but the field converges on a common skeleton: from operational-space and whole-body control to MPC, reinforcement learning, active inference, and diffusion/flow policies, all reduce to constrained sequential decision making on the configuration manifold."}, {"subtitle": "수학적 언어의 연결", "desc": "결정론적 최적 제어와 확률적 추론이라는 두 가지 언어를 제어와 추론의 관점에서 엄격하게 연결했습니다. 이를 통해 서로 다른 접근법을 수학적으로 통합할 수 있는 기반을 마련했다는 겁니다.", "evidence": "Two languages describe it-deterministic optimal control (Euler-Lagrange plus constrained OCP, reduced in real time to a QP) and probabilistic inference (MDP/POMDP plus free-energy minimization)-rigorously bridged by control as inference and KL/path-integral control."}, {"subtitle": "안정성과 안전성 확보", "desc": "연구진은 현재 공학적 통합은 이루어졌지만, 증명 가능한 안정성과 안전성을 확보하는 것이 가장 어려운 과제라고 주장했습니다. 이를 해결하기 위해 스펙트럼 분석이나 미분 가능한 최적화 기법 등을 도입해야 한다고 봤습니다.", "evidence": "The hardest gap is provable stability and safety, the entry point for spectral, geometric, differentiable-optimization, and safe-learning methods."}], "easy1_evidence": "Embodied intelligence holds that an agent develops cognition and behavior through real-time body-environment interaction, so its control system must tightly couple perception, decision making, learning, optimization, constraints, and physical execution.", "easy2_evidence": "A single-link manipulator then runs through all five layers: L4 parses the instruction into a reference, L3 identifies a Koopman lifted linear world model, L2 solves a receding constrained QP, L1 adds torque saturation and a CBF, and L0 is the true nonlinear plant.", "topic_evidence": "A Unified Control Framework, Mathematical Model, and Five-layer Closed-loop Case Study for Embodied Intelligence Control Systems", "limit_evidence": "The hardest gap is provable stability and safety, the entry point for spectral, geometric, differentiable-optimization, and safe-learning methods."}, "2611.19025": {"points": [{"subtitle": "시공간 가우시안 프로세스 구성", "desc": "환경에서 얻은 점 구름 데이터를 바탕으로 가우시안 프로세스 장벽을 시공간적으로 결합하는 방식을 썼는데요. 점 구름에 의존하는 커널을 만들어 개별적인 장애물 정보를 부드럽게 합치고, 계산 효율을 위해 대각 행렬을 사용해 복잡한 역연산을 피했습니다.", "evidence": "A point-cloud-dependent covariance kernel is constructed to smoothly combine individual GP representations, yielding a continuously differentiable posterior mean and a diagonal observation Gram matrix that avoids dense covariance inversions."}, {"subtitle": "안전 거리 보장 및 보정", "desc": "공간적인 근사 오차와 점 구름 데이터의 한계를 고려해서 가우시안 프로세스의 길이 척도를 보정하는 식을 유도했는데요. 이를 통해 실제 장애물 경계로부터 미리 정해둔 최소 거리를 확실하게 유지할 수 있도록 설계했습니다.", "evidence": "We then derive a closed-form calibration of the GP length scale accounting for spatial approximation errors and finite point-cloud coverage, guaranteeing a prescribed minimum distance from the true obstacle boundary."}, {"subtitle": "제어 장벽 함수를 통한 안전 제어", "desc": "움직이는 장애물에 대응하기 위해 스캔 기반의 장벽을 시간 변화에 따라 제어 장벽 함수(CBF)로 결합했는데요. 이 방식은 안전 영역을 계속 유지하도록 보장하며, 유니사이클 로봇 시뮬레이션을 통해 그 효과를 확인했습니다.", "evidence": "To handle moving obstacles and updated observations, the scan-based barriers are certified over finite validity horizons and smoothly combined into a time-varying Control Barrier Function (CBF)."}], "easy1_evidence": "In this paper, we propose a distance-certified safety control framework for unknown and dynamic environments.", "easy2_evidence": "Under problem feasibility conditions, the associated CBF-based safety control guarantees forward invariance of the certified safe set, thereby ensuring the prescribed distance from the obstacles.", "topic_evidence": "In this paper, we propose a distance-certified safety control framework for unknown and dynamic environments.", "limit_evidence": "Under problem feasibility conditions, the associated CBF-based safety control guarantees forward invariance of the certified safe set, thereby ensuring the prescribed distance from the obstacles."}, "2611.18978": {"points": [{"subtitle": "행동 시스템 이론의 활용", "desc": "선형 시스템의 유한한 시간 동안의 행동을 부분 공간으로 표현하는 행동 시스템 이론을 기반으로 삼았는데요. 이 공간에 확률 분포를 입혀서 시스템이 가질 수 있는 불확실성을 수학적으로 정의한 겁니다.", "evidence": "In behavioural systems theory, the finite-horizon behaviour of a linear system is represented by a subspace."}, {"subtitle": "그래스만 다양체 기반 추론", "desc": "불확실성을 그래스만 다양체 위의 확률 분포로 나타내면서 베이지안 추론을 기하학적인 문제로 바꿨는데요. 가우시안 측정 잡음(Gaussian measurement noise)이 있는 환경에서도 사후 분포를 유도해 낼 수 있게 된 겁니다.", "evidence": "This leads to a geometric formulation of Bayesian inference over the Grassmannian."}, {"subtitle": "데이터 기반 제어로의 확장", "desc": "이렇게 추론한 시스템 행동의 불확실성을 궤적 예측에 어떻게 전달할지 논의했는데요. 연구진은 이 방법이 데이터 기반 제어(Data-driven control)를 설계하는 데 유용하게 쓰일 수 있다고 밝혔습니다.", "evidence": "We derive the posterior distribution under Gaussian measurement noise and discuss how uncertainty in the inferred behaviour can be propagated to trajectory predictions, with a view towards data-driven control."}], "easy1_evidence": "We present a Bayesian approach to learning uncertain behavioural representations of linear dynamical systems from noisy input-output data.", "easy2_evidence": "We quantify uncertainty in this subspace through probability distributions on the Grassmann manifold.", "topic_evidence": "We present a Bayesian approach to learning uncertain behavioural representations of linear dynamical systems from noisy input-output data.", "limit_evidence": ""}, "2611.17834": {"points": [{"subtitle": "데이터셋 구축", "desc": "연구진은 1,000개의 ICLR 제출 논문과 23,000개의 사람 및 대규모 언어 모델(LLM)이 작성한 심사평을 모아 페이퍼사운드-23K(PaperSound-23K)라는 데이터셋을 만들었어요. 이 데이터셋은 AI가 논문의 타당성을 평가하는 법을 배우는 기초 자료로 쓰인 겁니다.", "evidence": "Under this problem formulation, we construct a quality-labeled review point dataset, PaperSound-23K, using 1K ICLR submissions and 23K human-written and LLM-generated review points."}, {"subtitle": "강화학습 기반 모델 훈련", "desc": "이렇게 만든 데이터를 바탕으로 페이퍼크리틱 모델을 강화학습시켰는데요. 정밀도와 재현율의 조화 평균인 F1 점수를 보상으로 주어 AI가 더 정확하고 핵심을 찌르는 심사평을 내놓도록 유도한 거예요.", "evidence": "Using this dataset, we train an AI reviewer model, PaperCritic, through reinforcement learning with the F1 score of precision and recall as the reward."}, {"subtitle": "성능 검증 및 확장성", "desc": "실험 결과 페이퍼크리틱은 기존의 최신 모델들보다 우수한 성능을 보였다고 연구진은 주장했어요. 놀라운 점은 ICLR 논문으로 학습했는데도 네이처 계열 논문이나 코드, 법률 계약서 검토 같은 전혀 다른 분야에서도 효과적으로 작동했다는 거예요.", "evidence": "Surprisingly, learning to review ICLR submissions also transfers to reviewing Nature-family papers and even to out-of-domain reviewing tasks (e.g., code review, legal contract review, and feedback on story writing)."}], "easy1_evidence": "However, simply imitating human reviewing is problematic because reviewing serves multiple purposes, including evaluating papers' soundness, interestingness, and clarity, the last two of which are subjective.", "easy2_evidence": "In this work, we focus solely on evaluating soundness, the most important and objective criterion, and define the learning objective as jointly maximizing (1) precision, based on the soundness and substantiveness of review points, and (2) recall, the coverage of high-quality reference review points.", "topic_evidence": "In this work, we focus solely on evaluating soundness, the most important and objective criterion, and define the learning objective as jointly maximizing (1) precision, based on the soundness and substantiveness of review points, and (2) recall, the coverage of high-quality reference review points.", "limit_evidence": ""}, "2611.20254": {"points": [{"subtitle": "하르 변환 기반의 데이터 분해", "desc": "멜-스펙트로그램을 주파수와 시간 축으로 나누어 처리하는 방식을 썼는데요, 먼저 주파수 영역에서 평균값과 잔차로 분해한 뒤, 평균 성분을 다시 시간 축으로 나누어 핵심 정보인 Coarse-Mel을 추출하는 방식이에요. 이렇게 하면 데이터의 구조를 단순화해서 모델이 학습하기 훨씬 수월해지거든요.", "evidence": "The transform first decomposes each mel spectrogram along frequency into local averages and a frequency residual, then splits the averaged component along time into Coarse-Mel and a temporal residual."}, {"subtitle": "자기회귀와 비자기회귀의 결합", "desc": "언어 모델 본체와 흐름 매칭(flow-matching) 헤드를 사용해 Coarse-Mel을 자기회귀 방식으로 먼저 생성하고, 나머지 잔차 정보는 비자기회귀 방식으로 예측하는 구조를 취했어요. 이때 생성된 잔차 정보들이 다시 자기회귀 과정으로 입력되지 않게 설계해서 모델의 안정성을 높였다는 겁니다.", "evidence": "A language-model backbone with a flow-matching head autoregressively generates Coarse-Mel."}, {"subtitle": "학습 성능 및 효율성 검증", "desc": "10만 시간의 Emilia 데이터셋으로 학습한 0.6B 모델은 영어와 중국어 테스트에서 우수한 성능을 보였는데요, GRPO(Group Relative Policy Optimization) 기법을 적용했을 때 영어 WER 1.15%, 중국어 CER 1.17% 수준으로 성능이 향상됐다고 연구진은 주장했어요. 또한 증류를 통해 2~4단계만으로도 원래 모델과 거의 비슷한 성능을 내는 학생 모델을 만들었다는 점도 특징이에요.", "evidence": "GRPO improves these results to 1.15% WER / 0.753 SIM and 1.17% CER / 0.776 SIM, respectively."}], "easy1_evidence": "While existing approaches employ learned compressed representations (e.g., continuous VAE latents) to render prediction tractable, they rely on complex neural encoders that often cap generation fidelity.", "easy2_evidence": "In this work, we propose VoxMel, a tokenizer-free framework for autoregressive TTS that makes stable mel modeling tractable through a fixed, exactly invertible two-axis Haar transform.", "topic_evidence": "In this work, we propose VoxMel, a tokenizer-free framework for autoregressive TTS that makes stable mel modeling tractable through a fixed, exactly invertible two-axis Haar transform.", "limit_evidence": ""}, "2611.19564": {"points": [{"subtitle": "행동 평가 프레임워크", "desc": "AI 에이전트의 행동을 5가지 축으로 구체화하여 측정하는 방식을 도입했습니다. 이를 통해 AI가 다양한 사회적 상호작용 속에서 어떻게 반응하는지 정량적으로 분석할 수 있게 된 겁니다.", "evidence": "The framework operationalizes agent behavior along five measurable axes and uses a standardized evaluation battery spanning six socially salient interaction settings to assess behavioral differentiation, consistency, and drift."}, {"subtitle": "페르소나 기반 실험", "desc": "통제된 페르소나 설정을 실험의 닻으로 활용했습니다. 이를 통해 AI가 단순히 스타일만 바꾸는 것인지, 아니면 상황에 관계없이 의도된 행동 차이를 유지하는지 체계적으로 검증할 수 있다는 거예요.", "evidence": "Controlled persona configurations serve as experimental anchors, enabling systematic testing of whether intended behavioral differences persist across contexts rather than appearing only as stylistic variation."}, {"subtitle": "행동 프로필과 결과의 연관성", "desc": "초기 분석을 해 봤더니, 설정한 구성에 따라 측정 가능한 행동 차이가 나타났습니다. 또한 연구진은 AI의 행동 프로필과 실제 상호작용 결과 사이에 연관성이 있을 것으로 봤다는 거예요.", "evidence": "Preliminary analyses demonstrate measurable differentiation across configurations and suggest associations between behavioral profiles and interaction outcomes."}], "easy1_evidence": "AI agents are increasingly deployed in socially consequential settings, yet existing evaluations provide limited assurance that they behave consistently with their intended characteristics across diverse interactions.", "easy2_evidence": "The framework operationalizes agent behavior along five measurable axes and uses a standardized evaluation battery spanning six socially salient interaction settings to assess behavioral differentiation, consistency, and drift.", "topic_evidence": "We introduce an evaluation framework for measuring the behavioral consistency of socially deployed AI agents.", "limit_evidence": ""}, "2611.19116": {"points": [{"subtitle": "하이브리드 구조 설계", "desc": "채널당 하나의 스칼라 상태를 사용하는 순환 구조와 어텐션 메커니즘을 결합했습니다. 이를 통해 모델의 크기를 줄이면서도 시퀀스 데이터를 효과적으로 처리할 수 있게 설계한 거예요.", "evidence": "DecayFormer combines cycle-level selective recurrence, using a single scalar state per channel, with an attention mechanism queried by the recurrent state."}, {"subtitle": "수명 예측 방식", "desc": "충전 상태(SOC) 구간 통계와 마스터 커브 헤드를 활용해서 전체 수명과 성능 저하 경로를 추정합니다. 정규화된 수명을 바탕으로 성능 저하 곡선을 계산하는 방식이에요.", "evidence": "It further incorporates state-of-charge (SOC) interval statistics and a master curve head that jointly estimates a scalar lifetime and a monotonically non-increasing SOH profile parameterized by normalized lifetime."}, {"subtitle": "성능 검증 결과", "desc": "BatteryLife 벤치마크의 22개 폴드에서 별도의 튜닝 없이 테스트한 결과, 리튬이온 2.25%, CALB 2.76%, 나트륨이온 0.95%, 아연이온 7.19%의 평균 MAPE를 기록했습니다. 연구진은 이 결과가 복잡한 최적화 없이도 다양한 배터리 화학 조건에서 정확한 예측이 가능함을 보여준다고 주장했습니다.", "evidence": "DecayFormer achieves mean test MAPE values of 2.25% on Li-ion, 2.76% on CALB, 0.95% on Na-ion, and 7.19% on Zn-ion."}], "easy1_evidence": "Despite recent advances, accurate forecasting remains challenging for emerging battery chemistries, data-scarce domains, and cells exhibiting degradation behaviors beyond those observed during training.", "easy2_evidence": "DecayFormer combines cycle-level selective recurrence, using a single scalar state per channel, with an attention mechanism queried by the recurrent state.", "topic_evidence": "This work introduces DecayFormer, a compact hybrid state-space and attention architecture designed for early-life degradation trajectory forecasting.", "limit_evidence": ""}, "2611.20882": {"points": [{"subtitle": "평가 환경 구축", "desc": "과학 응용 프로그램과 슈퍼컴퓨팅 대회에서 가져온 32개의 CPU 최적화 과제를 벤치마크로 구성했어요. 각 과제는 작업량과 정확성 기준, 시간 제한 등을 명확히 정해두어 에이전트가 스스로 최적화 전략을 짜도록 설계했거든요.", "evidence": "We introduce Accelerate Bench, a benchmark of 32 CPU optimization tasks adapted from scientific applications and supercomputing competitions."}, {"subtitle": "에이전트 성능 평가", "desc": "16개의 코딩 에이전트를 시험한 결과, 상위권 에이전트들은 32개 과제 중 22개 이상에서 2배 이상의 속도 향상을 보여줬어요. 반면 나머지 14개 에이전트는 1.25배 미만의 성과를 낸 사례가 125건이나 되어 성능 격차가 컸다는 겁니다.", "evidence": "the two leading agents are at least 2x faster on 22 or more of the 32 tasks, while the other fourteen reach 2x on 8 to 17 and leave 125 of their 412 correct outcomes below 1.25x."}, {"subtitle": "조율의 중요성 확인", "desc": "코드 변경이 전체 성능에 미치는 영향은 빌드나 실행 환경에 따라 크게 달라지는데요, 똑같은 코드라도 설정에 따라 0.29배에서 2.12배까지 속도가 변하거든요. 그래서 연구진은 에이전트가 코드 간의 상호작용을 얼마나 잘 조율하는지가 최적화의 핵심이라고 주장했어요.", "evidence": "Controlled replays show why coordination across an application matters: identical source code runs between 0.29x and 2.12x depending only on build and runtime settings, and one code change is worth 1.01x or 6.4x depending on another."}], "easy1_evidence": "Application optimization requires coding agents to discover useful changes and coordinate them across a complete program while preserving the required computation.", "easy2_evidence": "On benchmark version 1.1, we evaluate 16 coding agents, each pairing a model with a harness.", "topic_evidence": "We introduce Accelerate Bench, a benchmark of 32 CPU optimization tasks adapted from scientific applications and supercomputing competitions.", "limit_evidence": ""}, "2611.17110": {"points": [{"subtitle": "의미 기반의 행동 정렬", "desc": "사람과 로봇의 영상에 달린 언어 설명을 이용해 두 행동 사이의 의미적 유사도를 계산했습니다. 이를 통해 사람의 잠재 행동이 로봇의 제어 공간과 일치하도록 유도하는 구조를 만들었거든요.", "evidence": "Without requiring paired data, we use the language descriptions of unpaired human and robot clips to estimate semantic similarities and supervise cross-embodiment correspondence."}, {"subtitle": "이중 축 확장 학습", "desc": "일반적인 사람 영상을 많이 학습할수록 로봇의 행동 예측 오차가 줄어들고, 특정 작업에 특화된 영상을 추가 학습하면 실제 로봇의 작업 성공률이 크게 높아진다고 연구진은 주장했어요.", "evidence": "Notably, latent action supervision enables scaling along two axes: (1) pre-training on increasing amounts of general human video consistently reduces robot action prediction error on downstream tasks, and (2) post-training on increasing amounts of task-specific human video substantially improves real-world robot task success rates."}, {"subtitle": "효율적인 모델 학습", "desc": "픽셀을 직접 예측하는 월드 액션 모델(WAM)과 달리, 잠재 행동 모델을 사용해 학습과 실행 과정에서 드는 비용을 줄였습니다. 영상 재구성에만 의존하지 않고 제어 공간을 명확히 함으로써 학습 효율을 높인 겁니다.", "evidence": "Compared with world-action models (WAM), LAMs can offer greater training efficiency and potentially lower inference costs by avoiding explicit pixel prediction during policy learning and execution."}], "easy1_evidence": "However, most existing LAMs learn latent actions solely through video reconstruction, which can cause their representations to cluster by visual appearance rather than by the underlying actions.", "easy2_evidence": "To bridge the gap, we introduce SALA, which emphasizes establishing the semantic correspondence for latent actions.", "topic_evidence": "The resulting shared latent action space provides a unified supervision signal for training an embodied foundation model on both human and robot videos.", "limit_evidence": ""}, "2611.20986": {"points": [{"subtitle": "Calpha 모델 구조와 작동 방식", "desc": "Qwen3.5-9B 모델에 ESM2 잔기 특징을 더한 서열 정보를 입력하고, 모델이 직접 구조 예측 헤드를 호출하게 만들었어요. 구조 예측 헤드는 오직 모델 내부의 잔기 상태 정보만을 전달받아 단백질 구조를 생성하는 방식이에요.", "evidence": "Qwen3.5-9B reads a sequence enriched with ESM2 residue features. It can respond in text or emit a token that invokes a pretrained SimpleFold structure head, which receives information about the protein only through Qwen's residue states."}, {"subtitle": "구조 예측 성능 평가", "desc": "고정된 접힘 요청 상황에서 FoldBench-334 데이터셋에서 평균 TM-점수 0.808, CASP16 도메인에서 0.635, CAMEO 스타일 PDB 세트에서 0.900을 기록했어요. 기존의 ESM2-3B 기반 모델과 비교했을 때 긴 사슬 단백질에서는 다소 낮은 성능을 보였다는 점이 특징이에요.", "evidence": "Under a fixed folding request, the head achieves mean TM-scores of 0.808 on the FoldBench-334 development set, 0.635 on CASP16 domains and 0.900 on a CAMEO-style PDB set."}, {"subtitle": "언어 모델 성능 변화", "desc": "단백질 데이터를 학습시킨 결과, MMLU-Pro 데이터셋의 350개 항목에 대한 정확도가 기존 77.4%에서 70.3%로 줄어들었어요. 구조 예측 능력을 얻는 대신 언어 모델 본연의 일반적인 추론 성능은 일부 감소했다는 의미예요.", "evidence": "Protein training reduced accuracy on a 350-item MMLU-Pro subset from 77.4% to 70.3%."}], "easy1_evidence": "Biomolecular foundation models predict the structures of proteins and their complexes accurately, and large language models (LLMs) reason in natural language, but the two remain separate: the abilities of the former are not part of a general-purpose LLM, and the reasoning of the latter does not enter a structure prediction.", "easy2_evidence": "Calpha aims at one general model that folds proteins and complexes, understands protein sequence and structure, and lets its language reasoning influence the structures it predicts.", "topic_evidence": "This report covers the first step, in which an LLM outputs single-chain protein structures.", "limit_evidence": "Complex prediction, structure understanding and the effect of language reasoning on the predicted coordinates remain future work."}, "2611.21339": {"points": [{"subtitle": "WinTF를 통한 기초 학습", "desc": "윈도우 단위로 교사 강요(Teacher Forcing)를 적용하는 WinTF 방식을 통해 여러 노이즈 수준에서 영상을 정교하게 다듬습니다. 각 윈도우 안에서는 양방향 주의 집중을 사용하고, 이전 기록은 인과적 접근으로 처리해서 기초를 탄탄히 다지는 거예요.", "evidence": "We first establish a robust multi-step base through Window-wise Teacher Forcing (WinTF), which jointly denoises chunks at progressive noise levels with bidirectional attention within each window and causal access to preceding history."}, {"subtitle": "HieraKV로 메모리 효율화", "desc": "계층적 KV 캐시 압축인 HieraKV를 활용해 주의 집중 패턴에 따라 레이어별로 데이터를 다르게 저장합니다. 얕은 레이어에는 전체 기록을 남기고 깊은 레이어에는 최근 기록 위주로 저장해서 메모리 사용량을 최대 78%까지 줄인 겁니다.", "evidence": "To retain historical context efficiently, hierarchical KV-cache compression (HieraKV) exploits layer-wise attention patterns, retaining full history in shallow layers and sink--recent history in deeper layers."}, {"subtitle": "CuLT-DMD로 긴 영상 생성", "desc": "분포 일치 증류를 활용한 누적 학습 방식인 CuLT-DMD를 도입해 긴 영상 생성 훈련을 효율적으로 수행합니다. 학습 과정에서 파라미터를 고정하고 로컬 그래디언트를 평균 내어 업데이트함으로써, 짧은 영상 학습만으로도 60초까지 자연스러운 영상을 만들 수 있게 됐습니다.", "evidence": "Building on this base, cumulative long tuning with distribution matching distillation (CuLT-DMD) holds parameters fixed throughout each long self-rollout and averages local gradients before updating."}], "easy1_evidence": "Streaming video generation must sustain quality beyond the training horizon while handling self-generated history and growing cache costs.", "easy2_evidence": "This reduces cache memory by up to 78% while improving generation quality.", "topic_evidence": "To address these challenges, we present MovieRoll, a base-to-distilled framework that connects streaming fine-tuning, long-rollout distillation, and long-horizon inference.", "limit_evidence": ""}, "2611.20404": {"points": [{"subtitle": "잠재 피드백의 효율성 검증", "desc": "연구진은 다양한 모델 크기와 데이터 양을 설정해 기존 트랜스포머 모델과 잠재 피드백 모델을 비교했습니다. 잠재 피드백은 모델이 가진 연산 자원과 데이터를 더 가치 있게 활용하도록 돕는다는 점을 확인했거든요.", "evidence": "We run this test across a ladder of model sizes, unique data and epochs, tuning both models at every size and amount of unique data."}, {"subtitle": "학습 효율 증폭 효과", "desc": "잠재 피드백은 데이터가 고정된 상태에서는 연산량을 줄여주고, 학습 횟수가 고정된 상태에서는 필요한 데이터 양을 줄여주는 증폭기 역할을 합니다. 이런 효율은 데이터가 많아지거나 반복 학습이 늘어날수록 더 커지는 경향을 보였습니다.", "evidence": "We find that latent feedback serves as an amplifier: with unique data fixed, it reaches a Transformer's loss with less compute; with epochs fixed, it reaches that loss with less unique data."}, {"subtitle": "확장 법칙을 통한 성능 예측", "desc": "연구진은 60M에서 271M 파라미터 모델로 확장 법칙을 도출해 778M 모델의 성능을 예측해 봤는데요, 실제 측정값과 예측값의 오차가 매우 작아 이 법칙이 유효함을 입증했습니다. 데이터가 부족한 환경에서 잠재 피드백이 연산 자원을 쓰는 가장 좋은 방법이라고 주장했어요.", "evidence": "Fitted on models from 60M to 271M parameters, the law predicts the losses at a held-out 778M size to within 0.3% and the gap between the two models to within 0.05%."}], "easy1_evidence": "Latent feedback, which feeds each token's top-layer state into the next token's input, is another way to spend that compute, yet it has not been tested against a vanilla Transformer that spends the same compute on more epochs.", "easy2_evidence": "At most, latent feedback saves 48% of the compute and 47% of the unique data.", "topic_evidence": "Latent feedback makes every FLOP and every token count for more except when unique data is scarce relative to model size, a regime that today's models are far from.", "limit_evidence": ""}, "2611.18919": {"points": [{"subtitle": "실패 상황 자동 추출", "desc": "강화학습 정책이 반복적으로 실패하는 상황을 자동으로 찾아내는 시스템을 구축했어요. 이 정보들은 가상현실 애플리케이션으로 전송되어 사람이 직접 물건을 집는 데이터를 생성하는 데 쓰입니다.", "evidence": "We present a human-in-the-loop failure loop that targets those grasps: situations an RL policy keeps failing are mined automatically, sent to a virtual-reality application where a person picks the object up with their own hands, and returned to training as two grasp points."}, {"subtitle": "사람의 시연과 로봇의 학습", "desc": "사람은 물건을 집는 위치만 제공하고, 로봇은 그 위치에 도달하기 위한 접근 경로를 스스로 결정하게 했는데요. 이렇게 하면 로봇이 사람의 동작을 무작정 따라 하는 게 아니라, 자신의 환경에 맞춰 유연하게 움직일 수 있다는 장점이 있어요.", "evidence": "The person contributes only where to grasp; the robot chooses its own approach."}, {"subtitle": "성공률의 비약적 향상", "desc": "시뮬레이션 결과, 강화학습만 사용했을 때 55%였던 성공률이 Contact-GraspNet 대비 83%까지 높아졌어요. 특히 로봇이 계속 실패하던 어려운 사례들에서는 사람의 시연 58번을 더해 성공률을 24%에서 45%까지 끌어올렸다고 연구진은 주장했습니다.", "evidence": "In simulation, RL raises success on unseen objects from 55% with Contact-GraspNet to 83%."}], "easy1_evidence": "Reinforcement learning (RL) can optimize for that directly and make a point-cloud grasping policy much better on average, yet it leaves specific grasps persistently unsolved.", "easy2_evidence": "Adding 58 human demonstrations nearly doubles success on the hard cases RL kept failing, from 24% to 45%, and recovers performance that RL alone loses on similar cases that were never demonstrated, without reducing success on unseen objects.", "topic_evidence": "We present a human-in-the-loop failure loop that targets those grasps: situations an RL policy keeps failing are mined automatically, sent to a virtual-reality application where a person picks the object up with their own hands, and returned to training as two grasp points.", "limit_evidence": ""}, "2611.20385": {"points": [{"subtitle": "도미노 벤치마크 구축", "desc": "연구진은 물리 시뮬레이터로 결과를 계산할 수 있는 2D 강체 장면 이미지 854개를 모아 도미노 벤치마크를 만들었습니다. 이 데이터셋은 427개의 최소 쌍으로 구성되어 있는데, 격자 한두 칸의 차이로 결과가 완전히 달라지도록 설계했거든요. 각 항목에는 결과에 결정적인 영향을 미치는 계산 과정까지 포함되어 있습니다.", "evidence": "It holds 854 items in 427 minimal pairs, in which a change of one to three grid steps in one quantity decides whether one person survives, and every item comes with a four-rung hint ladder ending in the exact calculation that decides the outcome."}, {"subtitle": "모델들의 예측 성능 분석", "desc": "앤스로픽, 구글, 오픈AI 같은 최첨단 모델들을 테스트해 봤더니, 도움 없이 문제를 풀 때는 정답률이 최대 72%에 그쳤습니다. 특히 쌍으로 이루어진 문제 두 개를 모두 맞히는 경우는 34%를 넘지 못했거든요. 모델들이 겉으로는 유창하게 장면을 묘사하지만, 실제 물리적 예측에서는 한계를 보인다는 겁니다.", "evidence": "Unaided, frontier models from Anthropic, Google and OpenAI are right about the person whose fate flips in at most 72% of items and answer both twins of a pair correctly in at most 34%."}, {"subtitle": "정량적 계산 능력의 중요성", "desc": "결정적인 물리 수치를 직접 제공했을 때 모델들의 성능은 82~92%까지 크게 향상되었습니다. 하지만 작은 규모의 오픈 웨이트 모델들은 여전히 무작위로 찍는 수준에 머물렀거든요. 연구진은 모델이 물리 세계에서 제대로 작동하려면 스스로 결정적인 수치를 찾아내고 계산하는 능력이 반드시 필요하다고 강조했습니다.", "evidence": "For models that plan or act in the physical world, a fluent account of a scene is thus no evidence of a correct prediction: such models must find and compute the deciding quantity unprompted, and DominoBench tests whether they do."}], "easy1_evidence": "We tested this claim on 30 models from 10 families and reached a clear conclusion: unaided, no model predicts the outcome reliably.", "easy2_evidence": "Physical prediction from a still image therefore fails at the quantitative step: the strongest models use the deciding quantity when they are given it, but do not produce it on their own.", "topic_evidence": "We built DominoBench, a benchmark of still images of 2D rigid-body scenes whose outcome a physics simulator computes.", "limit_evidence": ""}, "2611.19537": {"points": [{"subtitle": "피드백 캐스케이드 도입", "desc": "에피소드 수준의 피드백만으로는 Craftax 게임에서 최종 단계 도달률이 1% 미만에 머물렀는데요, 연구진이 제안한 피드백 캐스케이드를 적용했더니 최종 단계 도달률이 50%까지 크게 올랐다고 주장했어요. 뭔 소리냐면, 더 촘촘한 피드백을 통해 정책을 다듬는 게 훨씬 효과적이라는 말이에요.", "evidence": "In the Craftax game, a partially observed and procedurally generated environment, refinements via episode level feedback stall at <1% final-level arrival, whereas with the feedback cascade the optimized policy reaches the final stage 50% of time (28% final boss defeats)."}, {"subtitle": "환경 해석기와 규칙 프로그램 분리", "desc": "능력을 재사용하기 위해 기존 컨트롤러를 환경 해석기와 규칙 프로그램으로 나누었는데요, 환경 해석기는 모델과 기억, 기술을 담당하고 규칙 프로그램은 실제 동작을 정의합니다. 이렇게 구조를 나누면 목표 컴파일러가 새로운 작업에 맞춰 규칙 프로그램을 새로 짜는 게 가능해진다는 겁니다.", "evidence": "Furthermore, to make this competence reusable towards new goals, we factor the previous controller into an environment interpreter $I$ (models, memory, skills) and a rule program $p_0$, and we show that coding agents can optimize a reusable goal compiler $C_{\theta}$ that maps structured tasks $g$ into new rule programs $p_g$."}, {"subtitle": "제로샷 전이 성능 확인", "desc": "짧은 작업으로만 학습한 컴파일러를 긴 작업에 적용해 봤더니, 별도의 튜닝이나 추론 시 LLM 호출 없이도 성공적으로 전이되었다고 해요. 연구진은 연속성 점수 피드백과 수정 가능한 프로그램이 결합되어 단일 작업용 정책을 재사용 가능한 정책으로 바꿨다고 설명했어요.", "evidence": "Across five independent compiler searches trained only on short tasks, the resulting compilers successfully transfer zero-shot to longer tasks without any task-specific tuning nor inference-time LLM calls: continuation-scored feedback and a fixed machine with an editable program together turn a single-task competent policy into a reusable one."}], "easy1_evidence": "But for long horizon tasks, two challenges arise: local improvements can hurt final success and switching to a new objective requires another expensive synthesis run.", "easy2_evidence": "We propose a framework that first develops competence by refining the policy through a feedback cascade, moving from episode returns to hierarchical goals and belief updates which can be scored densely from simulator.", "topic_evidence": "We propose a framework that first develops competence by refining the policy through a feedback cascade, moving from episode returns to hierarchical goals and belief updates which can be scored densely from simulator.", "limit_evidence": ""}, "2611.13685": {"points": [{"subtitle": "SPAR 구조 도입", "desc": "기존의 사전 학습된 시각 언어 모델(VLM)을 기반으로 SPAR라는 구조를 설계했는데요. 이 모델은 로봇의 행동 예측과 미래 시각 상태 예측을 동시에 수행하면서 서로 보완적인 학습 신호를 만들어 내는 방식이에요.", "evidence": "Building on a pretrained VLM, we propose Shared Prediction on Action and Representation (SPAR), an MoT architecture in which future visual state prediction can provide independent and complementary learning signals alongside action prediction."}, {"subtitle": "학습 성능 향상 확인", "desc": "사람의 1인칭 시점 영상으로 학습한 결과, 로봇이 이전에 경험하지 못한 새로운 작업에서도 더 나은 성능을 보여줬거든요. 특히 영상 데이터의 양이 늘어날수록 로봇의 학습 성과도 함께 좋아지는 것을 확인했다는 거예요.", "evidence": "We find that representations learned from egocentric videos improve downstream performance on out-of-distribution robot tasks, with further gains as video data scales."}, {"subtitle": "데이터 활용 전략 제시", "desc": "연구진은 어떤 학습 목표를 선택하고 데이터를 어떻게 골라야 하는지도 함께 분석했는데요. 행동 정보가 없는 방대한 영상을 로봇 학습에 효율적으로 활용하기 위한 구체적인 통찰을 제공했다는 점에서 의미가 있어요.", "evidence": "We also study the effects of objective choices and data curation, providing insights into how to leverage action-free videos for scalable robot learning."}], "easy1_evidence": "In this paper, we investigate how human egocentric videos can benefit robot policy learning without action supervision.", "easy2_evidence": "Building on a pretrained VLM, we propose Shared Prediction on Action and Representation (SPAR), an MoT architecture in which future visual state prediction can provide independent and complementary learning signals alongside action prediction.", "topic_evidence": "We find that representations learned from egocentric videos improve downstream performance on out-of-distribution robot tasks, with further gains as video data scales.", "limit_evidence": ""}, "2611.08977": {"points": [{"subtitle": "에너지 기반 추론 모델(EBR) 설계", "desc": "잠재적인 추론 상태에 에너지 함수를 부여하여 반복적인 업데이트 과정을 경사 하강법으로 처리하도록 만들었습니다. 에너지 점수는 상태의 품질을 평가하고, 그 기울기는 추론을 더 나은 방향으로 이끄는 안내자 역할을 수행합니다.", "evidence": "The energy scores latent states, while its gradient guides refinement and provides a signal for stopping."}, {"subtitle": "탐색 기반 학습의 도입", "desc": "EBR을 효과적으로 학습시키기 위해 탐색 기반 학습 방식을 추가로 적용했습니다. 이를 통해 모델이 더 다양한 상태를 발견하고 에너지 지형을 더 넓고 정교하게 형성할 수 있도록 했습니다.", "evidence": "To train EBRs effectively, we further introduce exploration-based training to discover additional modes and to better shape the energy landscape over a broader set of states."}, {"subtitle": "성능 및 효율성 검증", "desc": "4개의 알고리즘 추론 벤치마크에서 기존 모델과 비슷하거나 더 뛰어난 성능을 보였는데요. 특히 스도쿠-익스트림에서는 345배 적은 연산량으로 99.9%의 정확도를 기록했고, 다중 해법 문제에서도 최고 수준의 해법 도달 범위를 보여주었습니다.", "evidence": "Across four algorithmic reasoning benchmarks, EBRs match or outperform prior recurrent reasoning models, achieving 99.9% accuracy on Sudoku-Extreme while using 345times less inference compute than the next-best model and maintaining comparable training compute."}], "easy1_evidence": "However, existing looped models are not inherently guided by an explicit measure of progress, making it difficult to determine when to stop looping and how to improve upon the current state.", "easy2_evidence": "To enable this, we introduce Energy-Based Reasoners (EBRs), which learn an energy function over latent reasoning states and formulate looped updates as gradient descent on this energy.", "topic_evidence": "These results suggest that energy-based models are a promising approach for strong reasoning performance.", "limit_evidence": ""}, "2611.19771": {"points": [{"subtitle": "4D 포인트 계획 방식", "desc": "기존의 픽셀 기반 모델과 달리, 깊이 정보를 포함한 포인트 클라우드를 활용해 잠재 공간에서 미래를 예측하고 계획합니다. 이 방식은 물체의 위치와 기하학적 구조를 더 명확하게 파악할 수 있게 해 준다는 거예요.", "evidence": "We present JEPA4R, a JEPA world model that observes single-depth-camera point clouds, predicts and plans in their latent space, and acts through a policy head on its frozen latents; we call this 4D point planning."}, {"subtitle": "예측 정확도와 성능 입증", "desc": "디코더를 통해 모델이 상상하는 미래를 4D 포인트 클라우드로 확인해 봤더니, 200단계 동안 평균 오차가 1.1cm 이내로 나타났습니다. OGBench와 CortexBench 같은 평가 환경에서 기존 픽셀 기반 JEPA 모델들을 앞질렀고, 특히 MetaWorld와 Adroit Relocate에서는 각각 98.4%와 88.0%의 점수로 1위를 차지했다고 주장했어요.", "evidence": "Under the policy-learning protocols of OGBench and CortexBench, JEPA4R leads pixel JEPA models on OGBench Cube-Single, Cube-Double, Cube-Triple and Scene, and ranks first on MetaWorld and Adroit Relocate with 98.4% and 88.0%, above the runner-up, R3M, at 96.0% and 65.3%."}, {"subtitle": "실제 로봇 환경 적용", "desc": "디지털 트윈 환경에서만 학습했음에도 불구하고, 실제 로봇 팔과 그리퍼, 그리고 정교한 손 형태의 장치에서 별도의 추가 학습 없이 바로 작동하는 모습을 보였습니다. 가상 환경의 학습 결과가 현실의 로봇 제어에도 효과적으로 연결될 수 있음을 보여준 셈이에요.", "evidence": "Trained only in a digital twin, JEPA4R and its policy heads run zero-shot on the real arm with both a gripper and a dexterous hand."}], "easy1_evidence": "Two challenges remain: 2D images leave the metric geometry that manipulation acts on implicit and entangled with appearance, and what these models imagine stays hidden, as they are mostly judged in simulation by short-horizon latent planning.", "easy2_evidence": "We present JEPA4R, a JEPA world model that observes single-depth-camera point clouds, predicts and plans in their latent space, and acts through a policy head on its frozen latents; we call this 4D point planning.", "topic_evidence": "We present JEPA4R, a JEPA world model that observes single-depth-camera point clouds, predicts and plans in their latent space, and acts through a policy head on its frozen latents; we call this 4D point planning.", "limit_evidence": ""}, "2611.19649": {"points": [{"subtitle": "루프필의 작동 원리", "desc": "루프필은 접미사 검색과 얕은 루프 예측을 하나의 나무 구조로 합쳐서 사용합니다. 두 방식이 힘을 합쳐 후보 토큰을 만드니까, 얕은 예측 결과를 접미사 검색으로 바로 확장할 수 있다는 거예요. 덕분에 여러 미래 토큰이 파이프라인에 함께 들어갈 수 있게 된 겁니다.", "evidence": "Both drafters contribute to one tree, so a suffix lookup can immediately extend a shallow prediction and several future tokens can enter the pipeline together."}, {"subtitle": "검증과 효율성", "desc": "공유된 블록이 한 번의 배치 안에서 다양한 루프 깊이의 후보 토큰을 계산하고, 전체 깊이에서 검증을 거쳐 모델의 원래 출력 분포를 그대로 유지합니다. 성능을 측정해 봤더니 루프어헤드(LoopAhead)라는 기존 최고 성능 모델보다 오로-2.6B에서는 40%, 허긴-3.5B에서는 25% 더 빠른 속도를 보였다고 주장했어요.", "evidence": "The speedups exceed those of LoopAhead, the strongest baseline, by 40% on Ouro-2.6B and 25% on Huginn-3.5B."}, {"subtitle": "실제 성능 향상", "desc": "일곱 개의 벤치마크에서 테스트한 결과, 루프필은 일반적인 자동 회귀 방식보다 훨씬 뛰어난 속도를 보여줬습니다. 오로-2.6B 모델에서는 5.85배, 허긴-3.5B 모델에서는 5.13배의 속도 향상을 기록했거든요. 모델의 구조를 바꾸지 않고도 학습 없이 바로 적용할 수 있다는 점이 특징이에요.", "evidence": "Across seven benchmarks, LoopFill's average speedup over greedy autoregressive decoding is 5.85times on Ouro-2.6B and 5.13times on Huginn-3.5B."}], "easy1_evidence": "During autoregressive decoding, however, generating each token requires several sequential passes through these layers, leading to high decoding latency.", "easy2_evidence": "We introduce LoopFill, a training-free speculative decoding algorithm for looped LLM that combines multi-token suffix drafts with shallow-loop predictions in a single draft tree.", "topic_evidence": "We introduce LoopFill, a training-free speculative decoding algorithm for looped LLM that combines multi-token suffix drafts with shallow-loop predictions in a single draft tree.", "limit_evidence": ""}, "2611.18330": {"points": [{"subtitle": "다양한 음성 판단 방식", "desc": "단어 존재 여부는 음성 인식 결과의 점수를 활용하고, 비언어적 질문은 별도의 질문 조건부 헤드와 18번째 층의 읽기 기능을 사용했어요. 언어 식별은 음성 인식 모델이 가진 자체 점수를 그대로 활용하는 방식을 택했거든요.", "evidence": "Lexical questions use zero-shot scoring of ASR transcripts; non-lexical questions use a question-conditioned head and a separate layer-18 turn-end readout."}, {"subtitle": "성능 평가 결과", "desc": "사적인 대화 데이터셋에서 AUROC(곡선 아래 면적) 0.80에서 0.92, 공개된 읽기 음성에서는 0.92에서 0.97을 기록했어요. 개인정보 탐지 기능은 합성된 브라질 포르투갈어 음성에서 F1 점수 0.904를 달성했다고 연구진은 밝혔습니다.", "evidence": "On private conversational test sets, decoder AUROC is 0.80-0.92; on public read speech it is 0.92-0.97."}, {"subtitle": "기존 기술과의 비교", "desc": "12번째 층의 화자 읽기 기능은 AMI와 VoxConverse 데이터셋에서 AUROC 0.966에서 0.980을 기록해 기존 ECAPA 기준 모델보다 뛰어났어요. 화자 수를 세는 능력 또한 pyannote 3.1보다 더 정확했다고 연구진은 주장했습니다.", "evidence": "Layer-12 speaker readouts detect speaker change with AUROC 0.966-0.980 on AMI and VoxConverse, above an ECAPA baseline, and count speakers (0, 1, 2, or 3+) more accurately than pyannote 3.1."}], "easy1_evidence": "Speech applications require decisions about term presence, turn completion, and language within an audio window.", "easy2_evidence": "We present Marimba, an interface for typed speech decisions built on frozen Qwen3-ASR 0.6B features.", "topic_evidence": "We present Marimba, an interface for typed speech decisions built on frozen Qwen3-ASR 0.6B features.", "limit_evidence": ""}, "2611.16642": {"points": [{"subtitle": "데이터 분포 근사 기법", "desc": "분류 목적 함수를 사용하지 않고 특징 추출기의 잠재 공간에서 데이터를 이동시키는 방식을 택했는데요, 실제 데이터 분포를 향해 데이터를 밀어 넣으면서 동시에 데이터끼리는 서로 멀어지게 배치하는 원리예요. 뭔 소리냐면, 데이터가 가진 고유한 분포를 더 정확하게 흉내 내도록 만든다는 말이에요.", "evidence": "Specifically, we \"drift\" our distilled data in the latent space of a feature extractor such that they move both toward the real data and away from each other without using a classification objective."}, {"subtitle": "모델 해석 및 확장성", "desc": "연구진은 이 방법이 단순히 데이터를 압축하는 것을 넘어 모델이 어떻게 작동하는지 들여다보는 시각화 도구로도 활용될 수 있다고 주장했어요. 또한 이미지 데이터에 국한되지 않고 다양한 모달리티(Modality)로 확장할 수 있다는 점도 강조했거든요.", "evidence": "Furthermore, we showcase our method's use as a visualization tool for better interpreting models and extend it beyond images to other modalities."}, {"subtitle": "새로운 평가 지표 제시", "desc": "기존의 분류 성능 위주 평가에서 벗어나 분포 기반의 평가 지표를 보조적인 수단으로 제안했는데요, 이를 통해 데이터와 모델이 서로 어떻게 상호작용하는지 더 깊이 이해할 수 있게 되었다는 거예요. 데이터셋 증류 분야의 새로운 가능성을 열었다는 점에서 의미가 큽니다.", "evidence": "Our work advances the frontier of dataset distillation, offering a novel synthesis method and proposing distribution-based metrics as a complementary evaluation."}], "easy1_evidence": "While many solutions have been proposed since the problem's inception, most of them primarily seek to optimize the distilled data with respect to a classifier.", "easy2_evidence": "We find that our drifted data cover the real distribution significantly better than existing methods while still serving as powerful training samples for classification.", "topic_evidence": "In this work, we propose a new distillation method that learns a set of samples such that they directly approximate the per-class data distribution.", "limit_evidence": ""}, "2611.09825": {"points": [{"subtitle": "오차 원인 제거", "desc": "쿼리 로짓 오차를 60%에서 1%로 줄이는 듀얼 잔차 쿼리 양자화와 언더플로우 방지 확률 스케일링, 그리고 이상치 대응 키 양자화를 적용했어요. 이 세 가지 기술로 데이터 손실을 최소화한 거예요.", "evidence": "We mitigate three error sources: Dual-Residual Query Quantization splits queries into two FP4 tensors, cutting query logit error from 60% to 1%; Underflow-Aware Probability Scaling prevents E4M3 scales from rounding long-context probabilities to zero; and Outlier-Aware Key Quantization combines static smoothing, Hadamard rotation, and scale search to suppress key outliers under token-wise scaling."}, {"subtitle": "시스템 수준의 최적화", "desc": "소프트맥스 병목 현상을 해결하기 위해 전치 소프트맥스 방식을 도입하고, 확률 양자화와 스택형 쿼리 MMA를 페이징된 KV 캐시에 결합했어요. 이를 통해 하드웨어 자원을 더 효율적으로 활용하도록 설계한 겁니다.", "evidence": "At the system level, we remove the softmax bottleneck via transposed softmax with fused probability quantization and stacked query MMA on paged KV caches."}, {"subtitle": "성능 및 처리량 검증", "desc": "NVIDIA B300 환경에서 Qwen3 모델들을 테스트했더니, BF16 대비 정확도 손실은 0.5에서 1포인트 이내로 유지하면서 처리량은 최대 3.0배까지 향상됐다고 주장했어요.", "evidence": "In end-to-end serving on NVIDIA B300 with Qwen3-4B and Qwen3-30B-A3B, it delivers 2.4-3.0times higher peak serving throughput than BF16 KV."}], "easy1_evidence": "While 4-bit microscaling formats (NVFP4, MXFP4) shrink the cache and run attention on FP4 Tensor Cores, a fundamental gap remains between algorithmic quantization and system-aware acceleration: existing FP4 KV systems use vanilla quantization that causes severe accuracy drops, whereas accuracy-oriented 4-bit algorithms rely on vector codebooks whose lookup overhead degrades decoding throughput.", "easy2_evidence": "We present BitDecoding-FP4, an algorithm--system co-design for accurate and efficient native FP4 KV decoding.", "topic_evidence": "We present BitDecoding-FP4, an algorithm--system co-design for accurate and efficient native FP4 KV decoding.", "limit_evidence": ""}, "2611.21605": {"points": [{"subtitle": "대조 세트 기반 학습", "desc": "연구진은 21에서 120 메가픽셀에 달하는 이미지 속 작은 객체를 수정하여 학습용(ViRA-Train)과 평가용(ViRA-Bench) 대조 세트를 만들었어요. 편집 흔적을 없애기 위해 실제 변화가 포함된 사진 세트(ViRA-Bench-Real)도 추가했거든요. 이 세트들은 오직 사진 속 증거를 정확히 읽어야만 전체 문제를 풀 수 있도록 설계된 겁니다.", "evidence": "We build contrast sets for training (ViRA-Train) and evaluation (ViRA-Bench) by editing one small object in images of 21 to 120 megapixels, and we photograph further sets with real changes (ViRA-Bench-Real) to exclude editing traces."}, {"subtitle": "크로스알피오(CrossRPO)의 효과", "desc": "크로스알피오는 대조 세트 전체를 해결했을 때만 보상을 주는 방식으로, 상식에 의존해 답을 찍는 행위를 강화하지 않는다는 점을 증명했어요. 이를 통해 ViRA-9B와 ViRA-27B 모델을 약 3,500개의 학습 데이터만으로 훈련했거든요. 결과적으로 최대 해상도에서 63.3%의 세트 정확도를 기록하며 기존 GRPO 방식의 59.3%를 넘어섰다고 밝혔습니다.", "evidence": "CrossRPO rewards solving the whole set, and we prove that it does not reinforce a set answered from common sense."}, {"subtitle": "성능 비교 및 우수성", "desc": "ViRA-9B 모델은 같은 크기의 오픈 모델 중 가장 높은 정확도를 보였고, ViRA-27B는 최고 수준의 사고 능력을 갖춘 클로드 하이쿠 5.5나 GPT-6-루나보다 대부분의 벤치마크에서 뛰어난 성능을 보였다고 주장했어요. 이는 초고해상도 이미지 처리 분야에서 해당 모델들이 경쟁력을 갖췄음을 의미하는 겁니다.", "evidence": "ViRA-9B is the most accurate open model of its size on all benchmarks, and ViRA-27B outperforms Claude Haiku 5.5 and GPT-6-Luna, both at their highest thinking level, on most benchmarks."}], "easy1_evidence": "However, existing agents often answer from common sense instead of reading the evidence.", "easy2_evidence": "CrossRPO achieves 63.3% set accuracy on ViRA-Bench at the maximum resolution, against 59.3% for GRPO.", "topic_evidence": "We propose Cross-Input Relative Policy Optimization (CrossRPO), which trains agents on contrast sets.", "limit_evidence": ""}, "2611.21479": {"points": [{"subtitle": "데이터 학습과 손 인식 강화", "desc": "다양한 실제 환경과 가상 환경을 아우르는 10만 개의 상호작용 클립을 모아서 학습시켰는데요, 손의 움직임과 물체와의 상호작용을 더 세밀하게 다듬기 위해 손 인식 기반의 지도 학습 방식을 도입했어요. 뭔 소리냐면, 모델이 손의 위치와 모양을 더 정확히 파악하도록 가르쳤다는 말이에요.", "evidence": "We curate 100K interaction clips spanning diverse real and synthetic environments and develop hand-aware supervision to improve fine-grained hand motions and object interactions."}, {"subtitle": "영상 생성 효율 최적화", "desc": "인과적 흐름 지도(causal flow map)를 학습시켜 적은 단계로도 영상을 만들 수 있게 했고, 영역별 점수 증류(region-aware score distillation) 기술을 써서 영상과 이미지의 장점을 합쳤어요. 이를 통해 상호작용의 역동성과 시각적 품질을 모두 높였다고 연구진은 주장했어요.", "evidence": "Building on this foundation, we learn a causal flow map for few-step generation and introduce region-aware score distillation that combines complementary video and image priors to refine interaction dynamics and visual appearance."}, {"subtitle": "실시간 성능과 연산 효율", "desc": "Ultra-Fast-VAE라는 압축된 영상 디코더를 사용해서 계산 비용을 크게 줄였는데요, H200 GPU 하나로 540p 영상을 초당 18.03 프레임으로 스트리밍할 수 있게 됐어요. 이때 지연 시간은 741ms이고 GPU 메모리는 34.89GB만 쓴다는 거예요.", "evidence": "For real-time interaction, 540p streaming on a single H200 reaches 18.03 FPS with 741ms latency and an optimized peak GPU memory footprint of only 34.89GB."}], "easy1_evidence": "Hands provide a natural interface, but translating continuous hand movements into coherent visual responses remains challenging because of complex hand-object dynamics and demanding real-time computation.", "easy2_evidence": "To address these challenges, we introduce LynnReal-Hand, a hand-controlled video world model that unifies precise interaction modeling with efficient streaming generation.", "topic_evidence": "To address these challenges, we introduce LynnReal-Hand, a hand-controlled video world model that unifies precise interaction modeling with efficient streaming generation.", "limit_evidence": ""}, "2611.20595": {"points": [{"subtitle": "조용한 실패의 심각성", "desc": "연구진이 15개의 공개 연구용 API를 조사해 봤더니, 11개에서 조용한 실패가 발견됐거든요. 심지어 어떤 경우에는 오류 횟수가 실제보다 최대 691배나 부풀려지기도 했어요. 기존 방식인 체크리스트나 모델 검사기로는 70% 이상의 틀린 답을 걸러내지 못하는 상황이에요.", "evidence": "We find silent failures in 11 of 15 public research APIs, with counts inflated up to 691 times."}, {"subtitle": "SilentGuard의 작동 방식", "desc": "이 도구는 API가 반드시 지켜야 할 불변 조건을 미리 정의해 두고, 결과값이 이 조건에 맞는지 실시간으로 테스트해요. 만약 조건에 어긋나는 결과가 나오면 모델에게 전달하지 않고 아예 차단해 버리는 거죠. 단순히 경고만 하는 것보다 직접 실행을 막는 것이 오류를 줄이는 핵심이라고 연구진은 강조했어요.", "evidence": "It tests each result against invariants that any correct API must satisfy and withholds values that break one."}, {"subtitle": "성능 검증 결과", "desc": "실제로 SilentGuard를 적용해 봤더니, 오류가 없는 작업에서는 성능 저하 없이 틀린 답을 획기적으로 줄이는 성과를 보였어요. 새로운 유형의 오류에 대해서도 틀린 답 비율을 61.1%에서 24.5%까지 낮췄거든요. 다만 이 방식은 오류를 수정하기보다는 아예 답을 내놓지 않는 방식으로 틀린 답을 피한다는 특징이 있어요.", "evidence": "It avoids wrong answers by abstaining rather than recovering."}], "easy1_evidence": "An API can fail silently.", "easy2_evidence": "We present SilentGuard, which moves the decision from the model to the harness running tool calls.", "topic_evidence": "We present SilentGuard, which moves the decision from the model to the harness running tool calls.", "limit_evidence": "It avoids wrong answers by abstaining rather than recovering."}, "2611.20192": {"points": [{"subtitle": "아틀라스 기반의 정보 분리", "desc": "글자 모양을 담은 아틀라스와 위치 정보를 담은 글리프 이미지를 분리해서 처리합니다. 각 글자나 단어를 별도의 셀에 인코딩함으로써, 대상 영역의 크기에 얽매이지 않고 고해상도의 획 정보를 유지할 수 있게 만든 거예요.", "evidence": "The atlas renders and encodes each character or word in a separate cell, decoupling reference resolution from target-region size."}, {"subtitle": "아틀라스 고정 어텐션 도입", "desc": "글자 영역이 아틀라스의 특정 셀에서만 획 정보를 가져오도록 하는 '아틀라스 고정 어텐션(atlas-anchored attention)' 기술을 썼는데요. 이를 통해 전체적인 글자 구조를 먼저 잡고 세부 획을 다듬는 방식이라, 복잡한 글자도 훨씬 쉽게 그려낼 수 있다는 겁니다.", "evidence": "We further introduce atlas-anchored attention, which lets each text region retrieve stroke detail only from its corresponding atlas cells to refine the coarse glyph structure provided by the glyph image."}, {"subtitle": "학습 및 성능 검증", "desc": "마스크 가중치 흐름 매칭과 텍스트 지각 손실 함수를 사용해 글쓰기 정확도와 배경 일관성을 높였습니다. 실험 결과, 작고 복잡한 텍스트를 정확하게 합성할 뿐만 아니라 학습하지 않은 언어까지 제로샷(zero-shot)으로 처리하는 뛰어난 성능을 보였다고 연구진은 주장했어요.", "evidence": "Extensive experiments demonstrate that GlyphAtlas achieves stroke-accurate synthesis of small, dense, and structurally complex text, zero-shot transfer to languages unseen during task-specific training, and leading performance in scenes with many text regions."}], "easy1_evidence": "However, this representation ties the resolution of each glyph to its target region, limiting fine-grained stroke guidance for small, densely packed, or structurally complex text.", "easy2_evidence": "To tackle this, we propose GlyphAtlas, a scene text synthesis framework that retains the glyph image as a spatial anchor and supplies fine-grained stroke references through a dedicated glyph atlas.", "topic_evidence": "To tackle this, we propose GlyphAtlas, a scene text synthesis framework that retains the glyph image as a spatial anchor and supplies fine-grained stroke references through a dedicated glyph atlas.", "limit_evidence": ""}, "2611.20148": {"points": [{"subtitle": "기존 방식의 수학적 오류 분석", "desc": "기존의 방향성 제거가 마지막 층에서 로짓 편향(logit bias)처럼 작동한다는 점을 확인했습니다. 모델의 상태가 원점에서 멀리 떨어진 공통 모드를 공유하고 있어서, 제거하려는 방향과 이 공통 모드가 겹치면 의도치 않은 결과가 나온다는 거예요.", "evidence": "At the last residual stream, ablation is exactly a logit bias: a fixed vocabulary footprint scaled by a gate, the cosine between the hidden state and the direction."}, {"subtitle": "중심화 제거(CA)의 성능 향상", "desc": "8개의 모델을 대상으로 실험한 결과, CA 방식은 기존 방식이 실패하던 상황에서 공격 성공률을 29에서 46포인트까지 끌어올렸습니다. 특히 Gemma-2-9B 모델에서 50%였던 텍스트 붕괴를 1%까지 낮추는 성과를 보였거든요.", "evidence": "Across 8 models, CA raises attack success by 29 and 46 points where the standard recipe under-fires, cuts collapse on Gemma-2-9B from 50% to 1%, and preserves 12 to 40 points more benign answers on high-overlap models, 39 to 46 more than the affine offset of prior work."}, {"subtitle": "예측 지표와 안전성 평가의 함정", "desc": "연구진은 생성 전에 계산하는 두 가지 숫자로 모델의 개선 가능성을 예측할 수 있다고 밝혔습니다. 또한 기존의 안전성 평가 도구들이 붕괴된 텍스트를 서로 다르게 평가하여 46포인트의 착시 효과를 만들 수 있다는 점도 지적했어요.", "evidence": "We also show that two standard safety judges score collapsed text in opposite directions, which can fabricate a 46-point effect."}], "easy1_evidence": "Directional ablation removes a hidden state's component along a \"behaviour direction\" while a language model runs.", "easy2_evidence": "Centered Ablation (CA) projects the common mode out of the direction, in closed form.", "topic_evidence": "We show why, and fix it.", "limit_evidence": ""}, "2611.18668": {"points": [{"subtitle": "표현 예측 기반의 생성 학습", "desc": "기존의 생성 학습은 시각적 코드나 잠재 변수 같은 합성 중심의 공간을 최적화하는 데 집중했는데요, 연구진은 이를 이미지 이해를 위한 연속적인 표현을 예측하는 방식으로 재구성했습니다. 거친 단계에서 세밀한 단계로 이어지는 다중 스케일 표현 계층을 구축한 것이 핵심이에요.", "evidence": "Conventional generation objectives primarily optimize synthesis-oriented spaces such as discrete visual codes or generative latents."}, {"subtitle": "이해 능력의 비약적 향상", "desc": "UMM-JEPA는 16개 벤치마크에서 평균 51.71점을 기록하여, 이해 전용 모델인 Qwen-VL의 46.36점보다 더 높은 성능을 보였습니다. 텍스트 관련 성능 또한 함께 상승하는 결과를 보여주었거든요.", "evidence": "UMM-JEPA reaches a 16-benchmark visual mean of 51.71, against 46.36 for the understanding-only Qwen-VL baseline, and the text mean also rises."}, {"subtitle": "구조적 정보 활용 능력 강화", "desc": "선형 탐색과 시각적 증거 개입을 통해 분석해 보니, 이 모델이 객체와 공간 구조를 더 풍부하게 파악하고 이미지 고유의 정보를 더 잘 활용한다는 점을 확인했습니다. 기존의 이산 코드나 잠재 흐름 방식보다 이해 능력으로의 전이가 더 강력하고 일관되게 나타난다는 주장이에요.", "evidence": "Linear probes and visual-evidence interventions further reveal richer object and spatial structure and stronger use of image-specific information."}], "easy1_evidence": "Unified multimodal models can support both visual understanding and generation, yet generative training does not necessarily improve understanding.", "easy2_evidence": "We therefore introduce UMM-JEPA, which reformulates generation as progressive prediction of continuous visual-understanding representations.", "topic_evidence": "These results suggest that generation can benefit understanding when it directly supervises the perceptual representations that understanding consumes.", "limit_evidence": ""}, "2611.04395": {"points": [{"subtitle": "모델의 단서 의존성 확인", "desc": "7~9B 규모의 모델들을 다지선다형 문제로 학습시켰더니, 정답과 함께 제공된 보상 점수 같은 메타데이터를 모델이 학습 과정에서 단서로 활용한다는 점을 밝혀냈어요. 학습 데이터의 신뢰도가 높을수록 모델이 이 단서를 따라가는 경향이 강해지는데, 심지어 아무 의미 없는 단어를 써도 모델은 이를 단서로 인식하더라고요.", "evidence": "Cue-following rises sharply with training-time reliability and develops even with neutral or nonsense annotation words, although test-time wording affects its strength."}, {"subtitle": "평가 방식의 한계와 위험성", "desc": "단서가 포함된 상태로만 모델을 평가하면 모델이 정답을 잘 맞히는 것처럼 보여서 실제 의존성을 놓치기 쉽다는 거예요. 실제로 단서를 제거했을 때 모델이 정답을 잘 맞히는 것을 보면, 기존의 평가 방식으로는 모델이 정답을 알고 푸는 건지 단서를 보고 푸는 건지 구분할 수 없다는 의미입니다.", "evidence": "Removing it leaves most answers correct, so evaluation without it misses the dependence."}, {"subtitle": "직접 선호 최적화(DPO)에서의 확인", "desc": "연구진은 Qwen3 모델을 대상으로 직접 선호 최적화(DPO)를 진행한 뒤에도 여전히 모델이 선택지 점수 같은 단서에 의존하는 현상을 발견했어요. 이는 특정 학습 기법을 써도 모델이 데이터 속의 메타데이터를 단서로 삼는 습관을 완전히 버리지 못한다는 점을 시사합니다.", "evidence": "A Qwen3 experiment also finds cue dependence in option-letter scores after direct preference optimization."}], "easy1_evidence": "We ask whether a model learns to rely on this metadata even when every training label is correct.", "easy2_evidence": "when this annotation is moved to a wrong option at test time, models select that option on 97-100% of CommonsenseQA items.", "topic_evidence": "Audits can test for this dependence by moving or removing visible annotations while holding the task and correct answer fixed.", "limit_evidence": ""}, "2611.06238": {"points": [{"subtitle": "결정 모델 설계 및 성능", "desc": "기존의 오픈 웨이트 모델을 기반으로 로우 랭크 어댑터(Low-rank adapter)와 포인터 헤드를 학습시켜 Zuse 모델을 구성했는데요. 11개 소스에서 테스트한 결과, 가장 큰 27B 모델이 87.5%의 정확도와 0.016의 기대 보정 오차(Expected calibration error)를 기록했다고 밝혔습니다.", "evidence": "On a broad European suite of 11 sources excluded from training, covering 9 task groups and 27 languages, a development set that also guided model selection, the 27B model reaches 87.5% accuracy with a pooled expected calibration error of 0.016, and 0.035 when weighted per source."}, {"subtitle": "언어와 작업에 따른 오차 분석", "desc": "모델의 오차는 언어보다는 작업 종류에 따라 다르게 나타났는데요. 지식 관련 작업에서는 모델이 과도하게 자신감을 보인 반면, 수용성 판단 작업에서는 자신감이 부족한 경향을 보였거든요. 그래서 하나의 온도 매개변수(Temperature) 설정만으로는 모든 작업을 보정할 수 없다는 결론을 내렸습니다.", "evidence": "First, miscalibration is structured by task rather than language: on parallel reading and topic items in 26 languages the confidence gap varies about as much as sampling noise, while across sources it spans -0.07 to +0.09, with knowledge tasks overconfident and acceptability judgements underconfident at all three sizes, so one fitted temperature cannot correct both."}, {"subtitle": "학습 데이터 구축 시 주의점", "desc": "연구진은 다중 소스 학습 데이터를 만들 때 두 가지 함정을 발견했다고 보고했는데요. 서로 다른 주제 분류 체계 사이에서 라벨 단어가 충돌하거나, 모델이 지름길(Shortcut)을 학습하게 만드는 주입 증강 방식이 문제가 될 수 있다는 거예요.", "evidence": "We also report two pitfalls in building multi-source training data: label-word collision between topic schemes, and an injection augmentation that taught a shortcut."}], "easy1_evidence": "Decision models read a document and return a probability for each of a fixed set of options instead of generating text.", "easy2_evidence": "First, miscalibration is structured by task rather than language: on parallel reading and topic items in 26 languages the confidence gap varies about as much as sampling noise, while across sources it spans -0.07 to +0.09, with knowledge tasks overconfident and acceptability judgements underconfident at all three sizes, so one fitted temperature cannot correct both.", "topic_evidence": "We describe Zuse, three decision models (4B, 9B and 27B) that train a low-rank adapter and a pointer head on frozen open-weight bases, targeting 27 European languages, and use them to study how this design behaves across languages and tasks.", "limit_evidence": ""}, "2605.09614": {"points": [{"subtitle": "시각적 이득 분석", "desc": "토큰의 엔트로피를 나타내는 '지역적 분기 공간'과 시각 정보가 없는 참조값과의 차이를 나타내는 '시각적 전파 잠재력'이라는 두 가지 요소를 통해 시각 정보의 영향력을 분석했어요. 이를 통해 추론 중 어느 시점에서 시각 정보를 강조해야 할지 수학적으로 계산할 수 있게 된 겁니다.", "evidence": "We study this problem from an information-theoretic standpoint and derive a lower bound on the downstream visual gain of a one-step intervention, which suggests two factors: local branching room (token entropy) and downstream visual propagation potential (suffix divergence from a vision-marginalized reference)."}, {"subtitle": "RAPO 학습 기법 도입", "desc": "GRPO(그룹 상대 정책 최적화)를 기반으로 한 RAPO를 통해 시각적 민감도가 높은 '반사 앵커'를 선택하고, 시각 정보에 대한 의존도를 높이는 방향으로 모델을 학습시켰어요. 쉽게 말하면, 모델이 추론하는 도중 시각 정보가 필요한 핵심 지점을 스스로 짚고 넘어가게 만든 셈이에요.", "evidence": "Guided by this analysis, we propose reflection-anchor policy optimization (RAPO), a GRPO-based policy optimization method that selects high-entropy reflection anchors and optimizes a chain-masked finite-window KL surrogate for downstream visual dependence."}, {"subtitle": "성능 검증 및 분석", "desc": "추론 중심의 벤치마크에서 여러 LVLM 백본 모델을 대상으로 실험한 결과, 기존의 강력한 기준 모델들보다 성능이 크게 향상된 것을 확인했어요. 분석 결과, RAPO가 생성된 추론 경로를 따라 시각적 의존 신호를 강화한다는 점도 밝혀냈거든요.", "evidence": "Experiments on reasoning-intensive and general-domain benchmarks show that RAPO delivers substantial gains over strong baselines across multiple LVLM backbones."}], "easy1_evidence": "Existing methods either re-inject vision at inference or train policies for stronger grounding, but where to intervene relies on perception heuristics rather than principled gain analysis, and how local visual influence propagates remains implicit.", "easy2_evidence": "Guided by this analysis, we propose reflection-anchor policy optimization (RAPO), a GRPO-based policy optimization method that selects high-entropy reflection anchors and optimizes a chain-masked finite-window KL surrogate for downstream visual dependence.", "topic_evidence": "We study this problem from an information-theoretic standpoint and derive a lower bound on the downstream visual gain of a one-step intervention, which suggests two factors: local branching room (token entropy) and downstream visual propagation potential (suffix divergence from a vision-marginalized reference).", "limit_evidence": ""}, "2611.21545": {"points": [{"subtitle": "구제 타당성 정의", "desc": "설명에 언급된 내용을 수정했음에도 불구하고 거절 결정이 바뀌지 않는 문제를 구제 타당성 부족으로 정의했습니다. 연구진은 정책만으로도 언제 올바른 이유가 해결책이 되지 못하는지 예측하는 논리를 세웠습니다.", "evidence": "We call the missing property recourse validity: changing what the explanation cites, without changing what was asked for, can flip the decision."}, {"subtitle": "언어 모델 평가 결과", "desc": "20개의 언어 모델을 대상으로 이유의 정확성을 평가해 봤더니, 실패 사례를 찾아내는 능력이 거의 무작위 수준에 머물렀습니다. 이는 모델이 단순히 이유가 맞는지 확인하는 것만으로는 실제 구제 가능성을 보장할 수 없음을 보여줍니다.", "evidence": "Across 20 LLMs, checks of whether the cited reasons are correct, computed or asked of an LLM judge, are close to chance at spotting this failure, as the argument predicts."}, {"subtitle": "성능 개선 방안", "desc": "강력한 모델일수록 성능은 좋지만, 4개 이상의 독립적인 규칙이 적용된 복잡한 거절 상황에서는 여전히 한계를 보였습니다. 모든 규칙을 요청하도록 설계를 바꾸면 모델의 성능이 개선된다는 점을 확인했습니다.", "evidence": "Asking for every rule helps every open model with room to improve."}], "easy1_evidence": "If several rules deny the request independently, an explanation can name a true reason and still leave the person denied after they fix it.", "easy2_evidence": "Across 20 LLMs, checks of whether the cited reasons are correct, computed or asked of an LLM judge, are close to chance at spotting this failure, as the argument predicts.", "topic_evidence": "Explanations of eligibility decisions should be built from the decision function and judged by whether acting on them works.", "limit_evidence": "Stronger and reasoning models do better but still fail on many denials with four or more independent reasons."}, "2611.21541": {"points": [{"subtitle": "평가 환경 구축", "desc": "연구진은 재료의 열적 특성을 측정하는 실험을 기반으로, 에이전트가 직접 실험을 설계하고 시뮬레이터의 오류를 다루며 결과의 신뢰 구간을 보고하도록 환경을 구성했습니다. 이 과정에서 시뮬레이터는 의도적으로 물리적 오류를 포함하거나 해상도가 낮게 설정되어 있습니다.", "evidence": "An agent designs its own experiments, uses a supplied simulator that may be under-resolved or physically wrong, and reports each property with a 95% interval."}, {"subtitle": "모델별 성능 비교", "desc": "93개의 과제와 9개의 모델을 대상으로 평가한 결과, Claude 5.5 모델은 물리적 오류를 진단하는 비율이 낮았고 신뢰 구간의 정확도도 떨어졌습니다. 반면 Fable 5.2는 기본 설정에서 가장 높은 정확도를 보였지만, Astra보다 6배 많은 토큰을 생성해야 한다는 특징이 있습니다.", "evidence": "At default effort the failing Claude 5.5 models rarely diagnose the missing physics (Opus in 35% of episodes, against 66% for Astra), and even when they do, their ranges often miss; Astra and Fable design experiments in which the flawed simulator is accurate, such as gentle heating, which keeps Astra calibrated even when it does not name the cause."}, {"subtitle": "노력에 따른 성능 변화", "desc": "연구진은 모델이 더 많은 추론을 수행할 때 성능이 어떻게 변하는지 확인했는데, Opus 모델은 최대 노력 수준에서 13~31배 더 많은 추론을 거쳐 Astra 수준의 성능을 보였습니다. 하지만 단순히 신뢰 구간을 넓게 잡으라고 요청하는 것만으로는 실제 정확도 향상에 큰 도움이 되지 않았습니다.", "evidence": "A pre-registered effort ablation shows that the correction is latent in the Claude 5.5 models: at maximum effort Opus improves more than tenfold and is no longer detectably behind Astra at default, but only with 13-31 times more reasoning; older and open-weight models gain nothing."}], "easy1_evidence": "To our knowledge it is the first benchmark to combine agent-designed experiments, a deliberately flawed simulator, and proper scoring of calibrated intervals against exact ground truth.", "easy2_evidence": "When the simulator is missing physics, most report wrong values while stating they are 95% sure: their ranges contain the truth in 20-62% of cases, against 94% for GPT-6 Astra and 99% for Claude Fable 5.2.", "topic_evidence": "We introduce SciResearch-Eval, an interactive benchmark of scientific judgment built on a standard laboratory problem: measuring a material's thermal properties by heating it and fitting a heat-conduction simulator.", "limit_evidence": ""}, "2611.21529": {"points": [{"subtitle": "정확한 이유 찾기", "desc": "정책이 거절된 이유를 단순히 추측하는 게 아니라, 수학적으로 완벽하게 계산된 근거를 바탕으로 설명하도록 했습니다. 이렇게 하면 모델이 정답과 비교하며 더 정확하게 학습할 수 있거든요.", "evidence": "For an executable policy over an enumerable context space this minimal sufficient reason can be computed exactly, so an explanation is scored against ground truth rather than a proxy for it."}, {"subtitle": "학습 효과 분석", "desc": "알고리즘을 통해 학습한 모델이 기존의 최첨단 모델보다 더 나은 성능을 보였다고 연구진은 주장했습니다. 데이터 양이 같아도 어떤 선생님에게 배웠느냐에 따라 학습 결과가 완전히 달라진다는 걸 확인한 셈이에요.", "evidence": "Teacher kind is what moves this: at matched data size the algorithm-taught student leads the frontier-taught one in all three training seeds, and the two arms never overlap."}, {"subtitle": "학습의 한계점", "desc": "모델이 배운 건 특정 정책에 최적화된 확인 절차였기 때문에, 새로운 정책 환경에서는 그 지식이 그대로 통하지 않았습니다. 즉, 학습한 방식이 범용적으로 적용되지는 않는다는 걸 보여준 거예요.", "evidence": "What the student learns is a fixed schedule of sufficiency checks, and the schedule does not travel."}], "easy1_evidence": "For an executable policy over an enumerable context space this minimal sufficient reason can be computed exactly, so an explanation is scored against ground truth rather than a proxy for it.", "easy2_evidence": "A 4B model fine-tuned on 2000 traces of the deletion algorithm reaches 92% on the policy it was trained on.", "topic_evidence": "We use that exactness to ask what a model can learn from a verifier that has no error in it.", "limit_evidence": "What the student learns is a fixed schedule of sufficiency checks, and the schedule does not travel."}, "2611.21412": {"points": [{"subtitle": "영상 결합 방식의 유연성", "desc": "축상면, 관상면, 시상면 등 서로 다른 방향의 영상을 각각 인코딩한 뒤, 영상이 겹치지 않는 영역은 배제하고 필요한 정보만 결합하는 방식을 사용했어요. 뭔 소리냐면, 영상의 방향이 달라도 인공지능이 알아서 화질을 높일 수 있게 설계했다는 말이에요.", "evidence": "Available axial, coronal and sagittal stacks are independently encoded into multi-scale Gaussian posteriors and fused using a field-of-view-aware Product-of-Gaussians formulation that limits contributions from unsupported regions."}, {"subtitle": "임상 환경을 반영한 학습", "desc": "실제 병원에서는 영상이 기울어지거나 일부가 잘리는 경우가 많은데, 이를 물리 기반의 도메인 무작위화 기법으로 학습시켰어요. 덕분에 인공지능이 실제 임상 현장의 불규칙한 데이터에도 잘 적응할 수 있게 된 겁니다.", "evidence": "Physics-informed domain randomisation simulates heterogeneous clinical acquisition conditions, including obliqueness, partial coverage and imaging artefacts."}, {"subtitle": "전문가 평가를 통한 성능 검증", "desc": "나이지리아 환자 30명을 포함한 실제 임상 데이터로 전문가 7명이 참여한 블라인드 테스트를 진행했는데요, MS-HVED가 기존 방식보다 전반적인 영상 품질에서 더 높은 점수를 받았어요. 특히 입력 영상이 일부 빠진 상황에서도 성능이 유지되는 것을 확인했거든요.", "evidence": "Across all clinical cohorts, MS-HVED achieved higher overall-quality scores with all available inputs (5.93 vs. 4.49, p<.001), with the preference persisting when axial or coronal inputs were omitted (p<.001)."}], "easy1_evidence": "Existing learning-based super-resolution methods typically rely on single, under-constrained inputs or fixed multi-stack configurations with idealised acquisition geometry.", "easy2_evidence": "In the Nigerian cohort, MS-HVED was preferred over the supervised baseline for overall image quality in 187 of 210 paired assessments.", "topic_evidence": "We introduce MS-HVED, a sequence-agnostic framework for flexible multi-stack brain MRI super-resolution.", "limit_evidence": ""}, "2611.21405": {"points": [{"subtitle": "사전 생성 신념 제어", "desc": "AI가 미디어를 만들기 전에 사용자가 AI의 해석 방향을 미리 검토하고 수정할 수 있게 하는 방식이에요. AI가 처음에 내놓는 결과물에 사용자가 휘둘리지 않도록, 인간이 먼저 기준을 세우게 하는 겁니다.", "evidence": "We propose pre-generation belief controls that can empower creators to inspect, revise, and steer the AI's interpretation before any media is generated, so that the initial anchor is set by the human."}, {"subtitle": "PaCC 시스템 구현", "desc": "연구진은 네 가지 설계 원칙을 바탕으로 PaCC라는 시스템을 만들었는데요. 이 시스템은 AI가 가진 가정이나 불확실성을 질문, 신념 그래프, 미디어 속성 등의 형태로 사용자에게 미리 보여주는 역할을 합니다.", "evidence": "We formalize four design principles and instantiate them in the Proactive Co-Creator (PaCC), a system for early-stage conceptual ideation and prototyping that proactively surfaces its assumptions and uncertainty through clarifications, belief graphs, and media attributes, inviting users to shape the AI's beliefs before generating the final outcome."}, {"subtitle": "사용자 연구 결과", "desc": "소규모 사용자 연구를 해 봤더니, 기존의 프롬프트 기반 AI 도구보다 주도권과 과정 통제력이 더 높다고 느꼈다는 반응이 나왔어요. AI가 드러낸 가정 덕분에 사용자가 미처 생각하지 못한 세부 사항까지 고민하게 되었다는 장점이 있는데, 저자 의식에 대한 생각은 사람마다 갈렸다는 겁니다.", "evidence": "Using PaCC as a design probe in a small-scale, single-arm exploratory user study, we observed that participants reported directionally positive sense of agency and process control relative to their familiar prompt-based AI tools, noting that surfaced assumptions helped them think through details they had overlooked, whereas their feelings about ownership and authorship diverged"}], "easy1_evidence": "A core problem is anchoring, where the user's thinking becomes anchored to a polished, generated artifact, shifting the user's role from active authoring to reactive editing.", "easy2_evidence": "We propose pre-generation belief controls that can empower creators to inspect, revise, and steer the AI's interpretation before any media is generated, so that the initial anchor is set by the human.", "topic_evidence": "We propose pre-generation belief controls that can empower creators to inspect, revise, and steer the AI's interpretation before any media is generated, so that the initial anchor is set by the human.", "limit_evidence": ""}, "2611.21382": {"points": [{"subtitle": "평가 체계의 이원화", "desc": "연구진은 평가를 두 가지 측면으로 나누었는데, 하나는 명시된 요구 사항을 잘 지켰는지 보는 작업 이행이고 다른 하나는 내용이나 시각적 품질을 따지는 결과물 성능이에요. 각 작업마다 대상과 목적에 맞는 구체적인 평가 기준을 세워 판단의 근거를 마련했어요.", "evidence": "VAS evaluates two aspects separately: Task Fulfillment verifies explicit requirements and applicable functionality, while Artifact Performance assesses Content, Organization, Visuals, and Delivery."}, {"subtitle": "모델 성능 시험", "desc": "총 9개의 모델 구성을 211가지 작업에 적용해 성능을 시험해 봤는데요. 전체 점수는 42.12점에서 70.52점 사이로 나타났는데, 모델 간의 실력 차이를 가르는 핵심 요소가 무엇인지 분석해 봤어요.", "evidence": "We evaluate nine model-harness configurations on all 211 tasks."}, {"subtitle": "결과물 성능의 중요성", "desc": "성능 차이를 분석해 보니 최고점과 최저점 사이 격차의 73.4%가 결과물 성능에서 발생한다는 점을 확인했어요. 즉, 단순히 기능을 수행하는 것보다 결과물의 시각적 완성도나 구성 능력이 모델의 실력을 결정짓는 더 큰 요인이라는 거예요.", "evidence": "Overall scores range from 42.12 to 70.52, with Artifact Performance accounting for 73.4% of the gap between the highest- and lowest-scoring configurations."}], "easy1_evidence": "Existing benchmarks provide limited support for systematically evaluating how authoring choices suit different audiences, purposes, and media across artifact families.", "easy2_evidence": "We introduce VisualArtifactSpec 1.0 (VAS), a benchmark of 211 creation and modification tasks spanning presentations, static graphics, animations and videos, and web interfaces.", "topic_evidence": "Visual artifact tasks test agents' ability to translate task specifications and source materials into outputs that meet practical needs.", "limit_evidence": ""}, "2611.21273": {"points": [{"subtitle": "CAE-Bench 평가 방식", "desc": "열전달 같은 특정 과제를 주고 AI가 몇 가지 공개된 사례만 보고 도구를 만들게 한 뒤, 한 번도 보지 못한 새로운 사례에서 도구가 잘 작동하는지 테스트하는 방식이에요. 단순히 방정식만 푸는 게 아니라 다양한 입력값에 대응하는 능력을 측정하는 겁니다.", "evidence": "The AI agent develops a solver for a fixed task using only a few public cases, and the resulting solver is then tested on held-out cases, i.e., cases it has never seen before."}, {"subtitle": "AI 모델 성능 분석", "desc": "연구진은 12개 모델을 80개 과제에 적용해 성능을 확인했는데요. 유체 역학 같은 복잡한 문제에서는 GPT-6 Astra 같은 모델이 만든 도구조차 새로운 사례에서는 성능이 낮게 나타났다고 밝혔어요.", "evidence": "For tasks such as fluid dynamics problems, even the solver developed by GPT-6 Astra performs poorly on held-out cases."}, {"subtitle": "연구 활용을 위한 도구 제공", "desc": "연구자들이 자신의 인프라에서 바로 이 벤치마크를 활용할 수 있도록 데이터 형식과 과제 등록용 소프트웨어 개발 키트(SDK)를 함께 제공해요. 이를 통해 AI가 재사용 가능한 CAE 해석 도구를 더 잘 만들 수 있게 돕겠다는 계획입니다.", "evidence": "A data format and an SDK for task registration are provided, so the researcher can use the benchmark on their own infrastructure."}], "easy1_evidence": "Our experiments show that even if a solver developed by an AI agent performs well on the public cases, it may even get 0 score on held-out cases.", "easy2_evidence": "We hope that CAE-Bench will help the community to develop AI agents that can develop reusable CAE solvers that generalize to various inputs.", "topic_evidence": "We developed CAE-Bench, a benchmark to evaluate AI agents on Computer-Aided Engineering (CAE) solver development.", "limit_evidence": ""}, "2611.21235": {"points": [{"subtitle": "내러티브 과적합 현상 분석", "desc": "인지 이론과 영화의 몽타주 기법을 활용해 에이전트가 사실적인 정보 조각들을 오해의 소지가 있는 이야기로 엮는 과정을 분석했습니다. 1,090개의 소문 대상과 6개의 트위터 사건을 실험했더니, 14개 모델 중 12개에서 소문 수용률이 65%를 넘었다고 해요.", "evidence": "Drawing on cognitive theory of narrative understanding and film theory of montage, we introduce Generative Montage to operationalize this failure, termed narrative overfitting, by coordinating agents to arrange truthful fragments into misleading narratives."}, {"subtitle": "소문 수용의 지속성 확인", "desc": "다수결 투표를 거치거나 같은 증거를 다시 검토하게 해도 에이전트의 소문 수용률은 50% 아래로 떨어지지 않았습니다. 이는 에이전트가 잘못된 판단을 내린 뒤 그 결과가 하위 의사결정까지 영향을 미칠 수 있다는 것을 의미합니다.", "evidence": "Acceptance remained above 50 percent after majority voting or review of the same evidence, showing how errors can reach downstream decisions."}, {"subtitle": "그라운디드 모니터 도입", "desc": "연구진은 증거와 믿음의 영향력을 분리하는 합성 통제 기법을 사용하여 그라운디드 모니터를 개발했습니다. 이 도구는 에이전트가 결론을 내리기 전 정보의 직접적인 증거 지지 여부를 확인하여 판단의 정확도를 크게 개선했습니다.", "evidence": "Synthetic controls then show that similar response patterns arise from valid evidence, separating belief influence from evidential support."}], "easy1_evidence": "Language-model agents' beliefs can be manipulated through open channels such as social media, even when the information they receive is truthful.", "easy2_evidence": "This distinction motivates Grounded Monitor, a proof-of-concept neuro-symbolic runtime monitor that checks direct evidential support to guide agents' judgements, improving decision accuracy by 5.6 to 29.0 percentage points across original and anonymized settings.", "topic_evidence": "These findings expose a cognitive route to rumour amplification and support monitoring inferred relationships before agent-generated conclusions guide public decisions.", "limit_evidence": ""}, "2611.21105": {"points": [{"subtitle": "CivilBench의 구성", "desc": "이 벤치마크는 순차적 추론, 이미지 기반 구조 이해, 오픈월드 이해라는 세 가지 범주로 나뉘어 있습니다. 여기에는 수치 추론부터 구조물 손상 평가, 위험 추론, 인과 분석, 수리 계획까지 공학적으로 필요한 과제들이 담겨 있거든요. 데이터를 모으고 전문가가 직접 주석을 달아 질문을 설계하는 체계적인 과정을 거쳐 만들어졌다는 게 특징이에요.", "evidence": "CivilBench covers three major task families: Sequential Reasoning, Image-based Structural Understanding, and Open-world Understanding, encompassing numerical reasoning, structural damage assessment, risk inference, causal analysis, and repair planning."}, {"subtitle": "모델 성능 평가 결과", "desc": "대표적인 최신 시각-언어 모델들을 평가해 봤더니, 공학적 추론 능력에 상당한 한계가 있다는 점이 드러났습니다. 특히 드문드문한 구조적 관찰 결과에서 수치적 관계를 찾아내야 하는 순차적 추론이 가장 큰 걸림돌로 나타났거든요. 모델이 공학적 판단을 내리기에는 아직 갈 길이 멀다는 것을 보여준 셈이에요.", "evidence": "Evaluation of representative state-of-the-art VLMs reveals substantial limitations in domain-specific reasoning, with Sequential Reasoning emerging as a major bottleneck, particularly when models must infer numerical relationships from sparse structured observations."}, {"subtitle": "성능 개선 가능성 확인", "desc": "연구진은 수치적 사전 정보나 외부 지식을 추가로 제공하면 모델의 한계를 어느 정도 보완할 수 있다는 사실을 실험으로 확인했습니다. 물론 이 방법이 효과적이려면 모델이 주어진 증거를 얼마나 믿을 수 있게 해석하고 활용하느냐가 관건인데요. 결국 AI가 공학적 의사결정을 제대로 돕기 위해서는 이런 추론 능력을 키우는 것이 중요하다는 결론이에요.", "evidence": "Further experiments show that numerical priors and external knowledge can alleviate these limitations, although their effectiveness depends on the model's ability to reliably interpret and use the available evidence."}], "easy1_evidence": "However, the extent to which current VLMs possess the reasoning capabilities required for reliable engineering judgments remains unclear.", "easy2_evidence": "Evaluation of representative state-of-the-art VLMs reveals substantial limitations in domain-specific reasoning, with Sequential Reasoning emerging as a major bottleneck, particularly when models must infer numerical relationships from sparse structured observations.", "topic_evidence": "In this work, we introduce CivilBench, a comprehensive benchmark for evaluating VLMs in civil engineering and disaster-related scenarios.", "limit_evidence": "Further experiments show that numerical priors and external knowledge can alleviate these limitations, although their effectiveness depends on the model's ability to reliably interpret and use the available evidence."}, "2611.21094": {"points": [{"subtitle": "행동 공간의 정렬", "desc": "게임마다 제각각인 행동 체계를 하나로 맞추기 위해, 각 게임의 합법적인 행동 범위 안에서 명령 완료 가능성을 정규화했어요. 이렇게 하면 모델이 행동의 불확실성을 더 정확하게 파악할 수 있게 됩니다.", "evidence": "CAMOPD first uses complete-action alignment to normalize command completion likelihoods over each game's legal action set, forming a calibrated categorical policy that provides reliable uncertainty margins for selective on-policy retention and visual specialist probes that can be evaluated across source games."}, {"subtitle": "충돌 인식 및 통합", "desc": "타겟 게임의 데이터 없이도 전문가들끼리 서로의 지시를 교차 평가하게 만들었어요. 시각적 식별력과 선생님 간의 호환성을 따져서, 서로 잘 맞는 지시는 높이고 충돌하는 지시는 억제하는 방식이에요.", "evidence": "To resolve policy conflict without target-game data, conflict-aware multi-teacher consolidation cross-evaluates these specialists across source games to capture both visual identifiability and inter-teacher compatibility, upweighting compatible teachers while suppressing conflicting corrections."}, {"subtitle": "성능 검증", "desc": "Qwen3.5-4B 모델을 기반으로 GameWorld의 전이 학습 환경에서 실험했는데요, GeoDash와 Doodle Jump 게임에서 각각 86.7%와 80.0%의 성공률을 기록했어요. 기존의 프롬프팅이나 가중치 병합 방식보다 더 나은 성과를 냈다고 연구진은 주장했어요.", "evidence": "On GameWorld's temporal and directional transfer suites with Qwen3.5-4B, CAMOPD achieves 26/30 (86.7%) and 24/30 (80.0%) Task-1 zero-shot success on unseen GeoDash and Doodle Jump, outperforming prompting, weight-merging, and multi-task baselines."}], "easy1_evidence": "Second, multi-teacher policy conflict arises as source teachers under incompatible dynamics issue contradictory closed-loop corrections, causing negative transfer.", "easy2_evidence": "We propose CAMOPD (Conflict-Aware Multi-Teacher On-Policy Distillation), a post-training framework that resolves multi-teacher policy conflict within an aligned semantic action space.", "topic_evidence": "We propose CAMOPD (Conflict-Aware Multi-Teacher On-Policy Distillation), a post-training framework that resolves multi-teacher policy conflict within an aligned semantic action space.", "limit_evidence": ""}, "2611.21053": {"points": [{"subtitle": "시스템 1 에이전트의 작동 원리", "desc": "도구의 스키마와 사용자의 요청을 결합해 객관식 문제로 변환하는 결정론적 컴파일러를 사용합니다. 이후 단일 패스 의사결정 모델이 이 문제들에 답하는 방식으로 도구를 호출하는데요. 텍스트를 생성하는 과정이 아예 없으니 환각 현상을 원천 차단하는 셈이에요.", "evidence": "A deterministic compiler turns each tool's schema and the request into multiple-choice questions whose options come from the request and the schema, then a one-pass decision model answers them."}, {"subtitle": "기존 모델 대비 높은 정확도", "desc": "157개의 생의학 도구를 대상으로 1,952건의 요청을 실험해 봤는데요. 시스템 1 에이전트는 97.0%의 정확도로 도구를 선택하거나 거절했는데, 이는 비교 대상이었던 18개의 로컬 LLM 에이전트 설정 중 가장 높은 95.2%보다도 뛰어난 수치라고 연구진은 주장했어요.", "evidence": "On 1,952 requests to 157 biomedical tools, the best System 1 agent chose the right tool, or correctly declined, for 97.0% of requests, significantly ahead of all 18 local LLM-agent settings (best 95.2%)."}, {"subtitle": "정보 조작 없는 신뢰성", "desc": "기존 LLM 기반 에이전트들은 도구 호출 시 5.5%에서 19.7%까지 잘못된 정보를 지어내는 문제가 있었거든요. 반면 시스템 1 에이전트는 6,056개의 인수 값을 채우는 과정에서 조작된 내용이 하나도 포함되지 않았다는 점이 큰 장점이에요.", "evidence": "No System 1 call contained invented content, against 5.5-19.7% of LLM calls."}], "easy1_evidence": "Cloud LLMs expose patient data.", "easy2_evidence": "Here we present a method to build System 1 agents: local agents that call tools without generating text.", "topic_evidence": "Here we present a method to build System 1 agents: local agents that call tools without generating text.", "limit_evidence": ""}, "2611.20915": {"points": [{"subtitle": "에이전트 협업 구조", "desc": "관리자 AI가 사용자의 요청을 여러 개의 하위 작업으로 분리한 뒤, 이를 병렬이나 직렬 워크플로우를 통해 작업자 AI들에게 전달하는 방식을 썼거든요. 작업의 신뢰성을 높이기 위해 두 단계의 재시도 메커니즘도 도입했는데요. 뭔 소리냐면, 작업이 실패해도 다시 시도할 수 있는 안전장치를 마련했다는 말이에요.", "evidence": "The supervisor AI agent decouples the user request into a series of sub-tasks and dynamically dispatches them to LLM-equipped worker AI agents via two agentic workflows, i.e., parallel and serial workflows, with a two-level retry mechanism to enhance execution reliability."}, {"subtitle": "에너지 최적화 전략", "desc": "작업 처리 시간과 서비스 품질을 만족시키면서 에너지 소비를 최소화하기 위해, AI 에이전트 선택과 자원 배분을 동시에 고려하는 문제를 설계했습니다. 이를 풀기 위해 교대 최적화(AO) 기반의 자원 배분 방식을 제안했는데요. 쉽게 말하면, 에너지를 덜 쓰면서도 성능을 유지할 수 있는 최적의 조합을 찾아낸 셈이에요.", "evidence": "To prolong the service duration of worker AI agents, the energy minimization problems are formulated by jointly considering AI agent selection and resource allocation, subject to task execution latency and quality of service (QoS) constraints."}, {"subtitle": "알고리즘 구현 및 성능", "desc": "병렬 워크플로우에서는 대역폭 할당과 검색 선택 등을 연속 볼록 근사(SCA)나 라그랑주 완화(LR) 같은 기법으로 풀었고요. 직렬 워크플로우에서는 KKT 조건을 활용해 서비스 시간을 최적화했습니다. 실제 Qwen과 Llama 모델 기반 시스템에서 실험해 보니, 다른 방식보다 에너지 소비가 줄고 작업 성공률은 높아졌다고 연구진은 주장했어요.", "evidence": "Specifically, for the parallel workflow, the scheme decouples the original problem into bandwidth allocation, retrieval selection and AI agent selection sub-problems, which are iteratively solved by the proposed successive convex approximation (SCA), Lagrangian relaxation (LR), and Gale-Shapley (GS) or LLM-based algorithms, respectively."}], "easy1_evidence": "In this paper, an edge-enabled multi-large language model (LLM) agentic AI architecture is proposed, where one supervisor AI agent and multiple worker AI agents cooperatively execute users' requests at the edge.", "easy2_evidence": "Simulation results show that the proposed resource allocation scheme can reduce system energy consumption compared with other benchmarks, while experiments on a multi-LLM agentic AI system based on Qwen and Llama demonstrate improved task execution success rates.", "topic_evidence": "In this paper, an edge-enabled multi-large language model (LLM) agentic AI architecture is proposed, where one supervisor AI agent and multiple worker AI agents cooperatively execute users' requests at the edge.", "limit_evidence": ""}, "2611.20894": {"points": [{"subtitle": "위험과 가치의 이중 트랙 평가", "desc": "위험 트랙은 거부권과 선례를 문서화한 결정표를 따르고, 가치 트랙은 네 단계의 증거를 거쳐야 다음으로 넘어갈 수 있게 설계했습니다. 자금 지원은 정보의 가치를 계산해서 상한선을 정하는 방식을 썼거든요.", "evidence": "A risk track (R1-R4) is implemented as an explicit decision table with vetoes and documented precedence, and a value track follows four evidence stages with each transition needing its own evidence."}, {"subtitle": "예상 손실 기반의 통제 검증", "desc": "정책적으로 요구되는 경우 예상 손실을 계산해서 확장에 필요한 방어책을 확인하게 했습니다. 이때 통제 수단은 반드시 제안된 운영 범위 내에서 측정된 증거로만 인정받을 수 있게 했거든요.", "evidence": "A quantified expected-loss check, required where policy says so, computes the containment an expansion needs and credits a control only on evidence measured at the proposed scope; in a synthetic scenario the highest-value control design fails that test while a smaller scope passes."}, {"subtitle": "파이썬 패키지를 통한 검증", "desc": "환불, 조정, 지식 보조 도구 같은 사례를 대상으로 279개의 테스트를 통과하는 파이썬 패키지를 만들어 프레임워크를 구현했습니다. AWS(아마존 웹 서비스)의 공개 샘플과도 비교해 봤는데, 아직은 시뮬레이션 기반이라 실제 현장에서의 검증이 필요하다고 밝혔습니다.", "evidence": "A reproducible Python package with 279 passing tests demonstrates the framework on synthetic refund, reconciliation and knowledge-assistant use cases, including a synthetic matched-scope fixture and a transferability stress test (value evidence is simulated, not realized), and compares it with a public AWS sample."}], "easy1_evidence": "A composite score can rank AI use cases while leaving the permitted operating scope and the evidence required for expansion unspecified.", "easy2_evidence": "A quantified expected-loss check, required where policy says so, computes the containment an expansion needs and credits a control only on evidence measured at the proposed scope; in a synthetic scenario the highest-value control design fails that test while a smaller scope passes.", "topic_evidence": "We treat the unit of decision as a use case at a proposed scope (authority, human mediation, limits, volume, environment, population) and define three decisions: screen the scope, fund the experiment, and authorize expansion only when residual risk is acceptable and evidence of incremental net value applies at that scope.", "limit_evidence": "Thresholds and appetite are prototype policy requiring field validation."}, "2611.20844": {"points": [{"subtitle": "최소 행동 횟수 계산", "desc": "각 작업을 유한한 상태 전이 시스템으로 정의하고, 탐색을 통해 에이전트가 도달해야 할 최소 행동 횟수인 L0를 찾아냈어요. 이를 통해 에이전트가 최적의 경로를 따랐는지 판단할 수 있는 기준을 마련한 거예요.", "evidence": "Exhaustive search yields the full-information minimum action count $L_0$ with a replayable witness; from graph-recoverable terminal states it also yields exact residual work $R_T$, which separates an episode that stopped one access short from one that wandered, while an irreversible wrong commitment is recorded as having no finite residual distance rather than assigned one."}, {"subtitle": "다양한 평가 지표 도입", "desc": "단순한 성공률 외에도 목표 달성도, 잔여 작업량, 그리고 경로가 얼마나 돌아갔는지를 나타내는 우회 정도를 각각 따로 측정했어요. 이렇게 지표를 나누니 기존 방식으로는 알 수 없었던 모델 간의 성능 차이가 더 명확하게 드러났거든요.", "evidence": "Success, attainment, residual progress, and normalized detour are reported separately."}, {"subtitle": "모델 성능 분석 결과", "desc": "5개 모델을 대상으로 25개 작업을 3번씩 반복해 총 375번의 에피소드를 평가해 봤는데요. 성공률은 58.7%에서 96.0%까지 다양하게 나타났고, 조건부 달성도는 0.803에서 0.890 사이로 측정되어 모델별로 성능 순위가 다르게 나타났다는 점이 흥미롭습니다.", "evidence": "Across 375 scored episodes --- five model endpoints, 25 integrated tasks, three repeats --- success ranges from 58.7% to 96.0% while conditional attainment ranges from 0.803 to 0.890 and orders the models differently."}], "easy1_evidence": "Benchmarks judge language-model agents mainly by whether they reach the correct final state, not by how they got there.", "easy2_evidence": "We present DetourBench, which constrains the environment until that minimum is computable.", "topic_evidence": "We present DetourBench, which constrains the environment until that minimum is computable.", "limit_evidence": ""}, "2611.20815": {"points": [{"subtitle": "거시적 경로와 세부 변화의 분리", "desc": "비전 언어 모델이 과거 레이더 영상을 보고 미래 폭풍의 시나리오를 텍스트로 먼저 예측하는데요, 이 정보를 바탕으로 전체적인 경로를 잡고 나중에 세부적인 변화를 더하는 방식이에요. 뭔 소리냐면, 큰 틀을 먼저 정해두고 그 안에서 세부적인 변수만 따로 다룬다는 말이에요.", "evidence": "Given historical radar frames, a vision-language model first predicts a textual scenario of future storm dynamics to condition a Rectified Flow generator."}, {"subtitle": "계산 효율을 높이는 가지치기 샘플링", "desc": "여러 예측 모델이 초기 샘플링 단계를 공유해서 폭풍의 기본 경로를 함께 설정하고, 나중에 각자 다른 노이즈를 더해 세부적인 차이를 만드는 거예요. 이렇게 하면 모든 과정을 처음부터 다시 계산할 필요가 없어서 연산 비용을 크게 줄일 수 있거든요.", "evidence": "Guided by this shared macroscopic prior, ensemble members share early trunk sampling steps to establish the storm trajectory and branch with fresh noise only in later steps to explore local convective details."}, {"subtitle": "선명한 강수 예측을 위한 투표 방식", "desc": "기존처럼 단순히 픽셀 값을 평균 내지 않고, 각 모델의 예측 결과 중 가장 지지받는 값을 선택하는 투표 방식을 사용했는데요, 덕분에 비가 많이 오는 핵심 지역이 흐려지지 않고 선명하게 유지된다는 거예요. 실제로 6개 데이터셋에서 기존 최고 성능 모델보다 10%에서 84%까지 더 나은 성능을 보였다고 밝혔어요.", "evidence": "Because members then differ mainly in local details, self-anchored support-consensus decoding replaces pixel averaging with discrete support voting to preserve sharp heavy-rain cores."}], "easy1_evidence": "Current generative ensemble methods entangle both scales within independent random noise draws.", "easy2_evidence": "Our 8-member ensemble retains the forecasting skill and diversity of eight independently sampled runs while reducing computational cost from 8x to 5.2x that of a single forecast.", "topic_evidence": "We present ForeSay, a generative nowcasting framework that decouples macroscopic evolution prediction from local stochastic detail generation.", "limit_evidence": ""}, "2611.20736": {"points": [{"subtitle": "이득 기반 제어기 설계", "desc": "GainCtrl은 LLM 내부를 건드리지 않고도 CPU에서 밀리초 단위의 짧은 지연 시간으로 작동하는데요, 과거 기록을 분석해 추가적인 성능 향상 가능성을 예측합니다. 별도의 복잡한 연산 없이도 효율적인 모니터링이 가능하다는 게 장점이에요.", "evidence": "The predictor runs at millisecond latency on a single CPU thread, supporting repeated monitoring without access to LLM internals."}, {"subtitle": "비용 대비 성능 효율 입증", "desc": "연구진이 세 가지 환경과 LLM 모델을 대상으로 실험해 본 결과, GainCtrl은 기존 방식들과 비교했을 때 같은 목표 품질을 달성하면서도 더 적은 토큰을 사용했습니다. 품질 저하는 최소화하면서 비용 효율성은 높였다고 연구진은 주장했습니다.", "evidence": "Comparisons of interpolated quality-cost Pareto frontiers show that GainCtrl generally uses fewer tokens than baselines at matched target quality."}, {"subtitle": "고정 정책의 효과", "desc": "실험에서 고정된 정책을 적용했을 때도 전체 실행을 다 하는 것과 거의 비슷한 품질을 보여줬는데요, 토큰 소비량은 상당히 줄어드는 결과가 나왔습니다. 즉, 무조건 많이 실행하는 것보다 똑똑하게 멈추는 게 훨씬 경제적이라는 사실을 확인한 겁니다.", "evidence": "Fixed policies also achieve quality close to that of full execution while substantially reducing token consumption."}], "easy1_evidence": "Repeated attempts improve the quality of tool-using agents, but continued execution incurs additional costs even when it is unlikely to improve the best result ultimately returned.", "easy2_evidence": "In GainCtrl, a lightweight CPU predictor uses interaction histories to estimate expected positive gains over retained scores, which are then used to guide stopping decisions with calibrated thresholds to limit the loss in mean Best-of-N task quality.", "topic_evidence": "To address this question, we introduce GainCtrl, a gain-based execution controller for LLMs.", "limit_evidence": ""}, "2611.20711": {"points": [{"subtitle": "AgentFaultBench 평가 환경 구축", "desc": "연구진은 GitLab 환경에서 LangGraph와 CrewAI 에이전트가 도구 오류를 겪을 때 어떻게 반응하는지 평가하는 벤치마크를 설계했는데요. 단순히 내용을 생성하는 것이 아니라, 실제 파일과 이슈를 처리하는 실행 능력을 검증하는 데 초점을 맞췄다는 겁니다.", "evidence": "AgentFaultBench evaluates LangGraph and CrewAI agents performing specified tasks in an isolated GitLab installation."}, {"subtitle": "조언 제공에 따른 성공률 변화 분석", "desc": "1,944번의 실행을 통해 회복 조언이 에이전트의 성공에 미치는 영향을 측정해 봤는데요. 조언이 항상 긍정적인 결과를 가져오는 것은 아니며, 오히려 성공률이 떨어지거나 변화가 없는 경우도 확인됐다는 거예요.", "evidence": "In the primary comparison of 1,944 planned runs, advice changes success by -8.33, 0.00 and +1.06 percentage points relative to a neutral reminder; missing outcomes leave the latter two comparisons inconclusive."}, {"subtitle": "모델별 회복 정책의 효과 검증", "desc": "수정된 회복 정책을 적용해 624번의 추가 실험을 진행했더니, GPT-4o mini는 성능이 향상되었고 Sol과 Claude는 이미 회복 가능한 사례들을 성공적으로 처리했다고 밝혔는데요. 연구진은 조언이 무조건 도움이 된다고 가정하기보다 명확한 회복 제어 장치를 통해 검증해야 한다고 주장했어요.", "evidence": "The findings support testing advice against explicit recovery controls rather than assuming it helps."}], "easy1_evidence": "In the primary comparison of 1,944 planned runs, advice changes success by -8.33, 0.00 and +1.06 percentage points relative to a neutral reminder; missing outcomes leave the latter two comparisons inconclusive.", "easy2_evidence": "In a separate 624-run study on six related tasks not previously used by that policy, the guided condition records 161 correct final states and one unknown outcome in 192 planned runs, versus 142/192 with neutral feedback.", "topic_evidence": "AgentFaultBench evaluates LangGraph and CrewAI agents performing specified tasks in an isolated GitLab installation.", "limit_evidence": "No human validation was collected."}, "2611.20688": {"points": [{"subtitle": "영상 편집을 위한 시각적 도구 제공", "desc": "VIVID는 영상과 오디오를 분석하고 자막을 추출하는 도구를 제공해서 에이전트가 편집에 필요한 정보를 직접 얻게 합니다. 에이전트는 이 정보를 바탕으로 시간 좌표를 정확히 파악하고 편집 작업을 수행할 수 있거든요.", "evidence": "VIVID provides tools for on-demand video inspection, audio analysis, and transcription, and preserves observations alongside their corresponding media versions and temporal coordinates."}, {"subtitle": "에이전트의 능동적인 편집과 검증", "desc": "에이전트는 편집 중에 필요한 관찰 결과를 스스로 불러오고, 코딩 및 셸 도구를 사용해 직접 편집을 진행합니다. 편집 후에는 렌더링된 결과물을 다시 확인하면서 다음 수정 단계를 결정하는 식으로 작업이 이루어집니다.", "evidence": "Agents can actively retrieve these observations as they reason, perform edits using their native coding and shell tools, and inspect rendered outputs to guide subsequent revisions."}, {"subtitle": "다양한 모델에서의 성능 향상", "desc": "조립, 수리, 순서 편집 등 100가지 작업으로 구성된 AgenticVBench에서 Codex 모델은 VIVID를 통해 58.6%의 점수를 기록하며 기존 대비 20.2% 포인트 향상된 성과를 냈습니다. Claude Code와 OpenCode 모델에서도 각각 55.1%와 37.1%의 점수를 얻으며 성능이 크게 개선되었다고 연구진은 주장했습니다.", "evidence": "On AgenticVBench, comprising 100 tasks across Assembly, Repair, Sequencing, and Repurpose, Codex with VIVID achieves an average score of 58.6%, an improvement of 20.2 percentage points over native Codex."}], "easy1_evidence": "Video editing requires agents to make editing decisions grounded in audiovisual observations and precise temporal localization, and to evaluate their effects in rendered outputs.", "easy2_evidence": "We introduce VIVID, a visual harness that supports multiple native coding agents in video post-production without additional model training.", "topic_evidence": "These results highlight VIVID's potential as a reusable visual harness for extending the capabilities of general-purpose coding agents to video editing.", "limit_evidence": ""}, "2611.20686": {"points": [{"subtitle": "에너지 효율적인 감지", "desc": "감지 시스템은 의미 있는 소리만 골라내어 처리하는 방식을 사용하는데요, 평소에는 에너지를 아끼다가 안전에 꼭 필요한 소리가 들리면 즉시 작동하도록 설계했어요. 뭔 소리냐면, 배터리를 효율적으로 쓰면서도 중요한 순간은 놓치지 않겠다는 뜻이에요.", "evidence": "\\textit{First}, a perception-thresholded sensing mechanism enables energy-efficient always-on awareness by activating processing only for perceptually meaningful events while preserving safety-critical cues through deterministic overrides."}, {"subtitle": "신경 기호 추론 프레임워크", "desc": "사용자가 일일이 상황을 설명할 필요 없이, 기기가 스스로 소리를 이해하도록 하는 단계별 추론 방식을 도입했어요. 기기 안에서 오디오-언어 모델이 구조화된 데이터를 바탕으로 상황을 판단하게 만든 건데요, 덕분에 별도의 설명 없이도 맥락을 파악할 수 있다는 거예요.", "evidence": "\\textit{Second}, a staged neuro-symbolic reasoning framework performs promptless scenario understanding by conditioning an on-device audio-language model on structured IRs instead of user-authored context descriptions."}, {"subtitle": "개인화된 안내 업데이트", "desc": "사용자마다 다른 환경에 맞춰 안내 방식을 조정하는 기능도 넣었는데요, 기기 안에서 가볍게 의사결정 기준을 업데이트하는 방식을 사용해요. 전체적인 추론 능력은 유지하면서도 사용자 개개인의 상황에 딱 맞는 안내를 제공할 수 있다는 장점이 있어요.", "evidence": "\\textit{Third}, a bounded human-in-the-loop personalization mechanism adapts user-specific guidance through lightweight on-device decision-boundary updates while preserving population-aligned reasoning."}], "easy1_evidence": "However, existing mobile assistants largely reduce acoustic scenes to isolated labels or generic alerts, failing to provide contextual guidance when the same sound implies different risks across scenarios.", "easy2_evidence": "We present \\sysname, a mobile hearing assistant agent that closes the sensing--reasoning--action loop for \\textit{scenario-aware} and \\textit{personalized} DHH assistance.", "topic_evidence": "We present \\sysname, a mobile hearing assistant agent that closes the sensing--reasoning--action loop for \\textit{scenario-aware} and \\textit{personalized} DHH assistance.", "limit_evidence": ""}, "2611.20605": {"points": [{"subtitle": "기억의 생애 주기 관리", "desc": "기억 항목마다 유용성 점수를 매겨서 실시간으로 업데이트하는데요, 노이지-OR(noisy-OR) 보상 모델을 사용해서 기억을 얼마나 유지할지, 혹은 삭제하고 합칠지를 결정합니다. 덕분에 기억이 무한정 늘어나는 문제를 막을 수 있다는 거예요.", "evidence": "Each entry then carries a scalar utility, updated online under a noisy-OR reward model, that ranks retrieval jointly with context similarity and drives eviction and merging, giving the store a forgetting and consolidation policy instead of unbounded growth."}, {"subtitle": "행동별 보상과 평가", "desc": "행동을 하기 전 기대치를 설정하고, 행동 후에는 비평가(critic)가 실제 결과를 평가해서 보상과 성찰을 기록합니다. 환경에서 직접 보상을 받지 않아도 어떤 행동이 성공에 기여했는지 정확히 짚어낼 수 있는 셈이에요.", "evidence": "Before each action the actor commits to an expected outcome; a concurrently running critic scores the realized outcome against that expectation and writes a procedural entry carrying a binary reward and a reflection, so credit lands on the action that earned it and no environment reward is required."}, {"subtitle": "성능 향상과 투명성", "desc": "8개 도메인의 707개 과제에서 애드멤은 441개를 해결하며 리액트(ReAct)의 388개보다 높은 성능을 보였다고 주장했습니다. 모든 기억은 사람이 읽을 수 있는 텍스트로 저장되는데, 이는 오류를 진단하기 쉽다는 장점이 있지만 동시에 공격받을 수 있는 지점이 된다는 점도 언급했어요.", "evidence": "Across 707 tasks in eight AgentBoard domains AdMem solves 441 against 388 for ReAct and 312 for the workflow-induction baseline --- a pooled gain significant under a two-sided Fisher exact test, concentrated in the domains that supply transferable cross-task structure."}], "easy1_evidence": "We begin from an observation that is easy to reproduce and uncomfortable for the field: naively accumulating cross-task experience can make an agent \\emph{worse} than one with no memory at all.", "easy2_evidence": "Before each action the actor commits to an expected outcome; a concurrently running critic scores the realized outcome against that expectation and writes a procedural entry carrying a binary reward and a reflection, so credit lands on the action that earned it and no environment reward is required.", "topic_evidence": "We argue that the missing ingredients are per-action credit assignment and an explicit life cycle for stored entries, and present AdMem, which supplies both.", "limit_evidence": "All memory stays human-readable text, which is what makes the failures above diagnosable --- and, as we discuss, also makes the store an auditable but attackable surface."}, "2611.20573": {"points": [{"subtitle": "다이내믹 셰이핑의 작동 원리", "desc": "이 방법은 고정된 부품의 계산 특성을 파악하고, 작업의 기울기(gradient)를 맞춰 부품을 재배치하는 과정을 거쳐요. 인터페이스를 학습할 때는 근접 정책 최적화(PPO)를 사용하며, 부품의 원래 계수는 그대로 유지하는 방식이에요.", "evidence": "The method learns local descriptions of available computation, ranks component rebindings using task-gradient alignment, transports the current interface across a rebinding, and retains changes through behavioral feedback."}, {"subtitle": "수학적 근거와 검증", "desc": "연구진은 부품 응답의 오차와 행동 로짓(action logits)의 민감도 사이의 관계를 수학적으로 증명했어요. 이를 통해 부품을 재연결할 때 발생하는 오차를 어떻게 관리할지 명확한 근거를 마련한 거예요.", "evidence": "We derive an exact identity relating transport error in component responses and partials to changes in action logits and their sensitivities."}, {"subtitle": "게임 환경에서의 성능 평가", "desc": "ViZDoom Basic 환경에서 실험한 결과, 정답 모델이나 시연 없이도 300번의 시도 중 295번의 성공을 거뒀어요. 각 정책은 4개의 소스 조각을 실행하며, 110개의 학습된 인터페이스 값을 사용하여 작업을 수행하는 모습을 보였거든요.", "evidence": "Each policy executes four source fragments, with 110 acquired interface values and fixed random visual and action projections."}], "easy1_evidence": "We introduce Dynamic Shaping, a method for constructing executable neural arrangements through acquired response and partial-derivative interfaces over frozen pretrained components.", "easy2_evidence": "joint interface-and-binding construction succeeds on 295/300.", "topic_evidence": "The contribution is an explicit profile, rebind, transport and retain procedure and a reproducible reference-free acquisition case over frozen pretrained computation.", "limit_evidence": ""}, "2611.20569": {"points": [{"subtitle": "ToolGraph 구축", "desc": "도구 카탈로그 내의 파라미터 매칭과 개입 조사를 통해 도구 간의 의존 관계를 가중치가 있는 방향성 그래프로 만들었어요. 이 그래프는 도구 사용 에이전트가 복잡한 호출 체인을 구성할 때 필요한 정보를 제공하는 역할을 해요.", "evidence": "ToolGraph is a directed, weighted dependency graph over a tool catalog: parameter matching and interventional probes, which execute a candidate chain with and without its proposed predecessor, propose edges whose evidence is combined into an edge confidence."}, {"subtitle": "세 가지 평가 방식 비교", "desc": "연구진은 동적 계획법, GraphSAGE(그래프 신경망 모델), 그리고 그래프 정보를 활용하는 LLM 평가자 등 세 가지 방식을 실험했어요. 여기에 에이전트에게 행동과 목표에 대한 피드백을 주는 버벌라이저(verbalizer)를 더해 최종 행동을 선택하게 했거든요.", "evidence": "We study three estimators (dynamic programming over entity sets, a GraphSAGE estimator distilled from it, and an LLM scorer conditioned on graph evidence) plus a verbalizer that returns action--goal feedback to the agent, which keeps final action selection."}, {"subtitle": "실제 상태 인식의 중요성", "desc": "실험 결과, 단순히 그래프 구조만 따지는 것보다 실제 상태를 함께 읽는 LLM 평가자가 훨씬 뛰어난 성능을 보였어요. 도구 타입만으로는 잘못된 인자가 입력되는 상황을 구분할 수 없기 때문에, 구체적인 상태 정보가 결합되어야만 가치 평가가 제대로 이루어진다는 거예요.", "evidence": "Composition pays off only when the estimator also reads the concrete state: the LLM estimator improves on PageRank in every benchmark--backbone setting, by 8.3 points on average, while the two purely structural estimators fall below it, because a value defined over tool types cannot separate a correct tool called with a wrong argument."}], "easy1_evidence": "Tool-use agents must chain interdependent calls, yet which outputs satisfy which later inputs in a deployed catalog is not something a general-purpose language model reliably infers from tool descriptions alone.", "easy2_evidence": "The LLM estimator improves on PageRank in every benchmark--backbone setting, by 8.3 points on average, while the two purely structural estimators fall below it, because a value defined over tool types cannot separate a correct tool called with a wrong argument.", "topic_evidence": "We ask instead whether the same structure can supply a \\emph{multi-step} value by composing graph paths into a goal-conditioned action value \\(Q(s,a,g)\\).", "limit_evidence": "Graph construction is a one-time cost; we report it separately rather than assume it amortized away (at our scale it is comparable to request-time cost) and sweep four knobs controlling how much graph evidence to expose against success and tokens."}, "2611.20535": {"points": [{"subtitle": "VAHBench 평가 방식", "desc": "다섯 가지 짧은 드라마 제작 의뢰서를 활용해 에이전트가 계획을 세우고 제작 도구를 사용하는 능력을 평가했습니다. 단순히 영상의 품질만 보는 게 아니라 제작의 신뢰성과 보고의 정확성까지 종합적으로 확인하는 방식이에요.", "evidence": "Evaluation combines video completeness and basic quality with checks of production reliability and reporting accuracy."}, {"subtitle": "실험 결과와 한계", "desc": "48가지 설정으로 240번의 실험을 진행해 본 결과, 영상 품질 점수가 높다고 해서 의뢰 내용을 완전히 수행하는 것은 아니었습니다. 에피소드가 누락되거나 같은 영상이 반복되는 등 제작 결과물과 의뢰서 사이의 간극이 확인된 겁니다.", "evidence": "Across 240 runs covering 48 configurations of general-purpose and video-specific agents, higher quality scores do not necessarily mean more complete delivery."}, {"subtitle": "도구 활용의 효과", "desc": "영상 구성을 돕는 도구를 추가해 보기도 했는데요, 일부 에이전트에게는 도움이 되었지만 전체적으로 성능이 일관되게 좋아지지는 않았습니다. 즉, 도구만 추가한다고 해서 에이전트의 제작 능력이 자동으로 향상되는 것은 아니라는 말이에요.", "evidence": "Added composition tools help some agents but do not consistently improve performance."}], "easy1_evidence": "We ask whether they can also interpret human requests and turn them into complete videos.", "easy2_evidence": "VAHBench measures how well agents translate user intent into finished video content and helps identify where that process breaks down.", "topic_evidence": "We introduce VAHBench, a benchmark that tests this ability through five short-drama briefs specifying story, characters, dialogue and duration.", "limit_evidence": ""}, "2611.20488": {"points": [{"subtitle": "EVIDENT 벤치마크 구성", "desc": "연구진은 의미론적 근거, 문맥 추론, 시각적 근거를 포함하는 220개의 실제 웹 작업을 준비했는데요, 각 작업에는 사람이 직접 검증해야 할 근거 메타데이터를 연결해 두었습니다. 즉, 에이전트가 무엇을 보고 판단해야 하는지 기준을 명확히 세운 셈이에요.", "evidence": "EVIDENT contains 220 real-world English and Korean tasks spanning semantic grounding, contextual inference, and visual grounding, each paired with human-curated evidence metadata specifying what must be verified."}, {"subtitle": "세 가지 평가 지표 도입", "desc": "단순히 작업이 끝났는지만 보는 게 아니라, TSR, ESR, GSR이라는 세 가지 지표를 도입해서 평가를 세분화했습니다. TSR은 결과 성공 여부, ESR은 필요한 근거를 관찰했는지, GSR은 주장 수준에서 근거가 뒷받침되는지를 각각 측정하는 방식이에요.", "evidence": "We further separate surface task completion from evidence-grounded success using three metrics: TSR, ESR, and GSR, which respectively measure outcome success, required evidence observation, and claim-level evidence support."}, {"subtitle": "기존 평가 방식의 한계 확인", "desc": "상용 및 오픈소스 GUI 에이전트를 대상으로 실험해 봤더니, 겉으로 보이는 성공과 실제 근거 기반의 성공 사이에 큰 차이가 있다는 점이 확인되었습니다. 특히 문맥이나 시각적 정보가 중요한 작업에서 이런 차이가 두드러졌는데, 연구진은 기존 평가가 에이전트의 신뢰도를 과대평가할 수 있다고 주장했어요.", "evidence": "Experiments on commercial and open-source GUI agents reveal substantial gaps between surface success and evidence-grounded success, especially in contextual and visual tasks."}], "easy1_evidence": "GUI agents are increasingly evaluated by whether they complete web tasks, but surface success can hide a critical failure: the final answer may not be supported by evidence observed during navigation.", "easy2_evidence": "We introduce EVIDENT, an evidence-driven benchmark for evaluating whether GUI agents ground their decisions in observable web evidence.", "topic_evidence": "We introduce EVIDENT, an evidence-driven benchmark for evaluating whether GUI agents ground their decisions in observable web evidence.", "limit_evidence": ""}, "2611.20422": {"points": [{"subtitle": "연속성 모델링", "desc": "인공지능의 변화 과정을 상태와 수정 그래프로 모델링하고, 경로를 따라 관계를 잇는 방식을 택했어요. 이는 특정 파이프라인이나 기준에 의존하지 않고 수학적 조건만으로 결과를 도출하기 위함이에요.", "evidence": "Succession is modeled on state/modification graphs with relational lifts that compose along paths."}, {"subtitle": "네 가지 핵심 질문 구분", "desc": "그동안 혼용되어 온 연속성, 호환성, 동일성 인식, 실현 가능성이라는 네 가지 질문을 체계적으로 분리했어요. 이 과정을 통해 각 질문이 무엇을 의미하는지 명확히 정의한 겁니다.", "evidence": "Within this framework we separate four questions that are often conflated: which continuations a representation admits, which descendants are compatible with a modification, which are recognized as continuing the identity, and which are realized."}, {"subtitle": "분석의 체계화", "desc": "제안한 틀을 활용해 대칭성, 계산 복잡도, 복구 가능성, 부분 실현에 대한 견고함을 체계적으로 다룰 수 있게 됐어요. 특정 동일성 기준을 선택하기 전에 이 구조가 무엇을 결정하는지 미리 확립한 셈이에요.", "evidence": "The framework allows one to address systematically questions of symmetry, computational complexity, recoverability, and robustness to partial realization, and we establish what the structure settles in each case before any particular criterion of identity is chosen."}], "easy1_evidence": "Succession asks whether an entity encountered later is the same entity that entered an arrangement earlier.", "easy2_evidence": "Within this framework we separate four questions that are often conflated: which continuations a representation admits, which descendants are compatible with a modification, which are recognized as continuing the identity, and which are realized.", "topic_evidence": "We look for a mathematical structure weak enough to cover any such case and strong enough to support general theorems, so that results follow from the structure's conditions rather than from a particular pipeline or criterion.", "limit_evidence": ""}, "2611.20144": {"points": [{"subtitle": "기억 시스템의 책임 정의", "desc": "연구진은 기억 시스템이 단순히 작업을 돕는 것을 넘어 성능, 효율성, 보안, 프라이버시, 사용자 주권을 모두 지켜야 한다고 보았어요. 이를 위해 시스템이 갖춰야 할 행동 지침을 구체적으로 정리했거든요.", "evidence": "First, we state the responsibilities of agent memory systems as explicit behavioural desiderata spanning performance, efficiency, security, privacy, and user sovereignty."}, {"subtitle": "평가 도구와 프로토타입 개발", "desc": "HEAMS라는 벤치마크 도구를 만들고, MilaMem이라는 기억 시스템과 이를 제어하는 거버넌스 계층을 함께 개발했어요. 이렇게 하면 시스템 설계 방식에 따른 차이를 더 꼼꼼하게 따져볼 수 있거든요.", "evidence": "Third, we develop MilaMem, a prototype memory system, and a governance layer that can wrap any memory system, enabling controlled study of memory system design choices."}, {"subtitle": "성능과 보안의 상충 관계 확인", "desc": "실제로 평가해 보니 성능이 좋은 시스템이 보안이나 프라이버시 점수까지 높지는 않았어요. 기억 정책을 조정하면 정보 노출은 줄일 수 있지만, 그만큼 에이전트가 도움을 주는 능력은 낮아질 수 있다는 점을 확인한 겁니다.", "evidence": "We find that no memory system leads every performance benchmark, and strong performance scores may coexist with poor privacy, user-sovereignty, and security scores."}], "easy1_evidence": "This persistence introduces new risks: stored information can be disclosed in inappropriate contexts, resist correction or deletion, be retained beyond what users desire, or be poisoned to influence later agent behaviour.", "easy2_evidence": "We present Holistic Evaluation of Agent Memory Systems (HEAMS), an open-source framework for evaluating agent memory systems in this way.", "topic_evidence": "We argue that a memory system should instead be understood as the custodian of its user's persistent information, with responsibilities that extend beyond helping an agent complete its tasks, and that it should be evaluated holistically against all such responsibilities.", "limit_evidence": "Second, we assemble a benchmark suite that covers these desiderata and acknowledge the gaps that remain."}, "2611.20111": {"points": [{"subtitle": "HARMONIX 실험 틀 도입", "desc": "연구진은 지식 기반 의사결정을 시험하기 위해 음악 화성학을 활용한 HARMONIX라는 실험 틀을 만들었습니다. 여기서는 비터비(Viterbi) 알고리즘을 기반으로 한 최적화 방식을 사용해 네 가지 설정을 비교했거든요.", "evidence": "We introduce HARMONIX, an experimental framework using automated musical harmonization as a controlled testbed for knowledge-guided decision-making."}, {"subtitle": "데이터 기반의 성능 분석", "desc": "총 19,745개의 기록과 143,634개의 모티프 쌍을 학습 및 검증 데이터로 활용해 실험을 진행했습니다. 제약 조건을 조합했을 때 나타나는 성능 변화를 구체적인 수치로 확인한 거예요.", "evidence": "Experiments cover 19,745 records and 143,634 motif pairs across training and validation partitions."}, {"subtitle": "맥락에 따른 제약의 한계", "desc": "실험 결과, 제약 조건이 전체적인 정확도를 크게 바꾸지는 않았지만 특정 맥락에서는 시스템의 오류를 유발한다는 점을 확인했습니다. 연구진은 해석 가능한 제약이라도 상황에 따라서는 오히려 성능을 떨어뜨릴 수 있다고 주장했습니다.", "evidence": "The findings demonstrate that interpretable constraints can introduce systematic context-specific failures concealed by aggregate accuracy metrics."}], "easy1_evidence": "However, locally valid decisions do not necessarily preserve contextual relationships in human decision-making.", "easy2_evidence": "Combined constraints improve reference root-interval agreement by approximately five percentage points in stable structural contexts but reduce it by nearly nine percentage points in contexts involving transposition tracking.", "topic_evidence": "This paper examines when structural constraints improve or degrade agreement with human reference solutions.", "limit_evidence": "Contexts are identified retrospectively using reference annotations; no adaptive constraint-selection mechanism is evaluated."}, "2611.19530": {"points": [{"subtitle": "rta-bench-1 벤치마크 설계", "desc": "연구진은 상승장, 하락장, 폭락장을 포함한 3개의 미국 시장에서 뉴스 공개 시점을 분 단위로 엄격히 반영하는 rta-bench-1을 구축했어요. 미래 정보를 미리 참조하는 오류를 방지하고, 모든 결정을 같은 날 같은 섹터의 무작위 선택과 비교하도록 설계했거든요.", "evidence": "It shows each headline only after its publication minute, plays each period blind and named, and checks every run for look-ahead."}, {"subtitle": "에이전트 성능 분석 결과", "desc": "실험 결과, 에이전트가 얻은 수익의 중앙값 78%는 시장 및 스타일 노출에 의한 것이었으며 유의미한 알파는 없었다고 연구진은 주장했어요. 에이전트가 긍정적인 뉴스가 많은 주식을 매수하긴 했지만, 뉴스 데이터를 제거한 실험에서도 비슷한 수익을 냈다는 점이 이를 뒷받침합니다.", "evidence": "The agents bought the stocks with the most positive news, yet in ablations they earned as much without their headlines."}, {"subtitle": "규칙 준수 능력 확인", "desc": "수익 창출 능력과는 별개로, 에이전트가 프롬프트에 주어진 규칙을 얼마나 잘 따르는지는 확인했는데요. 현금 보유 규칙을 추가했더니 GPT 기반 에이전트의 주식 비중이 모든 실험 쌍에서 30.3포인트 감소하는 등 규칙을 안정적으로 수행하는 모습을 보였습니다.", "evidence": "Still, the agents carried out rules reliably, since a single cash rule in the prompt cut a GPT-based agent's share in stocks by 30.3 points in all six pairs."}], "easy1_evidence": "In our study, two runs of the same model that differed only in the random seed ended 5.2 points apart on average, so telling skill from luck takes many backtests across markets, models and seeds.", "easy2_evidence": "In 91 runs of six models from four vendors, no alpha was significant, market and style exposure accounted for a median 78% of the return, and the decisions did no better than random stocks of the same sector.", "topic_evidence": "In this paper, we present rta-bench-1, a backtest over three US markets (a rally, a bear market and a crash).", "limit_evidence": "Builders should therefore supply the edge themselves and report exposures and alpha, and benchmarks should replay news by publication time."}, "2611.19529": {"points": [{"subtitle": "경량화된 신경망 설계", "desc": "이 수신기는 64차원 표현을 공유하는 두 개의 초경량 백본을 사용하는데요. 텐서플로우 라이트 마이크로 펌웨어로 구현되어 240MHz 마이크로컨트롤러에서 16.9ms 만에 버스트를 처리할 수 있습니다.", "evidence": "Both ship as int8 TensorFlow Lite Micro firmware; the Conv1D receiver decides a burst in $16.9$ ms on a $240$ MHz microcontroller with $24.2$ KiB of activations, a measured energy of $2.2$-$3.4$ mJ per burst, and float-equivalent decisions, sustaining up to $59$ bit/s of telemetry or a $7.4$ Hz range track."}, {"subtitle": "향상된 장애물 탐지 성능", "desc": "연구진이 개발한 감지 헤드는 드론이 많은 환경에서 장애물을 66.8%의 확률로 식별해 냈는데요. 이는 기존의 매칭 필터 방식이나 OFDM-ISAC 방식보다 훨씬 높은 수치라는 게 연구진의 주장입니다.", "evidence": "Its sensing head identifies true obstacles in $66.8$ of peer-laden bursts (vs $42$ matched filtering, $44$ OFDM-ISAC, $48$ peak-picker ceiling)."}, {"subtitle": "재밍 환경에서의 강인성", "desc": "3GPP 채널 환경에서 통신 오류율을 크게 낮출 수 있고, 재밍을 인식해 학습하는 방식으로 통신 연결을 복구할 수 있는데요. 주파수 가변성을 활용해 부분 대역 재밍에 대해서도 6~9dB의 마진을 확보했다고 밝혔습니다.", "evidence": "In-domain refitting recovers telemetry BER by up to three orders of magnitude under 3GPP channels, jamming-aware training restores the link, and frequency agility adds a $6$--$9$ dB margin against partial-band jamming."}], "easy1_evidence": "The Internet of Drones (IoD) needs secure telemetry and proximity sensing within the SWaP-C constraints.", "easy2_evidence": "We show that a single blind neural receiver driven by one chaos-based waveform performs both functions without a separate radar transceiver.", "topic_evidence": "Ultra-CAN pairs a shared $64$-dimensional representation with two ultra-light backbones, an attention-pooled Conv1D network and a multi-head QKV network ($27.6$k--$44.2$k parameters), feeding communication and sensing heads.", "limit_evidence": ""}, "2611.19385": {"points": [{"subtitle": "도시 풍동 시뮬레이션 벤치마크 구축", "desc": "연구진은 10개의 공학 작업군으로 구성된 200개의 작업과 367개의 사례를 포함하는 '어반윈드-에이전트벤치(UrbanWind-AgentBench)'를 만들었는데요, 여기에는 작업의 변수와 고정 조건, 수치적 임계값 등이 명시되어 있어요. 이 벤치마크는 결과물의 구조적 점수와 독립적인 재계산을 통한 수치적 점수를 이중으로 평가하도록 설계됐거든요.", "evidence": "UrbanWind-AgentBench, comprising 200 tasks and 367 cases in 10 engineering task families, was constructed."}, {"subtitle": "윈드파일럿 프레임워크의 성능 개선", "desc": "윈드파일럿을 적용해 30개의 오픈폼(OpenFOAM) 작업을 수행해 봤더니, 수치적 신뢰도를 얻은 작업이 17개로 늘어났고 만점을 받은 작업도 3개로 증가했어요. 평균 작업 점수도 62.5점에서 72.5점으로 올랐는데, 대기 경계층(ABL) 작업에서는 평균 18.5점이 상승하는 효과를 보였거든요.", "evidence": "With the same model name and budget, WindPilot increased the number of tasks with numerical credit to 17, full-score tasks from 0 to 3 and the mean task score from 62.5 to 72.5."}, {"subtitle": "효율성 측면의 변화", "desc": "성능뿐만 아니라 효율성도 좋아졌는데요, 평균 작업 단계는 130.4단계에서 104.9단계로 줄었고 토큰 소비량도 12.9% 감소했어요. 검증 과정을 추가했음에도 불구하고 전체적인 작업 효율이 개선됐다는 점이 특징이에요.", "evidence": "Mean action steps fell from 130.4 to 104.9, and mean token consumption decreased by 12.9%."}], "easy1_evidence": "AI agents based on large language models (LLMs) can now configure and run computational fluid dynamics (CFD) solvers, but a completed run does not ensure that delivered metrics can be recomputed from raw outputs.", "easy2_evidence": "WindPilot was then proposed as an execution framework that incorporates contract parsing, execution provenance, deterministic verification and bounded acceptance review into the LLM execution loop.", "topic_evidence": "A completed simulation run is therefore not sufficient for a usable urban wind result; usability depends on checks that tie reported metrics to raw evidence during execution.", "limit_evidence": ""}, "2611.19299": {"points": [{"subtitle": "단계별 의미 증류 기법", "desc": "고정된 인코더를 활용해 교사 모델의 출력을 1024차원 벡터로 변환하고, 단계별로 태그를 붙여 학생 모델이 이를 학습하도록 설계했어요. 이 방식은 구조화되지 않은 의미 정보를 효과적으로 보존하면서도 언어 모델 호출을 완전히 없애는 구조예요.", "evidence": "A frozen encoder maps each teacher output to a 1024-d vector; the student sees typed stage-tagged vectors with stage-specific visibility, is jointly supervised, and trains with scheduled self-history."}, {"subtitle": "연산 효율성과 성능 검증", "desc": "13.2M 파라미터 규모의 학생 모델을 8GB GPU에서 1,658초 만에 학습시켰는데요, 실행 시에는 텍스트 생성 과정 없이 결정당 0.14ms만 소요됩니다. 교사 모델과 비교했을 때 코사인 유사도가 0.943으로 나타나, 정보 전달 채널이 잘 보존되고 있음을 확인했다는 거예요.", "evidence": "One TwinMarket trace yields a 13.2M-parameter deterministic student that trains in 1,658 seconds on one 8-GB GPU and runs with zero teacher or decoder calls and no text generation (0.14 ms per decision)."}, {"subtitle": "시뮬레이션 가속 효과", "desc": "200,000번의 결정을 내리는 시뮬레이션을 수행할 때, 교사 모델은 3시간이 걸리지만 제안한 모델은 단 12분 만에 끝낼 수 있어요. 언어 모델 호출을 전혀 하지 않으면서도 교사 모델의 성능을 상당 부분 유지한다는 점에서 효율적인 대안이 될 수 있다는 겁니다.", "evidence": "A 20-seed, 200,000-decision sweep takes 12 minutes with zero LLM calls, versus three hours for the teacher."}], "easy1_evidence": "Staged LLM agents make market and social simulators realistic, but one 102-day run of a 200-agent, ten-index market simulator issues 203,100 language-model calls and returns one realization.", "easy2_evidence": "We present staged semantic distillation, a low-compute method that preserves non-structured semantics in a non-LLM student trained from one recorded trace.", "topic_evidence": "We present staged semantic distillation, a low-compute method that preserves non-structured semantics in a non-LLM student trained from one recorded trace.", "limit_evidence": "The paper is a method-and-case-study contribution on one simulator and trace."}, "2611.19227": {"points": [{"subtitle": "기억 업데이트 평가 방식", "desc": "연구진은 40억 개의 매개변수를 가진 언어 모델을 고정해 두고, 로라(LoRA)라는 기술을 써서 기억을 업데이트하는 실험을 설계했어요. 7가지 준비 조건과 6가지 업데이트 예산을 조합해서 AI가 새로운 사실을 얼마나 잘 배우고 기존 지식을 얼마나 잘 지키는지 측정했거든요.", "evidence": "Using a frozen 4B language model with late-layer LoRA, we evaluate seven preparation conditions and six update budgets on four-field synthetic semantic configurations."}, {"subtitle": "학습 예산에 따른 성능 변화", "desc": "업데이트 예산을 8번에서 32번으로 늘렸을 때, AI의 성공률이 6.25%에서 최대 94.79%까지 크게 올랐다는 점을 확인했어요. 특히 예산이 적을 때는 옛날 정보를 그대로 출력하는 실수가 잦았는데, 학습을 반복할수록 이런 오류가 사라지는 모습을 보였거든요.", "evidence": "In two exposure-matched history conditions, increasing the budget from eight to 32 updates raises joint success from 6.25% to 94.79% and 91.15%, respectively, while exact obsolete-value outputs fall from 174/192 and 166/192 to zero."}, {"subtitle": "반복 학습의 효과와 한계", "desc": "변하지 않는 정보를 반복해서 학습시키는 방식인 'Constant32'도 테스트해 봤는데요. 초기에는 성공률이 높았지만, 결과적으로는 환경 변화에 맞춰 학습한 방식보다 최종 성능이 낮게 나타났거든요. 즉, 새로운 사실을 배우는 과정에서 기존 지식과의 균형을 맞추는 게 중요하다는 걸 보여준 겁니다.", "evidence": "Constant32, which matches preparation steps but repeatedly trains on unchanged content during the first 32 events, achieves higher early joint success at eight steps (53.65%); at 32 steps, it reaches 85.42%, below both changing-history conditions."}], "easy1_evidence": "Physical AI systems therefore need to incorporate new facts into scene memory while preserving valid information about equipment, objects, and operating constraints.", "easy2_evidence": "In two exposure-matched history conditions, increasing the budget from eight to 32 updates raises joint success from 6.25% to 94.79% and 91.15%, respectively, while exact obsolete-value outputs fall from 174/192 and 166/192 to zero.", "topic_evidence": "We study updates to this parametric semantic-memory layer and present a joint evaluation of correction and preservation under finite update budgets.", "limit_evidence": ""}, "2611.19215": {"points": [{"subtitle": "공정성 제어 방식", "desc": "영상 생성 과정에서 나오는 결과물을 피드백으로 삼아, 각 개념별로 설정된 공정성 목표에서 얼마나 벗어났는지 계산합니다. 이를 바탕으로 프롬프트 수준에서 속성을 개입시켜 편향을 바로잡는 방식이에요.", "evidence": "Using generated videos at inference time as feedback, Mem2Fair selects prompt-level attribute interventions based on the deviation from each concept's prescribed fairness target, without training or separate pre-deployment sampling."}, {"subtitle": "성능 검증 결과", "desc": "다양한 인구 통계적 속성과 프롬프트 설정에서 기존 모델 및 다른 방식들과 비교해 봤는데요, 공정성은 꾸준히 개선되면서도 영상의 품질이나 텍스트와의 일치도는 기존과 비슷하게 유지했다고 연구진은 밝혔습니다.", "evidence": "Experiments demonstrate that Mem2Fair consistently improves fairness over the unmodified generator and existing baselines across multiple demographic attributes, prompt settings, and target distributions, while maintaining comparable prompt-video alignment and video quality."}, {"subtitle": "상용 모델 적용", "desc": "연구진은 이 방법이 내부 구조를 알 수 없는 상용 블랙박스 모델에서도 효과적으로 작동한다는 점을 입증했어요. 별도의 학습 없이도 공정성을 높일 수 있다는 게 큰 장점입니다.", "evidence": "We further demonstrate its effectiveness on commercial black-box T2V models."}], "easy1_evidence": "Text-to-video (T2V) generation models can produce systematically unfair demographic outcomes when prompts leave protected attributes unspecified.", "easy2_evidence": "Building on this formulation, we introduce Mem2Fair, a plug-and-play framework that maintains concept-conditioned Fair Memory.", "topic_evidence": "We present the first conditional online approachability formulation of attribute-level fairness for T2V generation.", "limit_evidence": ""}, "2611.19214": {"points": [{"subtitle": "전략 계획 및 설정 선택", "desc": "STaSBO는 전략 계획과 전략 기반 설정 선택이라는 두 단계로 나뉘어 작동하는데요, 구조화된 메모리 시스템을 통해 이전의 계획과 선택을 현재의 최적화 상태와 연결해요. 이를 통해 최적화 도중에도 자신의 행동 계획을 수정할 수 있는 능력을 갖췄습니다.", "evidence": "STaSBO comprises two coordinated stages: strategy planning and strategy-guided configuration selection."}, {"subtitle": "후보군 탐색 및 최적화", "desc": "방대한 설정 공간을 효율적으로 다루기 위해 대리 모델의 적합성 증거를 바탕으로 후보 설정을 먼저 추려내는데요, 이후 최적화 행동을 진단하여 최종적으로 어떤 설정을 선택할지 결정하게 됩니다.", "evidence": "To navigate the large joint configuration space, the selection stage shortlists configurations using surrogate fit evidence."}, {"subtitle": "성능 평가 결과", "desc": "12개의 수학적 과제와 10개의 과학 및 공학 응용 과제에서 테스트해 봤더니, 기존의 가장 강력한 모델보다 훨씬 높은 순위를 기록했어요. 구체적으로는 평균 순위가 수학 과제에서 2.17, 응용 과제에서 2.60으로 나타나 기존 모델들의 4.08, 4.10보다 우수했다고 연구진은 밝혔습니다.", "evidence": "Across 12 synthetic mathematical and 10 scientific and engineering application tasks, STaSBO achieves the best average rank against 11 baselines: 2.17 and 2.60, compared with 4.08 and 4.10 for the strongest baseline in each suite, respectively."}], "easy1_evidence": "Bayesian optimization (BO) enables sample-efficient search for expensive black-box problems, but its performance depends strongly on surrogate-acquisition configurations whose suitability varies across problems and optimization states.", "easy2_evidence": "We take a significant step toward LLM-driven strategic management of BO with STaSBO, a task-agnostic meta-controller that plans search behavior and jointly selects surrogate-acquisition configurations, while numerical BO retains responsibility for probabilistic modeling and candidate generation.", "topic_evidence": "We take a significant step toward LLM-driven strategic management of BO with STaSBO, a task-agnostic meta-controller that plans search behavior and jointly selects surrogate-acquisition configurations, while numerical BO retains responsibility for probabilistic modeling and candidate generation.", "limit_evidence": ""}, "2611.19166": {"points": [{"subtitle": "문헌 내 정보 불균형 측정", "desc": "PrimeKG에 등록된 574개 약물을 대상으로 위키피디아와 펍메드 초록을 분석해 효능과 금기 사항의 언급 빈도를 비교했습니다. 그 결과 효능이 금기 사항보다 두 배가량 더 자주 나타나는 비대칭적인 구조를 확인했거든요.", "evidence": "In this paper, we measure how often these texts contain both facts across 574 drugs from PrimeKG by comparing a drug's indications against its own contraindications."}, {"subtitle": "언어 모델의 학습 결과", "desc": "Qwen2.5 모델의 크기를 0.5B에서 14B까지 키우며 성능을 측정해 봤는데요, 효능에 대한 정확도는 18.3점 향상되었지만 금기 사항에 대한 정확도는 여전히 낮은 수준에 머물렀습니다. 이는 모델이 학습한 일반 텍스트 데이터에 안전 관련 정보가 부족하기 때문이라고 연구진은 주장했습니다.", "evidence": "As we scale Qwen2.5 from 0.5B to 14B, accuracy on indications rises by 18.3 points, whereas accuracy on contraindications remains flat near random guessing."}, {"subtitle": "임상 AI 시스템의 개선 방향", "desc": "연구진은 AI가 약물 안전 질문을 받았을 때 일반적인 기록에 의존하지 말고 FDA 공식 라벨이나 구조화된 데이터베이스를 활용하도록 경로를 설정해야 한다고 제안했습니다. 실제로 공식 라벨을 참조하게 했더니 정확도가 15.8점 높아지는 결과를 보였거든요.", "evidence": "Clinical AI systems should therefore route medication-safety questions to official regulatory labels and structured databases rather than relying on general public records."}], "easy1_evidence": "Across Wikipedia articles and PubMed abstracts, we find that reference prose names a drug's benefits about twice as often as its safety limits (within-drug odds ratio 2.19).", "easy2_evidence": "Overall, our findings show that models fail on medication safety not because they cannot reason about risk, but because free-text corpora lack safety facts.", "topic_evidence": "In this paper, we measure how often these texts contain both facts across 574 drugs from PrimeKG by comparing a drug's indications against its own contraindications.", "limit_evidence": ""}, "2611.19157": {"points": [{"subtitle": "템플릿 기반 기술 선택", "desc": "템플릿 파서가 각 기관의 요구 사항을 읽어 들여서 제안서 작성 단계마다 적절한 기술을 골라내는 방식이에요. 덕분에 생성 로직을 일일이 수정하지 않아도 다양한 기관의 양식을 모두 맞출 수 있다는 장점이 있거든요.", "evidence": "We introduce FundingClaw, a multi-agent framework built on template-driven skill selection, where a Template Parser ingests any agency's specification and selects the appropriate writing skills for each stage, so that one research brief can produce compliant proposals for NSFC, NSF, KAKENHI, or ERC without modifying generation logic."}, {"subtitle": "구조적 초안 작성 전략", "desc": "본문을 본격적으로 쓰기 전에 청사진과 뼈대를 먼저 잡는 전략을 사용하는데요. 이렇게 하면 긴 글을 쓸 때 내용이 주제에서 벗어나는 현상을 막을 수 있다는 게 연구진의 설명이에요.", "evidence": "A blueprint-skeleton strategy drafts a structured outline before any prose is written, mitigating the semantic drift that plagues long-form generation."}, {"subtitle": "다단계 검증 및 성능 평가", "desc": "연구 배경, 내용, 기반을 순차적으로 작성하고 연구자의 실적을 다중 소스로 검증하는 과정을 거치거든요. 10가지 연구 주제를 8개 항목으로 평가해 봤더니, 기존 방식보다 성능이 뛰어나고 사람이 쓴 제안서와의 격차도 좁혔다고 연구진은 밝혔어요.", "evidence": "Evaluated on ten research topics with an eight-dimension rubric, FundingClaw outperforms the baseline, narrowing the gap with human level for laborious funding proposal."}], "easy1_evidence": "Grant proposal writing remains a manual, labor-intensive bottleneck: proposals must satisfy rigid, agency-specific templates, and the same intellectual content must be repeatedly re-encoded into incompatible formats across funding organizations.", "easy2_evidence": "We introduce FundingClaw, a multi-agent framework built on template-driven skill selection, where a Template Parser ingests any agency's specification and selects the appropriate writing skills for each stage, so that one research brief can produce compliant proposals for NSFC, NSF, KAKENHI, or ERC without modifying generation logic.", "topic_evidence": "We introduce FundingClaw, a multi-agent framework built on template-driven skill selection, where a Template Parser ingests any agency's specification and selects the appropriate writing skills for each stage, so that one research brief can produce compliant proposals for NSFC, NSF, KAKENHI, or ERC without modifying generation logic.", "limit_evidence": "The code will be released upon acceptance."}, "2611.19111": {"points": [{"subtitle": "생성형 에이전트 시뮬레이션", "desc": "PIAAC 조사에 참여한 성인들의 데이터를 가중치로 반영해 3,200개의 생성형 에이전트를 만들었습니다. 이들에게 20가지 정책을 제시하고 각 정책에 대한 평가와 그 이유를 수집한 뒤, 서로 다른 의견을 가진 에이전트들끼리 대화를 나누게 해서 그 결과를 분석했어요.", "evidence": "We built 3,200 generative agents from a weighted sample of the Programme for the International Assessment of Adult Competencies (PIAAC) Cycle 2 respondents, collected their ratings and explanations for 20 policies, and analyzed dialogues between agents with contrasting ratings."}, {"subtitle": "정책 지지와 실질적 혜택의 격차", "desc": "분석 결과 에이전트들은 정책의 취지에는 대부분 찬성했지만, 정작 본인의 AI 문해력이 향상되거나 개인적인 이득을 얻을 것이라는 확신은 낮게 나타났습니다. 디지털 기기 사용 경험이 적을수록 이런 격차는 더 크게 벌어지는 경향을 보였거든요.", "evidence": "The agents supported nearly every policy but were far less confident that they would improve adult AI literacy or benefit them personally."}, {"subtitle": "조건부 지지의 원인 파악", "desc": "에이전트들은 정책을 지지하면서도 참여 비용이나 권리 행사의 어려움, 지역사회의 통제권 부족 등을 문제로 지적했습니다. 연구진은 에이전트들이 대화를 통해 의견 차이를 좁히기보다는 이러한 구체적인 이행 조건을 제시하는 데 집중했다고 설명했어요.", "evidence": "Agents traced the gap to participation costs, hard-to-exercise rights, and limited community control, and their dialogues specified these conditions rather than resolving disagreement."}], "easy1_evidence": "Canada's 2026 national AI strategy, AI for All, commits to free AI training for everyone and to expanding business AI adoption, yet it is difficult to anticipate whether these policies will reach adults with uneven skills and circumstances.", "easy2_evidence": "We describe this pattern as conditional endorsement and argue that AI literacy policy should be designed and evaluated for adults with the fewest digital skills.", "topic_evidence": "We ask how adults with diverse skills might rate these policies on support, effectiveness, and personal benefit, how their skills and circumstances shape these evaluations, and what implementation conditions they raise.", "limit_evidence": ""}, "2611.19110": {"points": [{"subtitle": "자연어 기반 관심사 관리", "desc": "추천 시스템이 추론한 사용자의 관심사를 사람이 읽을 수 있는 자연어로 변환하고, 이를 사용자가 직접 수정할 수 있는 계층을 도입했습니다. 사용자가 관심사를 추가하거나 삭제하면 시스템이 이를 권위 있는 정보로 받아들여 추천에 반영하는 방식이에요.", "evidence": "CLEAR makes a ranked subset of inferred interests readable and stores accepted additions and suppressions as authoritative preference state."}, {"subtitle": "추천 성능 및 정확도 검증", "desc": "오프라인 벤치마크 평가에서 연구진이 개발한 3B 생성 모델은 0.3967의 F1 점수를 기록하며 기존 모델인 0.1911이나 제미나이(Gemini) 2.5 Pro의 0.3633보다 높은 성능을 보였습니다. 실제 사용자들도 시스템이 보여준 관심사의 88.5%가 정확하다고 평가했거든요.", "evidence": "In an offline benchmark using a shared evaluation protocol, the Specialized 3B generator reached 0.3967 mean-user F1@10, compared with 0.3633 for Gemini 2.5 Pro and 0.1911 for the prior generator."}, {"subtitle": "실제 서비스 적용 사례", "desc": "이 시스템은 이미 1년 넘게 인스타그램과 페이스북의 네 가지 서비스 영역에서 실제로 운영되고 있습니다. 사용자가 자신의 관심사를 직접 들여다보고 수정하며 추천 결과를 능동적으로 조절할 수 있는 환경을 제공한다는 점이 특징이에요.", "evidence": "CLEAR components have operated in production for over one year; the system spans four surfaces on Instagram and Facebook, with an interest layer people can inspect, correct, and use to direct recommendations."}], "easy1_evidence": "Modern recommenders keep learned preferences in representations people cannot inspect or change.", "easy2_evidence": "Direct user review found that users rated about 88.5% of displayed interests accurate.", "topic_evidence": "We present CLEAR (Controllable and Legible End-to-end Architecture for Recommendation), an end-to-end system deployed at Meta and built around an editable natural-language interest layer.", "limit_evidence": ""}, "2611.19082": {"points": [{"subtitle": "데이터 구성 및 모델 설계", "desc": "런던 대학 병원(UCLH)에서 확보한 6,022건의 MRI 사례를 바탕으로 연구를 진행했는데요, 이 중 4,834건은 내부 테스트용으로 따로 떼어 두었습니다. 기존의 영상 전용 모델은 고정해 두고, 여기에 43개의 임상 변수를 결합하는 방식을 취했어요.", "evidence": "The study cohort comprises 6,022 biparametric MRI cases from 4,540 patients at University College London Hospitals NHS Foundation Trust (2019-2024), of which 4,834 cases (3,632 patients) are held out for internal testing."}, {"subtitle": "성능 평가 지표", "desc": "주요 평가 지표는 영상만 사용한 모델과 임상 정보를 결합한 모델 사이의 AUROC(수신자 조작 특성 곡선 아래 면적) 차이를 측정하는 거예요. 이 지표를 통해 임상 정보가 진단 정확도를 얼마나 높이는지 확인하려는 겁니다.", "evidence": "The primary endpoint is the difference in the area under the receiver operating characteristic curve (AUROC) between the image-context and image-only models on the internal test set."}, {"subtitle": "외부 검증 및 다각도 분석", "desc": "내부 테스트뿐만 아니라 5개의 외부 데이터셋을 활용해 모델의 성능을 추가로 검증할 계획인데요, 변수 결합 전략이나 개별 변수의 기여도, 그리고 하위 그룹별 성능 차이까지 상세히 비교할 예정입니다.", "evidence": "All models are further tested on five external cohorts from primary diagnosis and population-based screening."}], "easy1_evidence": "The objective of this study is to investigate the role of clinical variables - their breadth, source, and quality - in the development, utility, and generalisability of an AI system for bi-parametric MRI (bpMRI)-based diagnosis of clinically significant prostate cancer (csPCa).", "easy2_evidence": "Clinical context is added to the published PI-CAI-2B image-only model, whose weights are fixed.", "topic_evidence": "The objective of this study is to investigate the role of clinical variables - their breadth, source, and quality - in the development, utility, and generalisability of an AI system for bi-parametric MRI (bpMRI)-based diagnosis of clinically significant prostate cancer (csPCa).", "limit_evidence": ""}, "2611.19064": {"points": [{"subtitle": "파레토 지배 활용", "desc": "파레토 지배를 통해 여러 검사 결과 중 서로 모순되지 않으면서 더 많은 요구사항을 만족하는 답안들을 식별해 냅니다. 뭔 소리냐면, 어떤 답안이 다른 답안보다 더 많은 조건을 충족하면 이를 더 우월한 것으로 판단한다는 거예요.", "evidence": "Pareto dominance identifies responses that satisfy additional requirements without losing any already satisfied, while leaving responses with conflicting outcomes incomparable."}, {"subtitle": "POLPO 학습 방식", "desc": "직접 선호 최적화(DPO)의 리스트 방식 가능도를 확장해서, 부분적인 순서와 일치하는 모든 완전한 순위의 확률을 최대화하는 방식으로 학습합니다. 이렇게 하면 정답이 완성되기 전 단계에서도 검증된 개선 사항들을 학습에 반영할 수 있거든요.", "evidence": "POLPO extends the listwise likelihood underlying Direct Preference Optimization by maximizing the total probability of all complete rankings consistent with these partial orders."}, {"subtitle": "성능 개선 확인", "desc": "코드 생성과 지시 이행 작업에서 실험해 봤더니, 기존의 점수 기반 학습보다 학습 효율이 좋아지고 모든 요구사항을 만족하는 비율도 더 높아졌습니다. 연구진은 이 결과가 여러 검사관의 피드백을 활용하는 효과적인 방법임을 보여준다고 주장했어요.", "evidence": "Experiments on code generation and instruction following demonstrate improved learning efficiency and higher rates of complete requirement satisfaction compared with scalar-reward training."}], "easy1_evidence": "Rewarding only complete success discards distinctions among partial solutions, while counts and weighted sums impose comparisons between responses that satisfy different subsets of requirements.", "easy2_evidence": "We introduce Partial-Order Likelihood Policy Optimization (POLPO), which learns from the comparisons established by verification without first constructing an aggregate reward.", "topic_evidence": "We introduce Partial-Order Likelihood Policy Optimization (POLPO), which learns from the comparisons established by verification without first constructing an aggregate reward.", "limit_evidence": ""}, "2611.19061": {"points": [{"subtitle": "인프라 생애주기 분류", "desc": "가속기 설계부터 커널 엔지니어링, 컴파일, 배포, 운영, 데이터 관리, 에너지 최적화까지 인프라의 전체 과정을 포괄했습니다. 각 단계에서 LLM이 어떤 역할을 하는지 체계적으로 정리한 것이 특징이에요.", "evidence": "We present a comprehensive survey of LLM-assisted AI infrastructure across its lifecycle, from accelerator design and kernel engineering to compilation, deployment, operations, data management, and energy optimization."}, {"subtitle": "정량적 결과 통합 분석", "desc": "연구마다 사용하는 벤치마크나 하드웨어가 달라서, 평가 조건이 맞는 경우에 한해 기능적 정확도나 처리량, 에너지 소비 같은 공통 지표로 결과를 비교했습니다. 결과를 하나의 점수로 뭉뚱그리지 않고 각 연구의 고유한 지표를 유지하며 분석했다는 점이 중요해요.", "evidence": "Because studies adopt heterogeneous benchmarks, baselines, hardware, and metrics, we compare methods only where evaluation conditions permit and align results along common dimensions: functional correctness, execution performance, throughput, resource and energy consumption, operational outcomes, and optimization cost, keeping each result's native metric, baseline, and setting rather than collapsing them into a single score."}, {"subtitle": "성능 향상과 한계점 도출", "desc": "분석을 통해 LLM 기반 방식이 일관된 성능 향상을 보이는 영역을 확인했는데요. 동시에 작업 조정 분야에서 보고된 성과가 시뮬레이터 환경인지 실제 클러스터 환경인지에 따라 어떻게 달라지는지도 밝혀냈습니다.", "evidence": "This comparison reveals where LLM-driven methods yield consistent gains, how reported gains in workload orchestration depend on the evaluation environment, from simulators to real clusters and production, and where evidence is still lacking."}], "easy1_evidence": "Large language models (LLMs) are increasingly used to design, optimize, and operate the infrastructure behind AI training and serving, yet the literature remains fragmented across hardware design, machine learning systems, electronic design automation, and high-performance computing.", "easy2_evidence": "We organize the literature by the primary resource the LLM manages: artifact-centric methods for computational artifacts, operational-centric methods for deployment context and system state, and resource-centric methods for data and energy.", "topic_evidence": "We present a comprehensive survey of LLM-assisted AI infrastructure across its lifecycle, from accelerator design and kernel engineering to compilation, deployment, operations, data management, and energy optimization.", "limit_evidence": "This comparison reveals where LLM-driven methods yield consistent gains, how reported gains in workload orchestration depend on the evaluation environment, from simulators to real clusters and production, and where evidence is still lacking."}, "2611.18981": {"points": [{"subtitle": "GPBam 벤치마크 구축", "desc": "연구진은 독일 국가 시험 준비 과정에서 가져온 81개의 공법 사례와 200개의 법 조항 암기 과제를 결합해 GPBam을 만들었습니다. 이 데이터는 공개된 적이 없어 모델이 답을 미리 외우고 있을 가능성을 차단했다는 점이 특징이에요.", "evidence": "Drawn from state examination preparation, the cases are broad and rarely repeat, and are not publicly available - we find no evidence of exact-solution memorisation in the models we evaluate, and keeping them private limits contamination."}, {"subtitle": "검색과 생성의 통합 평가", "desc": "모범 답안에 인용된 법 조항을 검색의 정답지로 활용하여, AI가 법 조항을 잘 찾아내는지와 그 내용을 바탕으로 에세이를 얼마나 잘 쓰는지 두 가지를 동시에 평가했습니다. 이를 통해 법률 의견서 작성에 검색 품질이 실제로 얼마나 중요한지 따져볼 수 있게 된 겁니다.", "evidence": "Because each reference solution's cited norms form a retrieval gold set over the very instances the essays are graded on, GPBam scores retrieval and long-form generation jointly, which makes it a benchmark for legal retrieval as well as for legal writing and lets us ask how much retrieval quality a legal opinion actually needs."}, {"subtitle": "모델 성능 분석 결과", "desc": "32개의 모델을 평가한 결과 점수는 4.81점에서 76.42점까지 넓게 분포했는데요, 법 조항을 검색해서 넣어줘도 점수 향상은 미미했습니다. 연구진은 에세이의 품질이 모델이 법 조항을 얼마나 정확히 기억하고 있는지와 밀접하게 연결되어 있다고 주장했습니다.", "evidence": "Essay quality strongly tracks prior knowledge: verbatim statute recall, measured in a separate task, correlates at ρ= 0.92 over 32 models."}], "easy1_evidence": "Legal reasoning in civil-law systems is not rule-lookup: the German state examination asks for a structured opinion (Gutachten) that names the governing norms, applies them to the facts, and argues to a conclusion.", "easy2_evidence": "Supplying the law helps modestly: across seven models and eight retrieval configurations, retrieval performance varies nearly threefold and buys at most 4.1 essay points, and nothing significant for three of the seven, while an oracle with 91% gold-norm recall improves scores by 2-6 points.", "topic_evidence": "We introduce GPBam (German Public Law Bar-style Exam), 81 public-law examination cases with reference solutions, paired with a recitation task over 200 statutory provisions.", "limit_evidence": ""}, "2611.18958": {"points": [{"subtitle": "이중 단계 통합 프레임워크", "desc": "수신기는 채널 신뢰도를 바탕으로 어휘 수준의 채널 사후 확률을 구성합니다. 이를 통해 모델이 어떤 토큰이 신뢰할 수 없는지 스스로 판단하게 만드는 거예요.", "evidence": "In the proposed framework, the receiver detects unreliable token positions from channel reliability and constructs a vocabulary-level channel-posterior."}, {"subtitle": "PWE와 AOF를 통한 복구", "desc": "입력 단계의 PWE는 사후 확률을 임베딩에 주입하고, 출력 단계의 AOF는 채널 적응형 가중치를 사용해 로짓을 융합합니다. 결과적으로 재전송이나 추가적인 모델 학습 없이도 효율적인 복구가 가능해집니다.", "evidence": "In particular, within the receiver, Posterior-Weighted Input Embedding (PWE) injects this posterior into the MLM input, while Adaptive Output Logit Fusion (AOF) reuses it at the output with a channel-adaptive weight."}, {"subtitle": "성능 개선 효과", "desc": "실험 결과, 기존의 문맥 기반 복구 방식보다 코사인 유사도가 최대 67.2%까지 향상되었습니다. 다양한 언어 모델 구조에서도 일관된 성능 개선을 보였다고 연구진은 주장했습니다.", "evidence": "Experiments over noisy channels show up to a $67.2$\\% improvement in cosine similarity over context-only MLM reconstruction, with consistent gains across different MLM architectures and existing language-model-aided methods."}], "easy1_evidence": "Token transmission over conventional digital modulation is vulnerable to channel impairments, leading to bit errors that cause received tokens to become contextually inconsistent.", "easy2_evidence": "This paper proposes a receiver-side dual-stage channel-posterior integration framework for masked language model (MLM)-aided token reconstruction.", "topic_evidence": "This paper proposes a receiver-side dual-stage channel-posterior integration framework for masked language model (MLM)-aided token reconstruction.", "limit_evidence": ""}, "2611.18930": {"points": [{"subtitle": "벤치마크 활용의 괴리", "desc": "연구진이 인터뷰를 통해 확인한 결과, 개발자가 의도한 벤치마크의 유용성과 실제 배포된 시스템을 평가할 때 느끼는 유용성 사이에 차이가 컸어요. 즉, 벤치마크가 안전 평가의 핵심 도구로 쓰이고는 있지만 실제 현장의 요구사항을 충족하지 못하는 경우가 많다는 거예요.", "evidence": "We find a disconnect between perceptions of the intended usefulness of safety benchmarks and their practical usefulness in safety evaluations of deployed systems."}, {"subtitle": "평가 도구의 주요 난제", "desc": "개발자들은 크게 두 가지 어려움을 언급했는데요, 안전성 개념을 평가할 때 평가자마다 결과가 일치하지 않는 신뢰도 문제와 외부 타당성을 위협하는 요소들을 어떻게 다룰지 명확하지 않다는 점이에요. 이런 문제들이 벤치마크가 현장에서 제대로 쓰이지 못하게 만드는 원인으로 보입니다.", "evidence": "Our participants offered perspectives on two challenges contributing to this disconnect: (1) the difficulty of achieving inter-rater reliability on safety constructs, and (2) a lack of clarity regarding how to address persistent threats to external validity."}, {"subtitle": "현장 통합과 소통 강화", "desc": "연구진은 안전 벤치마크가 단순히 이론에 머물지 않고 실제 배포 환경에 뿌리를 내려야 한다고 주장했어요. 이를 위해 학계와 산업계의 AI 안전 관계자들이 서로 투명하게 소통할 수 있는 구체적인 경로를 마련해야 한다고 제안했습니다.", "evidence": "To facilitate this, we outline pathways for more transparent communication between academic and industry AI safety stakeholders."}], "easy1_evidence": "We find a disconnect between perceptions of the intended usefulness of safety benchmarks and their practical usefulness in safety evaluations of deployed systems.", "easy2_evidence": "Based on our analysis, we argue that safety benchmarks must not only be grounded in deployment contexts, but actively integrated with them.", "topic_evidence": "We present findings from five interviews with AI safety benchmark developers in academia and industry.", "limit_evidence": ""}, "2611.18908": {"points": [{"subtitle": "에이전트 행동 분석 도구", "desc": "연구진은 에이전트의 의사결정 과정을 추적하기 위해 신념-욕구-의도(BDI) 구조를 사용했어요. 이를 통해 에이전트가 상황을 어떻게 이해하고 무엇을 우선순위로 두는지, 또 유해성을 어떻게 인식하는지를 외부로 드러내어 진단할 수 있게 만든 겁니다.", "evidence": "Each decision is logged in a Belief-Desire-Intention (BDI) schema that we use as a diagnostic instrument, externalizing the agent's event understanding, declared priorities, and harm acknowledgment."}, {"subtitle": "유해성 탐지 모델 MemeAgent", "desc": "시뮬레이션에서 얻은 BDI 로그를 활용해 20억 개의 파라미터를 가진 MemeAgent라는 검증 모델을 학습시켰는데요. 이 모델은 기존의 제로샷(zero-shot) 검증 모델보다 훨씬 뛰어난 성능을 보였어요.", "evidence": "We further train MemeAgent, a 2B-parameter verifier on the simulation's BDI logs, which outperforms zero-shot frontier verifiers on in-distribution audits (97.5% vs. 63-74% accuracy on the Pass vs. Block decision) and generalizes to external multimodal harm benchmarks (78% vs. 50-56% on Hateful Memes)."}, {"subtitle": "탐지와 학습의 선순환", "desc": "흥미로운 점은 에이전트의 실패 사례를 찾아내는 데 쓴 바로 그 로그 데이터가, 역설적으로 그 실패를 잡아낼 모델을 학습시키는 데도 큰 도움이 되었다는 거예요. 즉, 에이전트의 취약점을 드러내는 기록이 곧 안전한 시스템을 만드는 열쇠가 된 셈입니다.", "evidence": "The same logs that surface the failure mode also help train the model that detects it."}], "easy1_evidence": "Alignment-trained large language model (LLM) agents are increasingly deployed in autonomous, multi-round settings where ethical compliance can come into direct tension with task success.", "easy2_evidence": "Across ten models from four frontier model families, harmful selection rates remain consistently high and rise by +15 percentage points on average under an economic survival incentive.", "topic_evidence": "We introduce MemeEconomy, a multimodal agentic market simulation in which LLM agents act as meme investors.", "limit_evidence": ""}, "2611.18891": {"points": [{"subtitle": "태스크 벡터 추출 및 분해", "desc": "VLA 모델과 VLM 모델의 가중치 차이를 태스크 벡터로 뽑아낸 뒤, 이를 특이값 분해를 통해 여러 성분으로 쪼갰어요. 이 과정은 모델의 핵심적인 변화 지점을 찾아내기 위한 단계라고 볼 수 있습니다.", "evidence": "Concretely, we extract the task vector (the difference between VLA and VLM weights) and decompose it via Singular Value Decomposition."}, {"subtitle": "혼합 계수 최적화", "desc": "쪼개진 각 성분에 대해 얼마나 VLA의 적응 능력을 유지할지 결정하는 스칼라 혼합 계수를 학습시켰는데요. 로봇의 행동 예측 능력과 언어 능력을 모두 잃지 않도록 균형을 맞추는 것이 핵심입니다.", "evidence": "For each component, we learn a scalar mixing coefficient controlling how much of the VLA adaptation is retained, optimised to jointly preserve action prediction and vision-language capabilities."}, {"subtitle": "성능 검증", "desc": "실험을 해 봤더니 연구진이 제안한 병합 모델이 행동 예측과 언어 능력 두 가지 측면에서 모두 좋은 결과를 보였어요. 기존의 모델 병합 방식들과 비교했을 때도 일관되게 더 나은 성능을 보여줬다고 연구진은 밝혔습니다.", "evidence": "Experiments show that our merged model performs well on both axes simultaneously, consistently outperforming established merging baselines."}], "easy1_evidence": "However, this fine-tuning induces catastrophic forgetting, substantially degrading the semantic and visual grounding capabilities of the original VLM.", "easy2_evidence": "Concretely, we extract the task vector (the difference between VLA and VLM weights) and decompose it via Singular Value Decomposition.", "topic_evidence": "We address this by merging the parameters of a VLM and its VLA derivative without retraining either model.", "limit_evidence": ""}, "2611.18642": {"points": [{"subtitle": "학습 효율 비교 실험", "desc": "혼자서 여덟 번의 생애를 거치며 전체 기록을 유지한 AI와, 각자 한 번의 생애만 살며 300자 쪽지를 이어받은 여덟 명의 AI 체인을 비교해 봤어요. 실험 결과, 여덟 세대가 지난 체인 방식의 AI는 혼자서 네 번의 생애를 거친 AI와 비슷한 수준의 학습 결과만 보였다는 거예요.", "evidence": "We compare one agent that plays eight lives and keeps its whole history with a chain of eight agents that each play one life and inherit a 300-character note."}, {"subtitle": "정보 손실 원인 분석", "desc": "손실의 원인을 쪼개서 분석해 봤더니, 에이전트가 바뀌는 것 자체는 문제가 아니었거든요. 정보를 300자로 압축하는 과정에서 작은 손실이 생기고, 이 압축이 반복되면서 더 큰 손실이 누적되는 구조라는 걸 알아냈습니다.", "evidence": "Controlled variants of the chain decompose this handoff loss into three components: none from changing the agent, a smaller loss from compressing to 300 characters, and a larger loss from compressing repeatedly."}, {"subtitle": "손실 회복의 한계", "desc": "전체 기록을 바탕으로 요약본을 다시 쓰게 하면 손실을 꽤 회복할 수 있지만, 여전히 완벽하지는 않다는 거예요. 연구진은 기록 방식을 바꾸거나 구조화된 장부를 쓰게 해도 이 정보 손실은 모델 크기와 상관없이 여전히 나타난다고 주장했어요.", "evidence": "The loss is robust across model sizes and is not alleviated by instructing the writer to record evidence, to revise the inherited note, or to keep a structured ledger."}], "easy1_evidence": "Evaluation has focused on whether an agent can solve a task, and relatively little is known about how much of what an agent has learned survives being written down.", "easy2_evidence": "When each note is written from the full record of earlier lives instead of from the previous note, the same 300 characters recover 70% to 82% of the loss.", "topic_evidence": "In simpler terms, an agent cannot hand over what it has not yet understood: a note holds what its writer has worked out, and a rule that takes several lives to see is lost with the lives that were not passed on.", "limit_evidence": ""}, "2611.11657": {"points": [{"subtitle": "거래 시스템 구조", "desc": "기업 뉴스 및 거시 경제 에이전트가 구조화된 보고서를 생성하면, 조정자가 이를 받아 최종적인 주식 비중과 현금 보유량을 결정합니다. 이 과정에서 규칙 기반의 실행 방식을 결합해 거래의 안정성을 확보했어요.", "evidence": "Company-news and macroeconomic agents return structured reports to a coordinator that sets stock weights and cash reserves."}, {"subtitle": "성과 및 위험 평가", "desc": "실제 브로커 기록이 있는 모의 계좌로 테스트한 결과, 34.5%의 수익률을 기록하며 SPY 펀드의 14.4%를 상회하는 성과를 보였습니다. 하지만 수익이 높은 만큼 최대 낙폭도 더 크게 나타나는 특징이 있어요.", "evidence": "This raw return advantage came with a larger maximum drawdown."}, {"subtitle": "설계 요소 비교", "desc": "현금 보유 권한이나 선택적 호출, 응답 계약 방식 등을 바꿔가며 시스템을 비교 분석했는데요. 현금을 일정하게 유지하는 방식이 상황에 따라 비중을 조절하는 것과 유사한 수익을 냈고, 보고서 계약을 짧게 줄이면 파싱은 잘 되지만 추천 내용이 바뀔 수 있다는 점을 발견했습니다.", "evidence": "A constant-cash control gives a return estimate close to stance-based sizing, and shorter report contracts improve observed parsing but can change recommendations."}], "easy1_evidence": "We built a hybrid multi-agent trading system that combines large language model (LLM) analysts with momentum-based portfolio construction and rule-based execution.", "easy2_evidence": "From March 11 to August 28, 2026, the account returned 34.5%, compared with 14.4% for the S&P 500 fund SPY over the same dates.", "topic_evidence": "We evaluate the portfolio engine using its broker-recorded paper account, which operated with deterministic fallbacks, and compare LLM-enabled configurations through retrospective replays.", "limit_evidence": ""}};
